window.__BOOK__={"meta":{"title_it":"Il Piccolo Principe","title_zh":"小王子","author_it":"Antoine de Saint-Exupéry","author_zh":"安托万·德·圣埃克苏佩里","voice":"it-IT-ElsaNeural (edge-tts)","ipa_note":"音标为宽式音位转写，仅供参考；重音未标注。","n_chapters":28,"n_paras":738,"n_sents":1574,"audio_paras":738},"chapters":[{"id":"ch00","title_it":"A LÉON WERTH","title_zh":"献词","paras":[{"id":"ch00p00","audio":true,"sents":[{"it":"Chiedo scusa ai bambini per aver dedicato questo libro a un adulto.","zh":"献给列昂·维尔特","t":[100,4112]},{"it":"Ho un buon motivo: questo adulto è il migliore amico che ho al mondo.","zh":"我请求孩子们原谅，我把这本书献给了一个大人。","t":[4112,8012]},{"it":"Ho un altro motivo: questo adulto può capire tutto, anche i libri per bambini.","zh":"这个大人——是我世界上最好的朋友。","t":[8012,13125]},{"it":"Ho un terzo motivo: questo adulto abita in Francia, dove ha fame e freddo.","zh":"还有另一个理由——他什么都懂，哪怕是写给孩子们看的书。","t":[13125,18500]},{"it":"Ha un gran bisogno di essere consolato.","zh":"我还有第三个理由——这个大人住在法国，在那里又饿又冷。","t":[18500,20888]},{"it":"Se tutti questi motivi non bastano, voglio dedicare il libro al bambino che questo adulto è stato molto tempo fa.","zh":"当然，得好好安慰他才是。","t":[20888,27488]},{"it":"Tutti gli adulti sono stati prima di tutto dei bambini.","zh":"因为所有大人曾经都是孩子，尽管没几个人记得这一点。","t":[27488,30925]},{"it":"(Ma pochi di loro se lo ricordano.) Quindi correggo la mia dedica: QUANDO ERA BAMBINO","zh":"所以我把这个题词改一改：献给小时候的列昂·维尔特。","t":[30925,36350]}]}]},{"id":"ch01","title_it":"I","title_zh":"第 1 章","paras":[{"id":"ch01p00","audio":true,"sents":[{"it":"Una volta, quando avevo sei anni, in un libro sulla foresta vergine intitolato Storie vissute ho visto un’illustrazione bellissima.","zh":"我六岁的时候，有一次在一本讲热带森林的书里看到一幅奇妙的画。","t":[100,8050]},{"it":"Raffigurava un serpente boa che divora una belva.","zh":"那本书叫《真实的故事》。","t":[8050,11162]},{"it":"Questa è una riproduzione del disegno.","zh":"画上画着一条正在吞食某只小野兽的蟒蛇。","t":[11162,13263]}]},{"id":"ch01p01","audio":true,"sents":[{"it":"Il libro diceva: “I serpenti boa divorano la preda tut­t’in­tera senza masticarla.","zh":"大致就是下面这个样子。","t":[100,5362]},{"it":"Dopo non riescono più a muoversi e passano i sei mesi della digestione dormendo”.","zh":"书里说，蟒蛇吞食猎物时是囫囵吞下、不加咀嚼的。","t":[5362,10225]}]},{"id":"ch01p02","audio":true,"sents":[{"it":"Allora ho pensato molto alle avventure della giungla e con una matita colorata sono riuscito anch’io a fare il mio primo disegno.","zh":"然后它们就动弹不得，要睡上六个月，直到把东西全部消化完。","t":[100,6750]},{"it":"Il mio disegno numero 1.","zh":"这是我的第一号作品。","t":[6750,8438]},{"it":"Era così:","zh":"它大致是这个样子。","t":[8438,9162]}]},{"id":"ch01p03","audio":true,"sents":[{"it":"Ho mostrato il mio capolavoro agli adulti e ho chiesto se era un disegno che faceva paura.","zh":"我把我的杰作拿给大人们看，问他们害不害怕。","t":[100,4937]}]},{"id":"ch01p04","audio":true,"sents":[{"it":"Tutti mi hanno risposto: “E perché mai un cappello dovrebbe fare paura?”.","zh":"他们却回答我说——一顶帽子有什么好怕的？","t":[100,4025]}]},{"id":"ch01p05","audio":true,"sents":[{"it":"Il mio disegno non raffigurava un cappello.","zh":"可是我画的并不是一顶帽子。","t":[100,2688]},{"it":"Raffigurava un serpente boa che digerisce un elefante.","zh":"那是一条正在消化大象的蟒蛇。","t":[2688,6125]},{"it":"Allora ho disegnato l’interno del serpente boa, in modo che gli adulti potessero capire.","zh":"于是为了让他们看明白，我又画了蟒蛇肚子里的情况。","t":[6125,11362]},{"it":"Hanno sempre bisogno di spiegazioni.","zh":"大人们嘛，凡事总得向他们解释个明白。","t":[11362,13750]},{"it":"Il mio disegno numero 2 era così:","zh":"我的第二号作品就是这样的。","t":[13750,15700]}]},{"id":"ch01p06","audio":true,"sents":[{"it":"Gli adulti mi hanno consigliato di lasciar perdere i disegni di serpenti boa aperti o chiusi e di interessarmi invece alla geografia, alla storia, all’aritmetica e alla grammatica.","zh":"可是大人们劝我别画蟒蛇了，不管是外面的还是里面的，还是去学地理、历史、算术和拼写吧。","t":[100,10712]},{"it":"È stato così che, all’età di sei anni, ho rinunciato a una brillante carriera di pittore, scoraggiato dall’insuccesso dei miei disegni numero 1 e numero 2.","zh":"就这样，六岁的我放弃了成为名画家的梦想。","t":[10712,19850]},{"it":"Gli adulti da soli non capiscono niente, ed è stancante per i bambini dover sempre spiegare tutto...","zh":"大人们自己什么也不懂，孩子们总得反反复复向他们解释，真是累人。","t":[19850,26150]}]},{"id":"ch01p07","audio":true,"sents":[{"it":"Perciò ho dovuto scegliermi un altro lavoro e ho imparato a pilotare gli aerei.","zh":"于是我只好另选了一种职业。","t":[100,4550]},{"it":"Ho volato un po’ in giro per il mondo.","zh":"我学会了驾驶飞机。","t":[4550,6612]},{"it":"E in effetti la geografia mi è stata utile.","zh":"我差不多飞遍了全世界。","t":[6612,9250]},{"it":"Sapevo distinguere al primo colpo d’occhio la Cina dall’Arizona.","zh":"所以说，地理知识还真帮了我忙。","t":[9250,12962]},{"it":"Torna comodo, se ti sei perso in piena notte.","zh":"我能一眼就分辨出中国和亚利桑那。","t":[12962,15700]}]},{"id":"ch01p08","audio":true,"sents":[{"it":"Così nella vita ho conosciuto molte persone serie.","zh":"夜里迷了路，这可派得上用场。","t":[100,3162]},{"it":"Ho frequentato parecchio gli adulti.","zh":"这一生里，我跟一大堆严肃的人打过交道。","t":[3162,5325]},{"it":"Li ho visti proprio da vicino.","zh":"我常常生活在大人中间。","t":[5325,7238]},{"it":"E la mia opinione non è cambiata.","zh":"我也常近距离地打量他们，尽管这并没有改善我对他们的看法。","t":[7238,9288]},{"it":"Quando ne incontravo uno che mi sembrava abbastanza sveglio, facevo l’esperimento del mio disegno numero 1, che conservo ancora.","zh":"每当我遇见一个看上去稍稍开窍的大人，我就在他身上做个试验。","t":[9288,16762]},{"it":"Volevo capire se era davvero veloce di comprendonio.","zh":"我想知道这个大人到底有多懂事。","t":[16762,19962]},{"it":"Ma tutti, invariabilmente, rispondevano: “È un cappello”.","zh":"可他总是回答我说，那是一顶帽子。","t":[19962,24562]},{"it":"Allora lasciavo perdere i serpenti boa, le foreste vergini e le stelle.","zh":"所以我也就不跟他说什么蟒蛇、热带森林或者星星了。","t":[24562,28988]},{"it":"Mi mettevo al suo livello.","zh":"我迁就他。","t":[28988,30638]},{"it":"Gli parlavo di bridge, di golf, di politica e di cravatte.","zh":"我跟他说桥牌，说高尔夫，说政治，说领带。","t":[30638,34575]},{"it":"E l’adulto era felicissimo di conoscere un uomo tanto ragionevole...","zh":"于是这个大人就很高兴，能结识我这样一个通情达理的人。","t":[34575,38224]}]}]},{"id":"ch02","title_it":"II","title_zh":"第 2 章","paras":[{"id":"ch02p00","audio":true,"sents":[{"it":"Così ho vissuto solo, senza nessuno con cui poter veramente parlare, finché sei anni fa non ho avuto un incidente nel deserto del Sahara.","zh":"后来我独自生活，连个能说真心话的人都没有。","t":[100,8125]},{"it":"Si era rotto qualcosa nel motore.","zh":"这种情况一直持续到六年前，我在撒哈拉沙漠上空出了事故。","t":[8125,10300]},{"it":"E siccome non avevo con me né un meccanico né passeggeri, decisi di riparare da solo quel brutto guasto.","zh":"飞机引擎里某个零件坏了。","t":[10300,16375]},{"it":"Era una questione di vita o di morte.","zh":"因为身边既没有机械师也没有乘客，我只好自己动手，对付这个棘手的故障。","t":[16375,18725]},{"it":"Avevo scorte di acqua solo per otto giorni.","zh":"我带的水不多——只够喝八天。","t":[18725,21087]}]},{"id":"ch02p01","audio":true,"sents":[{"it":"Perciò la prima sera mi sono addormentato sulla sabbia, a mille miglia da qualsiasi luogo abitato.","zh":"我带的水不多——只够喝八天。","t":[100,5875]},{"it":"Ero più isolato di un naufrago su una zattera in mezzo all’oceano.","zh":"第一天傍晚，我在离人烟千里之外的沙地上睡着了。","t":[5875,10050]},{"it":"Potete quindi immaginare la mia sorpresa quando, sul far del giorno, sono stato svegliato da una vocina che diceva:","zh":"我比一个在汪洋中筏子上遇了难的人还要孤独。","t":[10050,16775]}]},{"id":"ch02p02","audio":true,"sents":[{"it":"“Per favore...","zh":"所以，当黎明时分一个细细的嗓音把我唤醒时，您可想而知我有多惊讶。","t":[100,1112]},{"it":"disegnami una pecora!”","zh":"他说：——求求你……给我画一只小羊！","t":[1112,2550]}]},{"id":"ch02p03","audio":true,"sents":[{"it":"“Eh?”","zh":"——什么？","t":[100,450]}]},{"id":"ch02p04","audio":true,"sents":[{"it":"“Disegnami una pecora...”","zh":"——给我画一只小羊！","t":[100,1562]}]},{"id":"ch02p05","audio":true,"sents":[{"it":"Sono balzato in piedi come se fossi stato colpito da un fulmine.","zh":"——给我画一只小羊！","t":[100,4138]},{"it":"Mi sono sfregato gli occhi.","zh":"我腾地一下跳了起来，就像身边劈下一道闪电。","t":[4138,5938]},{"it":"Ho guardato bene.","zh":"我使劲揉了揉眼睛，朝四下里张望。","t":[5938,7175]},{"it":"E ho visto uno stranissimo ometto che mi fissava con aria seria.","zh":"我看见一个完全不寻常的小家伙，正一本正经地打量着我。","t":[7175,10875]},{"it":"Questo è il ritratto migliore che poi sono riuscito a farne.","zh":"这是我后来为他画的最满意的一幅肖像。","t":[10875,14238]}]},{"id":"ch02p06","audio":true,"sents":[{"it":"Ma ovviamente il mio disegno è molto meno bello dell’originale.","zh":"虽说画上的他不如本人那么好看。","t":[100,3900]},{"it":"Non è colpa mia.","zh":"不过这不能怪我。","t":[3900,5225]},{"it":"Quando avevo sei anni gli adulti mi avevano dissuaso dall’intraprendere la carriera di pittore, perciò non sapevo disegnare altro che i boa chiusi e i boa aperti.","zh":"要知道，我六岁那年，大人们就打消了我当画家的念头，除了外面和里面的蟒蛇，我什么都不会画。","t":[5225,13837]}]},{"id":"ch02p07","audio":true,"sents":[{"it":"Guardai quindi quell’apparizione con gli occhi sbarrati dallo stupore.","zh":"于是，我瞪大眼睛望着这个不可思议的小家伙。","t":[100,4038]},{"it":"Tenete presente che, come ho detto, mi trovavo a mille miglia da qualunque terra abitata.","zh":"于是，我瞪大眼睛望着这个不可思议的小家伙。","t":[4038,9488]},{"it":"E quell’ometto non sembrava essersi perso, né essere morto di stanchezza, né morto di fame, né morto di sete, né morto di paura.","zh":"别忘了——我当时可在离任何人烟千里之外的地方。","t":[9488,18012]},{"it":"Non aveva proprio l’aria di un bambino perso nel deserto, a mille miglia da qualsiasi terra abitata.","zh":"而这个小家伙，看起来既不像迷了路，也不像受了惊，更不像快要饿死或渴死的样子。","t":[18012,23850]},{"it":"Quando finalmente riuscii a parlare, gli dissi:","zh":"他完全不像一个在离人烟数百里的沙漠中央迷了路的孩子。","t":[23850,26850]}]},{"id":"ch02p08","audio":true,"sents":[{"it":"“Ma...","zh":"等我恢复了说话的能力，便问他：——可是……你在这儿干什么呢？","t":[100,750]},{"it":"Che ci fai tu qui?”","zh":"他却轻声而认真地把话重复了一遍：——求求你……给我画一只小羊！","t":[750,1688]}]},{"id":"ch02p09","audio":true,"sents":[{"it":"E allora mi ripeté piano, come fosse una cosa della massima importanza:","zh":"眼前这一切在我眼里是个解不开又令人震撼的谜，我不敢拒绝。","t":[100,4212]}]},{"id":"ch02p10","audio":true,"sents":[{"it":"“Per favore...","zh":"眼前这一切在我眼里是个解不开又令人震撼的谜，我不敢拒绝。","t":[100,1112]},{"it":"disegnami una pecora...”","zh":"尽管在离人烟千里、生死交界的地方，这显得多么不合时宜，我还是从口袋里掏出了纸和笔。","t":[1112,2537]}]},{"id":"ch02p11","audio":true,"sents":[{"it":"Dinanzi a un mistero assoluto, nessuno ha il coraggio di disobbedire.","zh":"不过我想起，我主要学的是地理、历史、算术和拼写。","t":[100,4450]},{"it":"Benché lì, a mille miglia da qualsiasi luogo abitato e in pericolo di morte, mi sembrasse una cosa del tutto strampalata, tirai fuori dalla tasca un foglio di carta e una stilografica.","zh":"于是我带着几分沮丧，对小家伙说我不会画画。","t":[4450,15588]},{"it":"Ma allora mi ricordai che avevo studiato soprattutto la geografia, la storia, l’aritmetica e la grammatica e (con un certo malumore) dissi all’ometto che non sapevo disegnare.","zh":"他却回答我说：——没关系。","t":[15588,26475]},{"it":"Lui mi rispose:","zh":"——画一只小羊吧。","t":[26475,27587]}]},{"id":"ch02p12","audio":true,"sents":[{"it":"“Non importa.","zh":"因为我从来没画过小羊，就给他重画了我会画的两幅画里的一幅——外面的蟒蛇。","t":[100,1250]},{"it":"Disegnami una pecora.”","zh":"当小家伙回答说——不，不！——时，我惊诧极了。","t":[1250,2650]}]},{"id":"ch02p13","audio":true,"sents":[{"it":"Siccome non avevo mai disegnato una pecora, rifeci per lui uno degli unici due disegni che sapevo fare.","zh":"——我不要蟒蛇肚子里的大象。","t":[100,6450]},{"it":"Quello del boa chiuso.","zh":"——我不要蟒蛇肚子里的大象。","t":[6450,7900]},{"it":"E con mio grande stupore udii l’ometto rispondermi:","zh":"——蟒蛇太危险，大象又太大了。","t":[7900,10787]}]},{"id":"ch02p14","audio":true,"sents":[{"it":"“No, no, non voglio un elefante dentro un boa.","zh":"——我家里的一切都特别小。","t":[100,3600]},{"it":"Il boa è pericolosissimo e l’elefante è troppo grosso.","zh":"——我要的是一只小羊。","t":[3600,7262]},{"it":"Il posto dove sto io è molto piccolo.","zh":"——给我画一只小羊吧。","t":[7262,9788]},{"it":"Mi serve una pecora.","zh":"于是我就给他画了一只。","t":[9788,11312]},{"it":"Disegnami una pecora.”","zh":"他仔细看了看，说：——不行。","t":[11312,12713]}]},{"id":"ch02p15","audio":true,"sents":[{"it":"Allora disegnai.","zh":"他仔细看了看，说：——不行。","t":[100,1187]}]},{"id":"ch02p16","audio":true,"sents":[{"it":"Lui guardò attentamente e poi:","zh":"——这只太弱不禁风了。","t":[100,2013]}]},{"id":"ch02p17","audio":true,"sents":[{"it":"“No!","zh":"——再画一只别的吧。","t":[100,788]},{"it":"Questa è troppo malconcia.","zh":"于是我又画了第二只小羊。","t":[788,2525]},{"it":"Fanne un’altra.”","zh":"我的新朋友宽厚地笑了笑。","t":[2525,3488]}]},{"id":"ch02p18","audio":true,"sents":[{"it":"Disegnai.","zh":"——你没看见吗？","t":[100,975]}]},{"id":"ch02p19","audio":true,"sents":[{"it":"Il mio amico fece un sorriso bonario e disse, paziente:","zh":"——这哪是小羊，是公羊嘛。","t":[100,3675]}]},{"id":"ch02p20","audio":true,"sents":[{"it":"“Ma no, lo vedi anche tu che non è una pecora, ma un ariete.","zh":"——它还有角呢……","t":[100,4225]},{"it":"Ha le corna...”","zh":"于是我又改画了一张。","t":[4225,4950]}]},{"id":"ch02p21","audio":true,"sents":[{"it":"Allora rifeci un’altra volta il disegno:","zh":"于是我又改画了一张。","t":[100,2375]}]},{"id":"ch02p22","audio":true,"sents":[{"it":"Ma, come i precedenti, fu rifiutato:","zh":"可他又像前面几只一样拒绝了：——这只小羊太老了。","t":[100,3112]}]},{"id":"ch02p23","audio":true,"sents":[{"it":"“Questa è troppo vecchia.","zh":"——我要的是能活很久很久的小羊。","t":[100,1612]},{"it":"Voglio una pecora che viva a lungo.”","zh":"这下我没了耐心，因为我得赶紧修我的引擎。","t":[1612,3500]}]},{"id":"ch02p24","audio":true,"sents":[{"it":"Poiché cominciavo a perdere la pazienza, e avevo fretta di smontare il motore, scarabocchiai questo disegno:","zh":"我胡乱画了下面这张，满不在乎地嘟囔道：","t":[100,6325]}]},{"id":"ch02p25","audio":true,"sents":[{"it":"E dissi:","zh":"——给你，这是个箱子。","t":[100,800]}]},{"id":"ch02p26","audio":true,"sents":[{"it":"“Questa è la cassa.","zh":"——你要的小羊就在里面待着呢。","t":[100,1412]},{"it":"E dentro c’è la pecora che vuoi tu.”","zh":"——你要的小羊就在里面待着呢。","t":[1412,3237]}]},{"id":"ch02p27","audio":true,"sents":[{"it":"Quale non fu il mio stupore nel vedere il viso del mio giovane giudice illuminarsi:","zh":"可是，当我看到我这位小批评家脸上顿时绽开光彩时，我惊讶极了：——这正是我想要的！","t":[100,4400]}]},{"id":"ch02p28","audio":true,"sents":[{"it":"“Ah, è proprio come la volevo!","zh":"——你说，这只小羊得吃很多草吗？","t":[100,2112]},{"it":"Pensi che a questa pecora occorra tanta erba?”","zh":"——怎么啦？","t":[2112,4450]}]},{"id":"ch02p29","audio":true,"sents":[{"it":"“Perché?”","zh":"——因为我家的一切都特别小……","t":[100,588]}]},{"id":"ch02p30","audio":true,"sents":[{"it":"“Perché il posto dove sto io è molto piccolo...”","zh":"——放心，它够吃的。","t":[100,2525]}]},{"id":"ch02p31","audio":true,"sents":[{"it":"“Sarà più che sufficiente.","zh":"——它本来就那么小嘛。","t":[100,1812]},{"it":"Ti ho dato una pecora piccola piccola.”","zh":"他俯下身去看那幅画。","t":[1812,3750]}]},{"id":"ch02p32","audio":true,"sents":[{"it":"Chinò il capo verso il disegno:","zh":"——也没那么小呀。","t":[100,1800]}]},{"id":"ch02p33","audio":true,"sents":[{"it":"“Mica tanto piccola...","zh":"——也没那么小呀。","t":[100,1662]},{"it":"Guarda!","zh":"——你瞧！","t":[1662,2500]},{"it":"Si è addormentata...”","zh":"——它睡着了。","t":[2500,3775]}]},{"id":"ch02p34","audio":true,"sents":[{"it":"E fu così che feci la conoscenza del piccolo principe.","zh":"就这样，我结识了小王子。","t":[100,3338]}]}]},{"id":"ch03","title_it":"III","title_zh":"第 3 章","paras":[{"id":"ch03p00","audio":true,"sents":[{"it":"Mi ci volle un bel po’ di tempo per capire da dove veniva.","zh":"我没能马上弄明白，他是从哪儿来的。","t":[100,3438]},{"it":"Il piccolo principe mi faceva moltissime domande, ma sembrava non ascoltare mai quelle che gli facevo io.","zh":"小王子问了我许多问题，却仿佛根本不听我问他的话。","t":[3438,9662]},{"it":"Solo alcune parole dette per caso mi hanno pian piano rivelato tutto.","zh":"不过，留意他偶然吐露的只言片语，我渐渐明白了是怎么回事。","t":[9662,13638]},{"it":"Così, quando vide per la prima volta il mio aereo (non lo disegno, è troppo difficile per me), mi domandò:","zh":"他第一次看到我的飞机时（我就不画它了——那幅画对我来说太难了），问我：——这是个什么玩意儿？","t":[13638,19913]}]},{"id":"ch03p01","audio":true,"sents":[{"it":"“Che roba è?”","zh":"——这不是玩意儿。","t":[100,688]}]},{"id":"ch03p02","audio":true,"sents":[{"it":"“Non è una roba.","zh":"——这不是玩意儿。","t":[100,1388]},{"it":"Vola, è un aereo.","zh":"——这是飞机。","t":[1388,3350]},{"it":"Il mio aereo.”","zh":"——它会飞。","t":[3350,4200]}]},{"id":"ch03p03","audio":true,"sents":[{"it":"Ed ero orgoglioso di fargli sapere che volavo.","zh":"——这是我的飞机。","t":[100,2750]},{"it":"Allora esclamò:","zh":"我得意地告诉他，我就是乘着它飞的。","t":[2750,3750]}]},{"id":"ch03p04","audio":true,"sents":[{"it":"“Ma come!","zh":"——是吗？","t":[100,1075]},{"it":"Sei caduto dal cielo?”","zh":"——这么说，你是从天上掉下来的？","t":[1075,2250]}]},{"id":"ch03p05","audio":true,"sents":[{"it":"“Sì,” feci io con modestia.","zh":"——是啊，——我谦逊地答道。","t":[100,1813]}]},{"id":"ch03p06","audio":true,"sents":[{"it":"“Ah, questa sì che è bella!...”","zh":"——啊……","t":[100,1813]}]},{"id":"ch03p07","audio":true,"sents":[{"it":"E il piccolo principe scoppiò in una gran risata che mi irritò molto.","zh":"——啊……","t":[100,4275]},{"it":"Voglio che si prendano sul serio le mie disgrazie.","zh":"——真有意思……","t":[4275,7188]},{"it":"Poi aggiunse:","zh":"小王子朗声大笑起来，这让我有点不快。","t":[7188,8113]}]},{"id":"ch03p08","audio":true,"sents":[{"it":"“Allora vieni anche tu dal cielo?","zh":"我觉得，对我这般绝境，该严肃对待才是。","t":[100,1950]},{"it":"Di che pianeta sei?”","zh":"接着他又说：——这么说，你也是从天上来的？","t":[1950,3200]}]},{"id":"ch03p09","audio":true,"sents":[{"it":"Di colpo scorsi una luce nel mistero della sua presenza, e subito gli domandai:","zh":"——那你是来自哪颗行星？","t":[100,4800]}]},{"id":"ch03p10","audio":true,"sents":[{"it":"“Quindi vieni da un altro pianeta?”","zh":"这时我开始猜到他来历的秘密，便直截了当地问他：——这么说是你从别的星球来的？","t":[100,1900]}]},{"id":"ch03p11","audio":true,"sents":[{"it":"Ma non mi rispose.","zh":"可他没有回答我。","t":[100,1450]},{"it":"Guardava l’aereo scuotendo piano la testa:","zh":"他只是摇了摇头，望着我的飞机说：——乘这个玩意儿，你恐怕飞不了多远吧……","t":[1450,3825]}]},{"id":"ch03p12","audio":true,"sents":[{"it":"“In effetti con quest’affare non puoi venire da molto lontano...”","zh":"他只是摇了摇头，望着我的飞机说：——乘这个玩意儿，你恐怕飞不了多远吧……","t":[100,3350]}]},{"id":"ch03p13","audio":true,"sents":[{"it":"E restò a lungo come trasognato.","zh":"他沉默下来，想了很久。","t":[100,2375]},{"it":"Poi tirò fuori dalla tasca la mia pecora e si immerse nella contemplazione del suo tesoro.","zh":"后来，他从口袋里掏出我画的那只小羊，端详起这份珍贵的礼物来。","t":[2375,7650]}]},{"id":"ch03p14","audio":true,"sents":[{"it":"Potete ben immaginare quanto mi incuriosisse quella mezza confidenza sugli “altri pianeti”.","zh":"您想想看，听到他提起别的星球，我有多么惊讶。","t":[100,5188]},{"it":"Cercai quindi di saperne di più:","zh":"于是我尽量多打听些这方面的事。","t":[5188,7087]}]},{"id":"ch03p15","audio":true,"sents":[{"it":"“Da dove vieni, ometto?","zh":"——那么，你是从哪儿来的呢，我的小家伙？","t":[100,2050]},{"it":"Qual è il posto dove stai?","zh":"——你说的“你家”在哪儿呀？","t":[2050,3762]},{"it":"Dove la vuoi portare la mia pecora?”","zh":"——你要把我的小羊带到哪儿去？","t":[3762,5576]}]},{"id":"ch03p16","audio":true,"sents":[{"it":"Dopo un silenzio pensoso mi rispose:","zh":"他沉默片刻，若有所思地答道：——还好你把它画在了箱子里。","t":[100,2437]}]},{"id":"ch03p17","audio":true,"sents":[{"it":"“C’è di buono che la cassa che mi hai dato di notte potrà farle da casa.”","zh":"——夜里它就可以睡在里面。","t":[100,3825]}]},{"id":"ch03p18","audio":true,"sents":[{"it":"“Certo.","zh":"——夜里它就可以睡在里面。","t":[100,1025]},{"it":"E se fai il bravo ti darò anche una corda per legarla durante il giorno.","zh":"——那当然。","t":[1025,5162]},{"it":"E un paletto.”","zh":"——你要是听话，我再给你画根绳子，白天好把它拴住。","t":[5162,6088]}]},{"id":"ch03p19","audio":true,"sents":[{"it":"Il piccolo principe sembrò scioccato dalla proposta:","zh":"——还有一根木桩。","t":[100,3163]}]},{"id":"ch03p20","audio":true,"sents":[{"it":"“Legarla?","zh":"可是，我这个提议似乎让小王子很不开心。","t":[100,1100]},{"it":"Che idea assurda!”","zh":"——拴住？","t":[1100,2250]}]},{"id":"ch03p21","audio":true,"sents":[{"it":"“Ma se non la leghi se ne andrà in giro chissà dove e si perderà.”","zh":"——多奇怪的念头！","t":[100,3700]}]},{"id":"ch03p22","audio":true,"sents":[{"it":"E di nuovo il mio amico scoppiò a ridere:","zh":"——可你要是不拴住它，它说不定会跑到哪儿去，走丢的……","t":[100,2213]}]},{"id":"ch03p23","audio":true,"sents":[{"it":"“Ma dove vuoi che vada?!”","zh":"这时我的小家伙又朗声笑了起来：——你以为它能跑到哪儿去呀？","t":[100,1312]}]},{"id":"ch03p24","audio":true,"sents":[{"it":"“Dove capita, prenderà la prima direzione che trova.”","zh":"这时我的小家伙又朗声笑了起来：——你以为它能跑到哪儿去呀？","t":[100,3226]}]},{"id":"ch03p25","audio":true,"sents":[{"it":"Allora il piccolo principe osservò, con aria seria:","zh":"——去哪儿都行……","t":[100,3326]}]},{"id":"ch03p26","audio":true,"sents":[{"it":"“Non importa, dove sto io è talmente piccolo!”","zh":"——随便哪儿吧。","t":[100,3000]}]},{"id":"ch03p27","audio":true,"sents":[{"it":"E aggiunse, forse con un’ombra di malinconia:","zh":"于是小王子十分认真地说：——没关系，反正我那儿地方小得很……","t":[100,2900]}]},{"id":"ch03p28","audio":true,"sents":[{"it":"“Qualunque direzione si prende, non si può andare molto lontano...”","zh":"接着他有点忧伤地补了一句：——就算一直往前走，也走不了多远。","t":[100,3826]}]}]},{"id":"ch04","title_it":"IV","title_zh":"第 4 章","paras":[{"id":"ch04p00","audio":true,"sents":[{"it":"Così avevo scoperto un’altra cosa molto importante: il pianeta da cui proveniva era poco più grande di una casa!","zh":"就这样，我了解到了第二件重要的事。","t":[100,6413]}]},{"id":"ch04p01","audio":true,"sents":[{"it":"Non mi stupiva.","zh":"他的星球，恐怕比一栋普通的房子大不了多少！","t":[100,1338]},{"it":"Sapevo che oltre ai pianeti maggiori come la Terra, Giove, Marte, Venere, a cui abbiamo dato dei nomi, ne esistono centinaia di altri che a volte sono così piccoli che quasi non si riesce neppure a vederli con il telescopio.","zh":"不过，这倒没怎么让我吃惊。","t":[1338,15575]},{"it":"Quando un astronomo ne scopre uno, lo designa con un numero.","zh":"我很清楚，在地球、木星、火星、金星这样的大行星之外，还有成百上千颗别的行星。","t":[15575,19288]},{"it":"Per esempio: “asteroide 325”.","zh":"其中有些小得很，用望远镜都很难看清。","t":[19288,22450]}]},{"id":"ch04p02","audio":true,"sents":[{"it":"Ho buoni motivi per credere che il pianeta da cui veniva il piccolo principe fosse l’asteroide B 612.","zh":"每当天文学家发现这样一颗小行星，","t":[100,5175]},{"it":"Questo asteroide è stato intravisto solo una volta, con il telescopio, nel 1909, da un astronomo turco.","zh":"他只给它一个编号，而不给名字。","t":[5175,14563]}]},{"id":"ch04p03","audio":true,"sents":[{"it":"Lo scienziato aveva presentato la sua scoperta a un congresso internazionale di astronomia.","zh":"比如，他管它叫“小行星 3251”。","t":[100,5512]},{"it":"Ma nessuno gli aveva creduto, per via del modo in cui era vestito.","zh":"我有充分的理由相信，小王子来自的那颗星球，就是 B-612 号小行星。","t":[5512,9675]},{"it":"Gli adulti sono fatti così.","zh":"这颗小行星，是一位土耳其天文学家在 1909 年第一次用望远镜观察到的。","t":[9675,11350]}]},{"id":"ch04p04","audio":true,"sents":[{"it":"Fu una vera fortuna, per la reputazione dell’asteroide B 612, quando un dittatore turco impose al proprio popolo, pena la morte, di vestirsi all’europea.","zh":"他还在国际天文学大会上，就这一发现做了长篇报告。","t":[100,11700]},{"it":"L’astronomo rifece la presentazione nel 1920, vestito con un completo elegante.","zh":"可是当时谁也不信他，因为他穿得太怪了。","t":[11700,16950]},{"it":"E stavolta tutti gli diedero retta.","zh":"大人哪，就是这么一种人。","t":[16950,18924]}]},{"id":"ch04p05","audio":true,"sents":[{"it":"Vi ho raccontato questi particolari sull’asteroide B 612 e vi ho rivelato il suo numero a causa degli adulti.","zh":"幸亏为了 B-612 号小行星，土耳其的君主下令臣民们，违者处死，必须改穿欧式服装。","t":[100,6962]},{"it":"Agli adulti piacciono i numeri.","zh":"到了 1920 年，那位天文学家重新做了一次报告。","t":[6962,8875]},{"it":"Quando raccontate loro di un nuovo amico, non vi chiedono mai le cose importanti.","zh":"这一回他穿得十分体面，大家就都同意他的说法了。","t":[8875,13538]},{"it":"Non vi dicono: “Com’è il suono della sua voce?","zh":"大人们喜欢数字。","t":[13538,16612]},{"it":"Quali sono i suoi giochi preferiti?","zh":"当你跟他们讲起一位新朋友，他们从来不问最要紧的事。","t":[16612,18812]},{"it":"Fa collezione di farfalle?”.","zh":"他们不会问他的嗓音好不好听，也不问爱玩什么游戏。","t":[18812,20575]},{"it":"Le loro domande sono: “Quanti anni ha?","zh":"他们不关心他喜欢什么，也不关心他是不是收集蝴蝶。","t":[20575,23188]},{"it":"Quanti fratelli?","zh":"他们只会问：他几岁了？","t":[23188,24362]},{"it":"Quanto pesa?","zh":"有几个兄弟？","t":[24362,25438]},{"it":"Quanto guadagna suo padre?”.","zh":"体重多少？","t":[25438,27138]},{"it":"Solo allora pensano di conoscerlo.","zh":"他父亲挣多少钱？","t":[27138,29375]},{"it":"Se dite agli adulti: “Ho visto una bella casa di mattoni rosa, con gerani alle finestre e colombi sul tetto...”, loro non riescono a immaginarsi la casa.","zh":"只有到这时候，他们才觉得算是了解他了。","t":[29375,38538]},{"it":"Dovete dire: “Ho visto una casa da centomila franchi”.","zh":"如果你对大人们说，你看见一所漂亮的红砖房子，窗台上有天竺葵，屋顶上停着鸽子，他们是没法想象出它的。","t":[38538,42238]},{"it":"Allora esclamano subito: “Oh, che bella!”.","zh":"你得对他们说，你看见的是一所值十万法郎的房子。","t":[42238,45000]}]},{"id":"ch04p06","audio":true,"sents":[{"it":"Quindi se dite: “Il piccolo principe è esistito perché era bellissimo, rideva e voleva una pecora.","zh":"这下他们就会赞叹道：“多漂亮啊！”","t":[100,6550]},{"it":"Se qualcuno vuole una pecora significa che esiste”, loro alzeranno le spalle e diranno che siete un bambino!","zh":"所以，如果你对他们说小王子存在，因为他与众不同，因为他会笑，还想要一只小羊（要知道，想要一只小羊，就证明你确实存在），他们只会耸耸肩，把你当成小孩子。","t":[6550,13162]},{"it":"Ma se proclamate: “Il pianeta da cui veniva è l’asteroide B 612”, allora si convinceranno e vi lasceranno in pace, senza farvi domande.","zh":"可如果你说他是乘着 B-612 号小行星来的，他们就会信以为真，不再拿这些问题来烦你。","t":[13162,22250]},{"it":"Sono fatti così.","zh":"大人们就是这么回事。","t":[22250,23562]},{"it":"Non bisogna prendersela.","zh":"因此，也犯不着为这个生他们的气。","t":[23562,25238]},{"it":"I bambini devono avere molta pazienza con gli adulti.","zh":"孩子们对大人，应当宽宏大量才是。","t":[25238,28237]}]},{"id":"ch04p07","audio":true,"sents":[{"it":"Noi però che capiamo la vita ce ne infischiamo dei numeri!","zh":"当然，懂得生活的人，是不在乎那些数字的。","t":[100,3612]},{"it":"Sarebbe stato bello cominciare questa storia come una favola.","zh":"我本想让这个故事，像一篇童话那样开头。","t":[3612,7038]},{"it":"Mi sarebbe piaciuto dire:","zh":"我本想这样写：“从前呀，有一位小王子。","t":[7038,8413]}]},{"id":"ch04p08","audio":true,"sents":[{"it":"“C’era una volta un piccolo principe che abitava su un pianeta poco più grande di lui e aveva bisogno di un amico...”.","zh":"他住在一颗只比他自己大一点点的星球上。","t":[100,6425]},{"it":"Per quelli che capiscono la vita, sarebbe sembrato molto più vero.","zh":"他需要一个朋友……”","t":[6425,10012]}]},{"id":"ch04p09","audio":true,"sents":[{"it":"Non mi piace, infatti, che il mio libro sia letto in maniera superficiale.","zh":"对于懂得生活的人，这样讲反倒更近乎真实。","t":[100,5025]},{"it":"È molto doloroso rievocare questi ricordi.","zh":"我一点也不希望人们把我的书，当作消遣来读。","t":[5025,7650]},{"it":"Sono passati ormai sei anni da quando il mio amico se n’è andato con la sua pecora.","zh":"讲述自己的回忆，对我来说是桩苦事。","t":[7650,12250]},{"it":"Se tento di descriverlo qui, è per non dimenticarlo.","zh":"要知道，我的朋友带着他的小羊离开我，已经六年了。","t":[12250,15812]},{"it":"È triste dimenticare un amico.","zh":"我在这里试着把他描述下来，只是怕自己把他忘了。","t":[15812,17812]},{"it":"Non tutti hanno avuto un amico.","zh":"要知道，忘掉一个朋友，是件叫人难过的事。","t":[17812,19675]},{"it":"E rischio di diventare come gli adulti, a cui interessano soltanto i numeri.","zh":"并不是每个人一生中都有过朋友。","t":[19675,24275]},{"it":"Per questo ho comprato una scatola di colori e delle matite.","zh":"我也可能变成那些只在乎数字的大人。","t":[24275,27775]},{"it":"Alla mia età è dura rimettersi a disegnare quando gli unici tentativi che hai fatto sono stati, a sei anni, un boa chiuso e un boa aperto!","zh":"到了我这把年纪，要重新学画画可真不容易，","t":[27775,35950]},{"it":"Ovviamente cercherò di fare ritratti più fedeli possibile.","zh":"尤其当初你六岁的时候，只试过两回——画外面的蟒蛇和里面的蟒蛇！","t":[35950,39488]},{"it":"Ma non sono sicuro di riuscirci.","zh":"不过，我当然会尽力画得像一些。","t":[39488,41812]},{"it":"Un disegno viene bene, e poi un altro non è somigliante.","zh":"虽说我一点也没把握能画好。","t":[41812,45638]},{"it":"A volte mi sbaglio anche con l’altezza.","zh":"这一幅画得还可以，那一幅就不大像……","t":[45638,47975]},{"it":"Qui il piccolo principe è troppo alto.","zh":"至于身材的高矮，我也拿不准。","t":[47975,50438]},{"it":"Lì è troppo basso.","zh":"这一张里小王子画得太大，那一张里又太小了。","t":[50438,51862]},{"it":"E sono incerto sul colore dei vestiti.","zh":"他衣服的颜色，我也说不准。","t":[51862,54412]},{"it":"Allora vado un po’ per tentativi, così e cosà, alla meno peggio.","zh":"只好凭感觉，东猜西猜——这边试试，那边碰碰。","t":[54412,58675]},{"it":"Finirà che sbaglierò qualche dettaglio cruciale.","zh":"最后，有些重要的细节，我也可能画错。","t":[58675,61588]},{"it":"Ma dovrete perdonarmi.","zh":"这一点，还请你们多多包涵。","t":[61588,63238]},{"it":"Il mio amico non dava mai spiegazioni.","zh":"我的这位朋友，从来没向我解释过什么。","t":[63238,65625]},{"it":"Forse mi credeva simile a lui.","zh":"大概他以为，我和他是一模一样的人。","t":[65625,67638]},{"it":"Purtroppo però io non sono capace di vedere le pecore attraverso le casse.","zh":"可遗憾的是，我不会隔着箱壁看见小羊。","t":[67638,72112]},{"it":"Forse sono un po’ come gli adulti.","zh":"也许，我多少有点像大人了。","t":[72112,74262]},{"it":"Devo essere invecchiato.","zh":"大概，我只是老了吧。","t":[74262,75625]}]}]},{"id":"ch05","title_it":"V","title_zh":"第 5 章","paras":[{"id":"ch05p00","audio":true,"sents":[{"it":"Ogni giorno scoprivo qualcosa sul pianeta, sulla partenza e sul viaggio.","zh":"每天，我都能从他那儿知道一点关于他星球和他旅程起点的新鲜事。","t":[100,4750]},{"it":"Saltava fuori tra una riflessione e l’altra.","zh":"他总是碰到机会，才零零碎碎地讲上一点。","t":[4750,7450]},{"it":"Fu così che il terzo giorno appresi il dramma dei baobab.","zh":"所以，关于猴面包树的那场灾难，我也是到第三天才知道的。","t":[7450,11050]}]},{"id":"ch05p01","audio":true,"sents":[{"it":"Anche stavolta fu grazie alla pecora, perché improvvisamente il piccolo principe mi domandò, come in preda a un grave dubbio:","zh":"而这件事，恰恰是因为那只小羊才弄明白的。","t":[100,7062]}]},{"id":"ch05p02","audio":true,"sents":[{"it":"“È vero, no, che le pecore mangiano gli arbusti?”","zh":"小王子想了很久，忽然问我：——小羊吃灌木，这是真的吧？","t":[100,3250]}]},{"id":"ch05p03","audio":true,"sents":[{"it":"“Sì, è vero.”","zh":"——是真的。","t":[100,1338]}]},{"id":"ch05p04","audio":true,"sents":[{"it":"“Ah, benissimo!”","zh":"——啊……那敢情好……","t":[100,1412]}]},{"id":"ch05p05","audio":true,"sents":[{"it":"Non capii perché fosse così importante che le pecore mangiassero gli arbusti.","zh":"我一时没明白，为什么羊吃灌木，对他这么要紧。","t":[100,4675]},{"it":"Ma il piccolo principe aggiunse:","zh":"可小王子又补了一句：——这么说，猴面包树它们也吃咯？","t":[4675,6525]}]},{"id":"ch05p06","audio":true,"sents":[{"it":"“Quindi mangiano anche i baobab?”","zh":"想到他的星球上有一队大象，小王子不禁笑了起来。","t":[100,1888]}]},{"id":"ch05p07","audio":true,"sents":[{"it":"Feci notare al piccolo principe che i baobab non sono arbusti, ma alberi alti come chiese, e che se anche avesse portato un intero branco di elefanti, il branco non sarebbe riuscito ad avere la meglio su un solo bao­bab.","zh":"——那可得把大象一只叠一只地摞起来才行。","t":[100,13200]}]},{"id":"ch05p08","audio":true,"sents":[{"it":"L’idea del branco di elefanti fece ridere il piccolo principe:","zh":"可他却很有见地地说：——可是猴面包树在长大之前，也曾经是小小的呀。","t":[100,3500]}]},{"id":"ch05p09","audio":true,"sents":[{"it":"“Bisognerebbe metterli uno sopra l’altro...”","zh":"——那倒是真的！","t":[100,2450]}]},{"id":"ch05p10","audio":true,"sents":[{"it":"Ma saggiamente osservò:","zh":"——可你为什么偏要你的小羊去吃那些小猴面包树呢？","t":[100,1412]}]},{"id":"ch05p11","audio":true,"sents":[{"it":"“All’inizio, prima di crescere, i baobab sono piccoli.”","zh":"他回答我时，那神情仿佛说的是明摆着的道理：——为什么？","t":[100,3738]}]},{"id":"ch05p12","audio":true,"sents":[{"it":"“Esatto!","zh":"——你自己想想嘛……","t":[100,1138]},{"it":"Ma perché mai le pecore dovrebbero mangiare i piccoli baobab?”","zh":"我可是费了好大脑筋，才弄明白问题出在哪儿。","t":[1138,4537]}]},{"id":"ch05p13","audio":true,"sents":[{"it":"Mi rispose: “Insomma, dai!”, come se fosse ovvio.","zh":"说真的，在小王子的星球上，就像在别的星球上一样，有用的植物中间，也长着杂草。","t":[100,4500]},{"it":"E dovetti fare un grande sforzo di intelligenza per venire da solo a capo del problema.","zh":"所以，土里既有好植物的好种子，也有坏植物的坏种子。","t":[4500,9675]}]},{"id":"ch05p14","audio":true,"sents":[{"it":"In effetti, come su ogni pianeta, sul pianeta del piccolo principe c’erano erbe buone ed erbe cattive.","zh":"不过，种子是瞧不大出来的。","t":[100,7125]},{"it":"Quindi semi buoni di erbe buone e semi cattivi di erbe cattive.","zh":"它们在地里守着各自的秘密沉睡，直到其中某一颗心血来潮，想要醒来。","t":[7125,11525]},{"it":"Ma i semi sono invisibili.","zh":"于是种子便抽出嫩芽。","t":[11525,13450]},{"it":"Dormono tutti nel segreto della terra finché a uno di loro non piglia il ghiribizzo di svegliarsi.","zh":"起初它怯生生地朝着太阳伸展，是那么迷人又无害。","t":[13450,19062]},{"it":"Allora si stiracchia e fa spuntare timidamente verso il sole uno splendido, innocuo germoglio.","zh":"若是萝卜或玫瑰的嫩芽，这话倒不假。","t":[19062,25438]},{"it":"Se è un germoglio di rapanello o di rosa, puoi lasciarlo crescere come gli pare.","zh":"那就由着它继续长去好了。","t":[25438,30100]},{"it":"Ma se ti rendi conto che è una pianta cattiva, devi strapparla immediatamente.","zh":"可要是杂草的芽，一认出来就得马上拔掉。","t":[30100,34788]},{"it":"Sul pianeta del piccolo principe c’erano alcuni semi terribili...","zh":"那是猴面包树的种子。","t":[34788,38762]},{"it":"ed erano i semi di baobab.","zh":"星球的整片土壤，都被它们污染了。","t":[38762,40638]},{"it":"Tutto il suolo del pianeta ne era infestato.","zh":"哪怕只放过一棵猴面包树，动手太晚，就再也没法摆脱它了。","t":[40638,43312]},{"it":"E se un baobab non lo strappi via subito, dopo non riesci più a liberartene.","zh":"它会占满整个星球，把根须扎进星球的每一处。","t":[43312,48250]},{"it":"Occupa tutto il pianeta.","zh":"要是星球太小，猴面包树又太多，它们干脆会把星球扯成碎片。","t":[48250,49925]},{"it":"Lo perfora con le radici.","zh":"所以，这是日常作息里非常重要的一条——小王子后来对我说。","t":[49925,52175]},{"it":"E se il pianeta è troppo piccolo e i baobab sono troppo numerosi, questi lo spaccano tutto.","zh":"早上把自己收拾停当之后，还得把星球也仔仔细细收拾一遍。","t":[52175,57600]}]},{"id":"ch05p15","audio":true,"sents":[{"it":"“È una questione di disciplina,” mi disse più tardi il piccolo principe.","zh":"得让自己养成习惯，定期把那些小猴面包树拔掉，只要你能把它们和幼苗期的玫瑰丛分辨开来——它们小时候可像了。","t":[100,4075]},{"it":"“Al mattino, finita la toilette, bisogna occuparsi della toilette del pianeta.","zh":"这活儿挺乏味，不过也挺简单。","t":[4075,9188]},{"it":"Appena distingui i baobab dalle piante di rose, cui somigliano molto quando sono giovani, li devi subito strappare.","zh":"有一回他劝我，尽量画一幅这样的画，好让我住处的孩子们能牢牢记住这件事。","t":[9188,16388]},{"it":"È un lavoro noiosissimo, ma molto semplice.”","zh":"“要是他们有一天出门远行，”他对我说，“这也许能帮上他们的忙。","t":[16388,19250]}]},{"id":"ch05p16","audio":true,"sents":[{"it":"E un giorno mi consigliò di provare a cimentarmi con un bel disegno per far entrare questo principio nella testa dei bambini di dove sto io.","zh":"有些活儿往后拖一拖，倒也无妨。","t":[100,7825]},{"it":"“Potrebbe essergli utile, se dovessero viaggiare.","zh":"可唯独猴面包树不行。","t":[7825,10725]},{"it":"In certi casi rimandare un lavoro non ha alcuna conseguenza.","zh":"不然就要闯大祸。","t":[10725,14400]},{"it":"Ma con i baobab è sempre un disastro.","zh":"我认识一颗星球，上面住着一个懒汉。","t":[14400,16962]},{"it":"Conoscevo un pianeta abitato da un pigro.","zh":"他对三棵小苗一直不理不睬……”","t":[16962,19500]},{"it":"Aveva trascurato tre arbusti...”","zh":"应小王子的请求，我把那颗星球画了下来。","t":[19500,21275]}]},{"id":"ch05p17","audio":true,"sents":[{"it":"Così, con le indicazioni del piccolo principe, ho disegnato quel pianeta.","zh":"我向来不爱教训人。","t":[100,5125]},{"it":"Non mi piace affatto prendere il tono del moralista.","zh":"我要说：“孩子们！","t":[5125,8262]},{"it":"Ma i baobab rappresentano un pericolo talmente sottovalutato, e i rischi di chi dovesse perdersi in un asteroide sono tali, che una volta tanto metto da parte ogni scrupolo.","zh":"当心猴面包树！”","t":[8262,18712]},{"it":"Dico: “Bambini!","zh":"我正是想以此提醒我那些年轻的朋友们，留意他们早已身处的危险。","t":[18712,20350]},{"it":"Fate attenzione ai baobab!”.","zh":"我自己也是画完这幅画，才察觉到这危险的。","t":[20350,22388]},{"it":"Se ho messo tutto il mio impegno in quel disegno è stato proprio per mettere in guardia i miei amici da un pericolo cui, come me, erano esposti da tempo senza saperlo.","zh":"这幅画，值得好好下一番功夫。","t":[22388,31825]},{"it":"Il messaggio che davo valeva lo sforzo.","zh":"也许你会问我——为什么这本书里，没有别的画能和这幅猴面包树的画一样气派？","t":[31825,34288]},{"it":"Vi domanderete: Perché in questo libro non ci sono altri disegni grandiosi come il disegno dei baobab?","zh":"答案很简单。","t":[34288,40512]},{"it":"La risposta è molto semplice: ci ho provato, ma non ci sono riuscito.","zh":"我也努力过，可就是画不出来。","t":[40512,45238]},{"it":"Quando ho disegnato i baobab, ero spinto dall’urgenza.","zh":"而当我画猴面包树时，鼓舞我的，是这件事本身的必要和紧迫。","t":[45238,48624]}]}]},{"id":"ch06","title_it":"VI","title_zh":"第 6 章","paras":[{"id":"ch06p00","audio":true,"sents":[{"it":"Ah!, piccolo principe, così ho pian piano capito come procedeva la tua vita malinconica.","zh":"啊，小王子！","t":[100,6125]},{"it":"Per molto tempo il tuo unico svago era stata la dolcezza dei tramonti.","zh":"我渐渐明白了，你为什么会那样忧伤。","t":[6125,10438]},{"it":"Ho scoperto questo ennesimo dettaglio il mattino del quarto giorno, quando mi hai detto:","zh":"你长久以来，只用那温柔的落日余晖来慰藉自己。","t":[10438,15276]}]},{"id":"ch06p01","audio":true,"sents":[{"it":"“A me piacciono molto i tramonti.","zh":"我是在","t":[100,2075]},{"it":"Andiamo a vedere un tramonto...”","zh":"我是在","t":[2075,3588]}]},{"id":"ch06p02","audio":true,"sents":[{"it":"“Ma bisogna aspettare...”","zh":"你生活中的这件新鲜事，是在第四天早晨得知的——那天你对我说：——我可喜欢看日落了。","t":[100,1513]}]},{"id":"ch06p03","audio":true,"sents":[{"it":"“Aspettare cosa?”","zh":"——走吧，去看日落……","t":[100,1075]}]},{"id":"ch06p04","audio":true,"sents":[{"it":"“Aspettare che il sole tramonti.”","zh":"——得等一会儿……","t":[100,1800]}]},{"id":"ch06p05","audio":true,"sents":[{"it":"Sulle prime sembravi molto stupito, poi hai riso di te stesso.","zh":"——等什么呀？","t":[100,4388]},{"it":"E mi hai detto:","zh":"——等到太阳开始落山呀。","t":[4388,5300]}]},{"id":"ch06p06","audio":true,"sents":[{"it":"“Credo sempre di essere da me!”","zh":"说这话时，你先是大觉意外，接着又自己笑起自己来。","t":[100,1612]}]},{"id":"ch06p07","audio":true,"sents":[{"it":"Infatti.","zh":"——我老觉得，自己还在家里呢。","t":[100,1262]},{"it":"Tutti sanno che quando negli Stati Uniti è mezzogiorno, in Francia è il tramonto.","zh":"——我老觉得，自己还在家里呢。","t":[1262,6712]},{"it":"Basterebbe poter andare in Francia in un minuto per veder tramontare il sole.","zh":"真的——当美洲是正午，全世界都知道，法兰西的太阳已经下山了。","t":[6712,11362]},{"it":"Purtroppo la Francia è molto lontana.","zh":"只要能在一分钟里赶到法兰西，就能亲眼看到这场日落。","t":[11362,13775]},{"it":"Ma sul tuo piccolissimo pianeta ti bastava spostare la sedia di qualche passo.","zh":"可惜法兰西太远了。","t":[13775,18350]},{"it":"E guardavi il crepuscolo ogni volta che volevi...","zh":"可在你的小星球上，只要把椅子挪上几步就够了。","t":[18350,20912]}]},{"id":"ch06p08","audio":true,"sents":[{"it":"“Un giorno ho visto il sole tramontare quarantaquattro volte!”","zh":"这样你就能随心所欲地看黄昏，看多久都行。","t":[100,3512]}]},{"id":"ch06p09","audio":true,"sents":[{"it":"E più tardi aggiungevi:","zh":"——有一天，我居然看了四十三次日落！","t":[100,1438]}]},{"id":"ch06p10","audio":true,"sents":[{"it":"“Sai...","zh":"——有一天，我居然看了四十三次日落！","t":[100,950]},{"it":"quando si è molto tristi si amano i tramonti...”","zh":"过了片刻你又补了一句：——你晓得吗，人一伤心，看日落就特别好……","t":[950,3462]}]},{"id":"ch06p11","audio":true,"sents":[{"it":"“Allora il giorno delle quarantaquattro volte eri proprio tanto triste?”","zh":"——这么说来，你看那四十三次日落的时候，心里特别难过咯？","t":[100,3638]}]},{"id":"ch06p12","audio":true,"sents":[{"it":"Ma il piccolo principe non rispose.","zh":"可小王子对这个问题，什么也没回答。","t":[100,2225]}]}]},{"id":"ch07","title_it":"VII","title_zh":"第 7 章","paras":[{"id":"ch07p00","audio":true,"sents":[{"it":"Il quinto giorno, sempre grazie alla pecora, mi fu rivelato il segreto della vita del piccolo principe.","zh":"小王子生活里的这个秘密，是我在第五天发现的，又是因为那只小羊。","t":[100,6300]},{"it":"Mi domandò bruscamente, di punto in bianco, come un interrogativo a lungo meditato in silenzio:","zh":"他忽然毫无来由地问我，仿佛这个问题已想了许久：——小羊既然吃灌木，那花是不是也吃？","t":[6300,12113]}]},{"id":"ch07p01","audio":true,"sents":[{"it":"“Una pecora, se mangia gli arbusti, mangia anche i fiori?”","zh":"——小羊碰到什么，就吃什么。","t":[100,3663]}]},{"id":"ch07p02","audio":true,"sents":[{"it":"“Una pecora mangia tutto quello che trova.”","zh":"——带刺的花也吃？","t":[100,2187]}]},{"id":"ch07p03","audio":true,"sents":[{"it":"“Anche i fiori con le spine?”","zh":"——对，带刺的也吃。","t":[100,1537]}]},{"id":"ch07p04","audio":true,"sents":[{"it":"“Sì.","zh":"——那刺呢？","t":[100,825]},{"it":"Anche i fiori con le spine.”","zh":"——那刺有什么用？","t":[825,2288]}]},{"id":"ch07p05","audio":true,"sents":[{"it":"“Allora le spine a cosa servono?”","zh":"这个我可不知道。","t":[100,1900]}]},{"id":"ch07p06","audio":true,"sents":[{"it":"Non lo sapevo.","zh":"这个我可不知道。","t":[100,1275]},{"it":"In quel momento ero tutto preso a svitare un bullone troppo stretto del motore.","zh":"再说我当时正忙着，想拧开发动机上一个拧不动的螺丝。","t":[1275,6138]},{"it":"Ero molto preoccupato perché il guasto cominciava a sembrarmi davvero serio e le scorte d’acqua che si riducevano mi facevano temere il peggio.","zh":"我心里很着急，因为故障看来相当严重。","t":[6138,13526]}]},{"id":"ch07p07","audio":true,"sents":[{"it":"“Le spine a cosa servono?”","zh":"我的饮用水快见底了，这让我往最坏处想。","t":[100,1576]}]},{"id":"ch07p08","audio":true,"sents":[{"it":"Il piccolo principe non rinunciava mai a una domanda dopo che l’aveva fatta.","zh":"——刺。","t":[100,4588]},{"it":"Ero contrariato dal bullone e risposi con la prima sciocchezza che mi passò per la mente:","zh":"——到底有什么用？","t":[4588,9226]}]},{"id":"ch07p09","audio":true,"sents":[{"it":"“Le spine non servono a niente, sono pura cattiveria da parte dei fiori!”","zh":"小王子一旦开了口问，就不会罢休。","t":[100,4350]}]},{"id":"ch07p10","audio":true,"sents":[{"it":"“Oh!”","zh":"那个拧不动的螺丝惹得我心烦，我便随口答道：——刺？","t":[100,562]}]},{"id":"ch07p11","audio":true,"sents":[{"it":"Ma dopo un attimo di silenzio sbottò, come risentito:","zh":"——它们一点用也没有。","t":[100,3737]}]},{"id":"ch07p12","audio":true,"sents":[{"it":"“Non ti credo!","zh":"——是花在使坏罢了。","t":[100,1312]},{"it":"I fiori sono deboli.","zh":"——噢！","t":[1312,2888]},{"it":"Sono ingenui.","zh":"可沉默了一分钟，他低声冲我嘟囔：——我才不信你的！","t":[2888,4112]},{"it":"Si fanno coraggio come possono.","zh":"——花是柔弱的。","t":[4112,6112]},{"it":"E con le spine pensano di mettere paura...”","zh":"——它们单纯。","t":[6112,8412]}]},{"id":"ch07p13","audio":true,"sents":[{"it":"Non risposi nulla.","zh":"——它们尽自己的力量保护自己。","t":[100,1538]},{"it":"In quel momento pensavo: “Se questo bullone non si allenta, lo faccio saltare con una martellata”.","zh":"——它们以为，仗着那些刺，自己就很厉害了……","t":[1538,7412]},{"it":"Il piccolo principe interruppe di nuovo le mie riflessioni:","zh":"——它们以为，仗着那些刺，自己就很厉害了……","t":[7412,10700]}]},{"id":"ch07p14","audio":true,"sents":[{"it":"“E tu credi che i fiori...”","zh":"我什么也没回答。","t":[100,1425]}]},{"id":"ch07p15","audio":true,"sents":[{"it":"“Ma no!","zh":"那一刻我对自己说：“这颗螺丝要是拧不开，我就用锤子把它砸出来。”","t":[100,875]},{"it":"Ma no!","zh":"可小王子又用一个问题把我岔开：——你难道觉得……","t":[875,1650]},{"it":"Non credo un bel niente!","zh":"——你以为花……","t":[1650,3500]},{"it":"Ho detto la prima cosa che capitava.","zh":"——不是啦！","t":[3500,5712]},{"it":"Ho faccende ben più serie a cui pensare, io!”","zh":"——不是！","t":[5712,8462]}]},{"id":"ch07p16","audio":true,"sents":[{"it":"Mi guardò stupefatto.","zh":"——我什么也没觉得。","t":[100,1563]}]},{"id":"ch07p17","audio":true,"sents":[{"it":"“Faccende ben più serie!”","zh":"——我刚才说的，你别管。","t":[100,1638]}]},{"id":"ch07p18","audio":true,"sents":[{"it":"Mi vedeva con il martello in mano, le dita nere di grasso, alle prese con un oggetto che a lui sembrava molto brutto.","zh":"——我正忙着正经事呢！","t":[100,6937]}]},{"id":"ch07p19","audio":true,"sents":[{"it":"“Parli come gli adulti!”","zh":"他惊讶地望了望我。","t":[100,1463]}]},{"id":"ch07p20","audio":true,"sents":[{"it":"Provai un po’ di vergogna.","zh":"——正经事？","t":[100,1788]},{"it":"Ma lui, implacabile, aggiunse:","zh":"他望着我——我手里握着锤子，手指上沾满油污，黑乎乎的。","t":[1788,4450]}]},{"id":"ch07p21","audio":true,"sents":[{"it":"“Confondi tutto...","zh":"我正俯身去对付那个在他看来丑陋的物件。","t":[100,1375]},{"it":"mescoli tutto!”","zh":"——你说话跟大人一模一样！","t":[1375,2338]}]},{"id":"ch07p22","audio":true,"sents":[{"it":"Era davvero molto irritato.","zh":"——你说话跟大人一模一样！","t":[100,1850]},{"it":"Scuoteva al vento i capelli dorati:","zh":"这话让我有点发窘，他却毫不留情地补了一句：——你全乱套了……","t":[1850,3862]}]},{"id":"ch07p23","audio":true,"sents":[{"it":"“Conosco un pianeta dove c’è un signore con la faccia paonazza.","zh":"——你什么也不懂！","t":[100,3825]},{"it":"Non ha mai annusato un fiore.","zh":"他这回是真生气了。","t":[3825,5625]},{"it":"Non ha mai guardato una stella.","zh":"他迎风抖了抖那一头金发：——我认识一颗星球，上面住着一位面色通红的先生。","t":[5625,7488]},{"it":"Non ha mai amato nessuno.","zh":"他从来不闻花香。","t":[7488,9188]},{"it":"Non ha mai fatto altro che addizioni.","zh":"他从来没抬头看过星星。","t":[9188,11425]},{"it":"E tutto il giorno ripete come te: ‘Sono un uomo serio!","zh":"他从来没爱过任何人。","t":[11425,15025]},{"it":"Sono un uomo serio!’ e questo lo riempie di orgoglio.","zh":"他只管算账。","t":[15025,18550]},{"it":"Ma non è un uomo, è un fungo!”","zh":"他整天像你一样，翻来覆去地说：“我是个正经人！","t":[18550,20687]}]},{"id":"ch07p24","audio":true,"sents":[{"it":"“Un cosa?”","zh":"我是个正经人！”","t":[100,787]}]},{"id":"ch07p25","audio":true,"sents":[{"it":"“Un fungo.”","zh":"说这话时，他得意得鼓胀起来。","t":[100,888]}]},{"id":"ch07p26","audio":true,"sents":[{"it":"Adesso il piccolo principe era pallido di rabbia.","zh":"可他哪里是人，简直是朵蘑菇！","t":[100,2863]}]},{"id":"ch07p27","audio":true,"sents":[{"it":"“Da milioni di anni i fiori mettono le spine.","zh":"——谁？","t":[100,2775]},{"it":"Da milioni di anni le pecore mangiano ugualmente i fiori.","zh":"——蘑菇！","t":[2775,6138]},{"it":"E non è forse una cosa seria cercare di capire perché i fiori si danno tanta pena per mettere spine che non servono a niente?","zh":"这一刻，小王子气得脸色发白。","t":[6138,12912]},{"it":"Non è forse importante la guerra delle pecore e dei fiori?","zh":"这一刻，小王子气得脸色发白。","t":[12912,16312]},{"it":"Non è forse più seria e importante delle addizioni di un signore grasso e rosso?","zh":"——花长刺，已经有几百万年了。","t":[16312,20962]},{"it":"E se io conosco un fiore unico al mondo, che esiste soltanto sul mio pianeta, e che una piccola pecora improvvisamente può distruggere, così, una mattina, senza neppure rendersene conto, non è forse importante?”","zh":"尽管几百万年来，羊一直在吃花。","t":[20962,34675]}]},{"id":"ch07p28","audio":true,"sents":[{"it":"Arrossì, poi continuò:","zh":"想弄明白，它们为何偏要长出那些毫无用处的刺，这难道不算正经？","t":[100,1975]}]},{"id":"ch07p29","audio":true,"sents":[{"it":"“Chi ama un fiore di cui esiste un solo esemplare fra milioni e milioni di stelle, basta che guardi le stelle e si sente felice.","zh":"羊和花之间这场没完没了的战争，难道不重要？","t":[100,7500]},{"it":"Può pensare: ‘Il mio fiore è lì da qualche parte...’.","zh":"这难道还比不上那位红脸先生的算账，重要、正经？","t":[7500,10638]},{"it":"Ma se la pecora mangia il fiore, è come se di colpo tutte le stelle si spegnessero!","zh":"如果我明知，世上独一无二、只长在我星球上的那朵花，会在某个清晨，被一只根本不懂自己在做什么的小羊轻易毁掉——这难道无关紧要？","t":[10638,15638]},{"it":"E ti sembra che questo non sia importante!”","zh":"他涨红了脸，接着说：——倘若你爱上了一朵花，它生长在千万颗星星之中，那么当你仰望星空时，这就足以让你感到幸福。","t":[15638,17950]}]},{"id":"ch07p30","audio":true,"sents":[{"it":"Non poté dire altro.","zh":"——你知道的——我的那朵花，就在那里的某处……","t":[100,1575]},{"it":"All’improvviso scoppiò in singhiozzi.","zh":"——可要是小羊把那朵花吃了，就好像所有的星星一下子都熄灭了！","t":[1575,4150]},{"it":"Era scesa la notte.","zh":"——这难道还不重要？！","t":[4150,5612]},{"it":"Avevo posato i miei utensili.","zh":"他再也说不出话，忽然放声大哭起来。","t":[5612,7512]},{"it":"Non mi importava niente del martello, del bullone, della sete e della morte.","zh":"夜幕降临了。","t":[7512,12400]},{"it":"Su una stella, su un pianeta, il mio, la Terra, c’era un piccolo principe da consolare!","zh":"我把手里的工具搁到一旁。","t":[12400,18938]},{"it":"Lo presi tra le braccia.","zh":"锤子、螺丝、口渴，甚至连死亡，对我都不再重要。","t":[18938,20688]},{"it":"Lo cullai.","zh":"在我的地球上，在一颗星星、一颗星球上，小王子在哭泣，得去安慰他才是。","t":[20688,21738]},{"it":"Gli dicevo: “Il fiore che ami non è in pericolo...","zh":"在我的地球上，在一颗星星、一颗星球上，小王子在哭泣，得去安慰他才是。","t":[21738,24838]},{"it":"Disegnerò una museruola per la tua pecora...","zh":"我把他抱在怀里，轻轻摇晃，对他说：“你那么心爱的花，平安无事。","t":[24838,27800]},{"it":"E per il tuo fiore disegnerò un’armatura...","zh":"我要给你的小羊画个嘴套。","t":[27800,30462]},{"it":"Io...”.","zh":"给你的花画一身铠甲……”","t":[30462,31188]},{"it":"Non sapevo cosa dire.","zh":"我实在不知道，该说些什么才好。","t":[31188,32712]},{"it":"Mi sentivo impacciato.","zh":"我觉得自己又笨又拙。","t":[32712,34350]},{"it":"Non sapevo come avvicinarmi a lui, dove trovare un accesso al suo cuore...","zh":"我不知道，怎样才能叩开他的心扉，走进他的灵魂……","t":[34350,38738]},{"it":"È talmente misterioso, il paese delle lacrime!","zh":"因为那泪水的国度，是如此难以捉摸，又如此神秘……","t":[38738,41825]}]}]},{"id":"ch08","title_it":"VIII","title_zh":"第 8 章","paras":[{"id":"ch08p00","audio":true,"sents":[{"it":"Presto imparai a conoscere meglio quel fiore.","zh":"不久，我对这朵花有了更多的了解。","t":[100,2675]},{"it":"Sul pianeta del piccolo principe c’erano sempre stati alcuni fiori molto semplici, con una sola raggiera di petali, che occupavano poco spazio e non disturbavano nessuno.","zh":"小王子的星球上，原本有许多朴素的小花，花瓣普普通通。","t":[2675,13100]},{"it":"Apparivano un mattino nell’erba e la sera morivano.","zh":"它们不占多少地方，也不招谁惹谁。","t":[13100,16362]},{"it":"Poi un giorno era spuntato quello, da un seme giunto da chissà dove, e il piccolo principe aveva tenuto d’occhio quel germoglio diverso da tutti gli altri.","zh":"清晨它们在草丛里绽放，到傍晚便凋谢了。","t":[16362,25450]},{"it":"Poteva essere un nuovo genere di baobab.","zh":"可那一朵，是从不知哪儿飘来的种子里长出来的；小王子仔仔细细地打量着这株与众不同的嫩芽。","t":[25450,28012]},{"it":"Ben presto però l’arbusto smise di crescere e cominciò a preparare un fiore.","zh":"没准儿，它是某一种新型猴面包树的芽呢。","t":[28012,32662]},{"it":"Il piccolo principe assisteva allo schiudersi di un enorme bocciolo e sentiva che ne sarebbe venuta un’apparizione miracolosa, ma la corolla indugiava, e si faceva bella, chiusa nella sua camera verde.","zh":"不过，这小灌木很快就不长了，眼看要开花。","t":[32662,44412]},{"it":"Con cura sceglieva i colori.","zh":"小王子眼看着一个大花苞长出来，料定奇迹就要出现；可那花躲在绿叶的庇护下，迟迟不肯展露芳容。","t":[44412,46288]},{"it":"Si vestiva piano, accomodando i petali a uno a uno.","zh":"仿佛它还在精心挑选将来的颜色。","t":[46288,49950]},{"it":"Non voleva uscire tutta stropicciata, come fanno i papaveri.","zh":"它慢条斯理地梳妆，一片花瓣、一片花瓣地舒展。","t":[49950,53750]},{"it":"Voleva mostrarsi solo nel pieno fulgore della propria bellezza.","zh":"它可不愿像什么罂粟似的，毛毛躁躁地就冒出来。","t":[53750,57688]},{"it":"Eh sì!","zh":"它要的是，以绝美的姿容隆重登场。","t":[57688,58538]},{"it":"Era molto vanitosa.","zh":"果然！","t":[58538,60012]},{"it":"La sua segreta toilette era durata giorni e giorni.","zh":"这朵花，可真够娇媚的。","t":[60012,63250]},{"it":"Ed ecco che una mattina, con il sorgere del sole, era apparsa una rosa.","zh":"它那神秘的筹备，日复一日地拖着。","t":[63250,67938]}]},{"id":"ch08p01","audio":true,"sents":[{"it":"Si era preparata con grande cura, e tuttavia disse sbadigliando:","zh":"终于有一天清晨，恰在日出时分，这位美人儿露面了。","t":[100,3738]}]},{"id":"ch08p02","audio":true,"sents":[{"it":"“Ah!","zh":"虽说它为出场费了长久又勤苦的功夫，可它打了个哈欠，开口便说：——啊！","t":[100,750]},{"it":"Mi sono svegliata proprio ora...","zh":"——我还没完全睡醒呢……","t":[750,2562]},{"it":"Scusatemi...","zh":"——请您原谅……","t":[2562,3650]},{"it":"Sono ancora tutta in disordine...”","zh":"——我这副模样，乱糟糟的……","t":[3650,5463]}]},{"id":"ch08p03","audio":true,"sents":[{"it":"Il piccolo principe non poté trattenere la propria ammirazione:","zh":"可小王子压不住心里的赞叹，喊道：——您太美了！","t":[100,3500]}]},{"id":"ch08p04","audio":true,"sents":[{"it":"“Come sei bella!”","zh":"——当真吗？","t":[100,1063]}]},{"id":"ch08p05","audio":true,"sents":[{"it":"“Eh sì,” rispose piano la rosa.","zh":"——她轻声说道。","t":[100,2075]},{"it":"“E sono nata insieme con il sole...”","zh":"——我可是和太阳一同出生的呀……","t":[2075,3913]}]},{"id":"ch08p06","audio":true,"sents":[{"it":"Il piccolo principe capì subito che non era granché modesta, ma era così toccante!","zh":"小王子明白，这花儿未免有点儿不知分寸，可它是那么惹人怜爱！","t":[100,5088]}]},{"id":"ch08p07","audio":true,"sents":[{"it":"“Credo sia ora di colazione,” aveva poi aggiunto, “saresti così gentile da pensare a me...”","zh":"——这会儿，该用早餐了吧，——美人儿紧接着说。","t":[100,4926]}]},{"id":"ch08p08","audio":true,"sents":[{"it":"E il piccolo principe, confuso, era andato a prendere un innaffiatoio pieno di acqua fresca e aveva servito la rosa.","zh":"——您会照应我的吧？","t":[100,7312]}]},{"id":"ch08p09","audio":true,"sents":[{"it":"Ben presto lei aveva cominciato a tormentarlo con la sua vanità un po’ ombrosa.","zh":"小王子又激动又局促，找来洒水壶，殷勤地伺候起花儿来。","t":[100,4862]},{"it":"Un giorno, per esempio, parlando delle sue quattro spine aveva detto al principe:","zh":"可没过多久，这位美人儿就用自己的担惊受怕和任性刁难，开始考验起小王子的耐心。","t":[4862,9825]}]},{"id":"ch08p10","audio":true,"sents":[{"it":"“Che vengano pure, le tigri, con i loro artigli!”","zh":"比如有一天，它谈起自己的四根刺，对他说：——没准儿，老虎会带着吓人的爪子闯到这儿来呢！","t":[100,3276]}]},{"id":"ch08p11","audio":true,"sents":[{"it":"“Sul mio pianeta non ci sono tigri,” aveva obiettato il principe, “e comunque le tigri non mangiano l’erba.”","zh":"——我的星球上没有老虎，——小王子反驳道。","t":[100,5862]}]},{"id":"ch08p12","audio":true,"sents":[{"it":"“Ma io non sono erba,” aveva risposto dolcemente la rosa.","zh":"——我的星球上没有老虎，——小王子反驳道。","t":[100,3238]}]},{"id":"ch08p13","audio":true,"sents":[{"it":"“Scusami...!”","zh":"——再说了，老虎不吃草。","t":[100,800]}]},{"id":"ch08p14","audio":true,"sents":[{"it":"“Non ho nessunissima paura delle tigri, ma ho il terrore delle correnti d’aria.","zh":"——我又不是草，——它小声答道。","t":[100,4612]},{"it":"Non avresti un paravento?”","zh":"——请您原谅……","t":[4612,6050]}]},{"id":"ch08p15","audio":true,"sents":[{"it":"“Il terrore delle correnti d’aria...","zh":"——老虎我倒是一点也不怕，可我顶怕穿堂风。","t":[100,2250]},{"it":"È una bella sfortuna, per una pianta,” aveva osservato il piccolo principe.","zh":"您这儿有屏风吗？","t":[2250,6925]},{"it":"“Questo fiore è proprio complicato...”","zh":"“想想看吧！","t":[6925,8787]}]},{"id":"ch08p16","audio":true,"sents":[{"it":"“La sera devi mettermi sotto una campana di vetro.","zh":"怕穿堂风！","t":[100,3262]},{"it":"Qui da te fa molto freddo.","zh":"没错，这朵花可不好伺候，”小王子心里暗暗拿定主意。","t":[3262,5038]},{"it":"È un posto proprio disagevole.","zh":"——傍晚您得用玻璃罩把我罩起来。","t":[5038,7062]},{"it":"Da dove vengo io...”","zh":"您这地方又冷又不舒服。","t":[7062,8124]}]},{"id":"ch08p17","audio":true,"sents":[{"it":"Ma la rosa si era interrotta.","zh":"我来的那个地方呀……","t":[100,2175]},{"it":"Era giunta lì sotto forma di seme.","zh":"可它说到这儿，突然住了口。","t":[2175,4425]},{"it":"Non poteva sapere nulla degli altri mondi.","zh":"它本是一粒种子飘到这颗星球上的，别的世界一概不知。","t":[4425,6850]},{"it":"Umiliata per essere stata sorpresa a inventare quella grossolana bugia, aveva tossito due o tre volte, per mettere il principe dalla parte del torto:","zh":"为了掩饰自己随口撒的那个小谎，它轻轻咳了几声，好让小王子觉得自己理亏。","t":[6850,15363]}]},{"id":"ch08p18","audio":true,"sents":[{"it":"“Allora, questo paravento?”","zh":"——那屏风到底在哪儿呀？","t":[100,1900]}]},{"id":"ch08p19","audio":true,"sents":[{"it":"“Stavo andando a prenderlo, ma tu mi parlavi!”","zh":"——我本要去拿，可您一直跟我说话来着！","t":[100,2762]}]},{"id":"ch08p20","audio":true,"sents":[{"it":"E la rosa aveva accentuato la tosse per farlo sentire in colpa.","zh":"于是它咳得更响，好让小王子更加过意不去。","t":[100,3650]}]},{"id":"ch08p21","audio":true,"sents":[{"it":"Così, nonostante la buona volontà del proprio amore, ben presto il piccolo principe aveva dubitato di lei.","zh":"尽管小王子真心爱着这朵花，心里却还是生出了几分疑惑。","t":[100,6612]},{"it":"Aveva preso sul serio parole senza importanza, ed era diventato molto infelice.","zh":"他把花儿那些空洞的话当了真，为此受尽了折磨。","t":[6612,11588]}]},{"id":"ch08p22","audio":true,"sents":[{"it":"“Non avrei dovuto ascoltarla,” mi confidò un giorno, “non bisogna mai ascoltare i fiori.","zh":"“我不该去听它的，”他后来对我坦白说。","t":[100,5200]},{"it":"Bisogna guardarli e annusarli.","zh":"——花儿说的话，不必去听。","t":[5200,7362]},{"it":"La mia rosa profumava tutto il pianeta, ma io non sapevo gioirne.","zh":"该欣赏它们，该去闻它们的芬芳。","t":[7362,11462]},{"it":"La storia degli artigli, che mi aveva così irritato, avrebbe dovuto intenerirmi...”","zh":"我的美人儿把整颗星球熏得香喷喷的，可我偏不会为此欢喜。","t":[11462,16400]}]},{"id":"ch08p23","audio":true,"sents":[{"it":"E mi confidò ancora:","zh":"那桩老虎爪子的事，本叫我那么光火，我早该警觉才是……”","t":[100,1387]}]},{"id":"ch08p24","audio":true,"sents":[{"it":"“Non ho capito niente!","zh":"他还对我吐露了另一桩心事：“那时我什么也不懂！","t":[100,1688]},{"it":"Avrei dovuto giudicarla dalle sue azioni e non dalle sue parole.","zh":"我本该看它的行动，而不是听它的言语。","t":[1688,5338]},{"it":"Mi profumava e mi illuminava.","zh":"它把芬芳赠予我，照亮了我的生活。","t":[5338,7312]},{"it":"Non avrei mai dovuto andarmene!","zh":"我不该一走了之！","t":[7312,9275]},{"it":"Avrei dovuto intuire l’affetto che stava dietro i suoi poveri trucchi.","zh":"我本该在它的耍小性子里，看出那份温柔与娇弱。","t":[9275,13100]},{"it":"I fiori sono così contraddittori!","zh":"花儿的心思，就是这么矛盾！","t":[13100,15450]},{"it":"Ma ero troppo giovane per saperla amare.”","zh":"可我那时太不懂事，还不晓得怎样去爱它。”","t":[15450,17650]}]}]},{"id":"ch09","title_it":"IX","title_zh":"第 9 章","paras":[{"id":"ch09p00","audio":true,"sents":[{"it":"Credo che per la sua fuga approfittò di una migrazione di uccelli selvatici.","zh":"我想，他是搭迁徙的候鸟，才逃离了星球。","t":[100,4825]},{"it":"Il mattino della partenza rassettò per bene il pianeta.","zh":"临走前的那个清晨，他把星球仔仔细细地收拾了一遍。","t":[4825,8400]},{"it":"Pulì con cura i vulcani attivi.","zh":"他把活火山的火山口疏通了。","t":[8400,10562]},{"it":"Ne possedeva due.","zh":"他星球上，有两座这样的火山。","t":[10562,12038]},{"it":"Ed erano molto comodi per scaldare la colazione.","zh":"每天早晨，借着它们热早饭，可方便啦。","t":[12038,15000]},{"it":"Possedeva anche un vulcano spento.","zh":"其中一座是死火山，可小王子常对自己说：“谁知道什么时候用得着呢。”","t":[15000,17325]},{"it":"Ma, come diceva lui: “Non si sa mai!”.","zh":"所以，死火山他也照样疏通了。","t":[17325,20212]},{"it":"Quindi pulì anche il vulcano spento.","zh":"因为火山疏通得好，就会安安静静、均匀地运转，不会喷发。","t":[20212,22700]},{"it":"Se sono tenuti puliti, i vulcani bruciano piano e in maniera uniforme, senza eruzioni.","zh":"火山喷发嘛，就像烟囱里迸出的火星。","t":[22700,28538]},{"it":"Le eruzioni vulcaniche sono come i fuochi nel caminetto.","zh":"可惜在我们地球上，人太小了，没法疏通自己的火山。","t":[28538,32075]},{"it":"Naturalmente sulla Terra siamo troppo piccoli per pulire i vulcani.","zh":"正因如此，火山才常常惹出那么多麻烦。","t":[32075,36100]},{"it":"Per questo ci causano tanti problemi.","zh":"小王子还带着几分不舍，把最后几株猴面包树的嫩芽也拔掉了。","t":[36100,38200]}]},{"id":"ch09p01","audio":true,"sents":[{"it":"Con un po’ di malinconia, il piccolo principe strappò anche gli ultimi germogli di baobab.","zh":"他想着，自己不会再回到这儿来了。","t":[100,5738]},{"it":"Pensava che non sarebbe mai più tornato.","zh":"那天清晨，这桩习惯了的活计，叫他觉得格外舒心。","t":[5738,8162]},{"it":"Ma quella mattina tutti i lavori consueti gli parvero molto piacevoli.","zh":"当他最后一次给花浇了水，正要把它罩进玻璃罩里时，他几乎要哭出来了。","t":[8162,12588]},{"it":"E quando innaffiò un’ultima volta la rosa, e si accinse a metterla sotto la campana, scoprì di aver voglia di piangere.","zh":"——再见，——他对花儿说。","t":[12588,19500]}]},{"id":"ch09p02","audio":true,"sents":[{"it":"“Addio,” le disse.","zh":"可花儿没有回答他。","t":[100,1287]}]},{"id":"ch09p03","audio":true,"sents":[{"it":"Ma lei non gli rispose.","zh":"——再见，——他又说了一遍。","t":[100,1538]}]},{"id":"ch09p04","audio":true,"sents":[{"it":"“Addio,” ripeté.","zh":"美人儿轻轻咳了一声。","t":[100,1100]}]},{"id":"ch09p05","audio":true,"sents":[{"it":"La rosa tossì.","zh":"当然，这可不是因为感冒。","t":[100,1425]},{"it":"Ma non era a causa del raffreddore.","zh":"——我从前真傻，——它终于开口说。","t":[1425,3462]}]},{"id":"ch09p06","audio":true,"sents":[{"it":"“Sono stata sciocca,” gli disse infine.","zh":"——原谅我吧，你要尽量过得快活。","t":[100,2488]},{"it":"“Ti chiedo scusa.","zh":"小王子很诧异，竟没听到一句责备。","t":[2488,3712]},{"it":"Cerca di essere felice.”","zh":"他愣住了，手里还端着玻璃罩，一时不知所措。","t":[3712,5087]}]},{"id":"ch09p07","audio":true,"sents":[{"it":"Lo stupì l’assenza di rimproveri.","zh":"他没料到，它会这么温柔。","t":[100,2325]},{"it":"Se ne stava lì, tutto sottosopra, con la campana di vetro in mano.","zh":"他没料到，它会这么温柔。","t":[2325,6762]},{"it":"Non capiva quella dolcezza tranquilla.","zh":"——哼，我当然是爱你的，——花儿对他说。","t":[6762,8900]}]},{"id":"ch09p08","audio":true,"sents":[{"it":"“Insomma, io ti amo,” gli disse la rosa.","zh":"——你不知道这一点，是我的不是。","t":[100,2900]},{"it":"“E per colpa mia non l’hai capito.","zh":"不过现在这都不打紧了。","t":[2900,4775]},{"it":"Non importa.","zh":"你和我一样傻。","t":[4775,5925]},{"it":"Ma sei stato stupido quanto me.","zh":"愿你快乐。","t":[5925,7950]},{"it":"Cerca di essere felice...","zh":"把那个罩子扔一边去吧。","t":[7950,9662]},{"it":"Lascia stare quella campana, non la voglio più.”","zh":"我再也用不着它了。","t":[9662,12250]}]},{"id":"ch09p09","audio":true,"sents":[{"it":"“Ma il vento...”","zh":"——那穿堂风呢？","t":[100,1062]}]},{"id":"ch09p10","audio":true,"sents":[{"it":"“Non sono poi così raffreddata...","zh":"——我还没那么容易伤风。","t":[100,2112]},{"it":"L’aria fresca della notte mi farà bene.","zh":"夜里的新鲜空气，对我有好处。","t":[2112,4512]},{"it":"In fondo, sono un fiore.”","zh":"我好歹是朵花呀。","t":[4512,6150]}]},{"id":"ch09p11","audio":true,"sents":[{"it":"“Ma gli animali...”","zh":"——那猛兽呢？","t":[100,1012]}]},{"id":"ch09p12","audio":true,"sents":[{"it":"“Devo pur sopportare due o tre bruchi se voglio conoscere le farfalle.","zh":"——要是我还想结识蝴蝶，挨上两三条毛毛虫，倒也不坏。","t":[100,4225]},{"it":"Pare che siano bellissime.","zh":"听说，蝴蝶美极了。","t":[4225,5950]},{"it":"Altrimenti chi mi verrà a trovare?","zh":"不然，谁来探望我呢？","t":[5950,8062]},{"it":"Tu sarai lontano.","zh":"你可是要远走他乡了。","t":[8062,9400]},{"it":"Quanto alle bestie grandi, non ho paura.","zh":"至于猛兽，我一点也不怕。","t":[9400,12125]},{"it":"Ho i miei artigli.”","zh":"我自有我的爪子呢。","t":[12125,13262]}]},{"id":"ch09p13","audio":true,"sents":[{"it":"E mostrava ingenuamente le sue quattro spine.","zh":"说着，它天真地亮了亮自己的四根刺。","t":[100,2888]},{"it":"Poi aggiunse:","zh":"接着它又说：——行了，别磨蹭！","t":[2888,3813]}]},{"id":"ch09p14","audio":true,"sents":[{"it":"“Non tirarla tanto per le lunghe, che è seccante.","zh":"真叫人受不了！","t":[100,3375]},{"it":"Hai deciso di partire, e allora vai.”","zh":"既然你拿定主意要走，那就走吧！","t":[3375,5600]}]},{"id":"ch09p15","audio":true,"sents":[{"it":"Non voleva che lui la vedesse piangere.","zh":"它不愿让他看见自己眼泪汪汪的样子。","t":[100,2438]},{"it":"Era un fiore talmente orgoglioso...","zh":"因为，这是一朵骄傲的花。","t":[2438,4437]}]}]},{"id":"ch10","title_it":"X","title_zh":"第 10 章","paras":[{"id":"ch10p00","audio":true,"sents":[{"it":"Lui si trovava nella regione degli asteroidi 325, 326, 327, 328, 329 e 330.","zh":"小王子来到 325、326、327、329、330 这几颗小行星附近。","t":[100,10038]},{"it":"Decise quindi di visitarli per cercarvi un’occupazione e per istruirsi.","zh":"他决定去拜访它们，好让自己有事做，也学点东西。","t":[10038,16062]}]},{"id":"ch10p01","audio":true,"sents":[{"it":"Il primo era abitato da un re.","zh":"第一颗小行星上，住着一位国王。","t":[100,2088]},{"it":"Il re sedeva vestito di porpora e di ermellino su un trono semplicissimo e tuttavia maestoso.","zh":"他披着白鼬皮镶边的紫红色袍子，坐在一张简朴而又威严的宝座上。","t":[2088,7424]}]},{"id":"ch10p02","audio":true,"sents":[{"it":"“Ah!","zh":"——啊！","t":[100,750]},{"it":"Ecco un suddito,” esclamò il re quando scorse il piccolo principe.","zh":"我的臣民来了！","t":[750,4625]}]},{"id":"ch10p03","audio":true,"sents":[{"it":"E il piccolo principe si domandò:","zh":"——国王一眼瞥见小王子，叫出声来。","t":[100,1963]}]},{"id":"ch10p04","audio":true,"sents":[{"it":"“Come fa a riconoscermi se non mi ha mai visto?”","zh":"他可一次也没见过我呀！”","t":[100,2462]}]},{"id":"ch10p05","audio":true,"sents":[{"it":"Non sapeva che per i re il mondo è alquanto semplificato.","zh":"小王子不知道，在国王们眼里，世界安排得挺简单。","t":[100,3875]},{"it":"Tutti gli uomini sono sudditi.","zh":"因为对他们来说，所有人都是臣民。","t":[3875,5600]}]},{"id":"ch10p06","audio":true,"sents":[{"it":"“Avvicinati, che ti voglio vedere meglio,” gli disse il re, tutto fiero di essere finalmente il re di qualcuno.","zh":"——走近一些，让我好好瞧瞧你，——国王对他说。","t":[100,6387]}]},{"id":"ch10p07","audio":true,"sents":[{"it":"Il piccolo principe cercò con gli occhi dove sedersi, ma il pianeta era tutto occupato dallo splendido mantello di ermellino.","zh":"他终于成了某个人的君主，得意极了。","t":[100,7575]},{"it":"Quindi rimase in piedi e, poiché era stanco, sbadigliò.","zh":"小王子拿眼睛找地方坐，可整颗星球都被国王那件华丽的白鼬皮袍子占满了。","t":[7575,11338]}]},{"id":"ch10p08","audio":true,"sents":[{"it":"“È contrario all’etichetta sbadigliare in presenza di un re,” gli disse il monarca.","zh":"他只好站着，又因为累，打了个哈欠。","t":[100,4562]},{"it":"“Te lo proibisco.”","zh":"——当着国王的面打哈欠，这可大违礼法，——君王对他说。","t":[4562,5576]}]},{"id":"ch10p09","audio":true,"sents":[{"it":"“Non posso evitarlo,” rispose il piccolo principe, imbarazzato.","zh":"——我禁止你这样做。","t":[100,4362]},{"it":"“Ho fatto un lungo viaggio e non ho dormito...”","zh":"——可我忍不住要打哈欠，——小王子窘得答道。","t":[4362,6474]}]},{"id":"ch10p10","audio":true,"sents":[{"it":"“Allora,” gli disse il re, “ti ordino di sbadigliare.","zh":"——我走了那么远的路，好久没合眼了。","t":[100,3512]},{"it":"Sono anni che non vedo nessuno sbadigliare.","zh":"——那么，——国王说，——我命令你打哈欠。","t":[3512,6100]},{"it":"E per me gli sbadigli sono vere e proprie curiosità.","zh":"我多年没见人打哈欠了。","t":[6100,9412]},{"it":"Forza!","zh":"来吧！","t":[9412,10300]},{"it":"Sbadiglia di nuovo.","zh":"再打一个。","t":[10300,11712]},{"it":"È un ordine.”","zh":"这是命令！","t":[11712,12487]}]},{"id":"ch10p11","audio":true,"sents":[{"it":"“Mi mette soggezione...","zh":"——我打不出来了，——小王子涨红了脸，局促起来。","t":[100,1688]},{"it":"non riesco...” fece il piccolo principe arrossendo.","zh":"——是吗？","t":[1688,4788]}]},{"id":"ch10p12","audio":true,"sents":[{"it":"“Hum!","zh":"——国王答道。","t":[100,838]},{"it":"Hum!” rispose il re.","zh":"——那我就……","t":[838,2925]},{"it":"“Allora...","zh":"我命令你打哈欠，不然……","t":[2925,3788]},{"it":"allora ti ordino di sbadigliare e poi di non...”","zh":"他嘟嘟囔囔，显得有些慌乱。","t":[3788,6600]}]},{"id":"ch10p13","audio":true,"sents":[{"it":"Farfugliava e sembrava indispettito.","zh":"对国王来说，最要紧的是不失威严。","t":[100,2362]}]},{"id":"ch10p14","audio":true,"sents":[{"it":"Al re infatti stava molto a cuore che la sua autorità fosse rispettata.","zh":"他容不得半点违拗。","t":[100,4312]},{"it":"Non tollerava la disobbedienza.","zh":"他是个专制的君主。","t":[4312,6388]},{"it":"Era un monarca assoluto.","zh":"不过他心地善良，只下合乎情理的命令。","t":[6388,8050]},{"it":"Ma poiché era buono, dava ordini ragionevoli.","zh":"那错在我自己。”","t":[8050,10863]}]},{"id":"ch10p15","audio":true,"sents":[{"it":"“Se ordinassi,” diceva abitualmente, “se ordinassi a un generale di trasformarsi in un uccello marino, e se il generale non obbedisse, non sarebbe colpa del generale.","zh":"——我能坐下吗？","t":[100,10075]},{"it":"Sarebbe colpa mia.”","zh":"——小王子怯生生地问。","t":[10075,11176]}]},{"id":"ch10p16","audio":true,"sents":[{"it":"“Posso sedermi?” domandò timidamente il piccolo principe.","zh":"——我命令你坐下，——国王撩起白鼬皮袍子的下摆，答道。","t":[100,3737]}]},{"id":"ch10p17","audio":true,"sents":[{"it":"“Ti ordino di sederti,” gli rispose il re, tirando cerimoniosamente a sé un lembo del mantello di ermellino.","zh":"可小王子来了兴致：这么小一颗星球，能统治些什么呢？","t":[100,6237]}]},{"id":"ch10p18","audio":true,"sents":[{"it":"Ma il piccolo principe era perplesso.","zh":"——陛下，——他对国王说，——恕我斗胆一问……","t":[100,2538]},{"it":"Il pianeta era minuscolo.","zh":"——我命令你尽管问！","t":[2538,4300]},{"it":"Su cosa poteva mai regnare il re?","zh":"——国王抢着说。","t":[4300,6187]}]},{"id":"ch10p19","audio":true,"sents":[{"it":"“Maestà...” gli disse, “mi scusi se ho l’ardire di farle una domanda...”","zh":"——陛下……您统治的是什么呢？","t":[100,4500]}]},{"id":"ch10p20","audio":true,"sents":[{"it":"“Ti ordino di farmi una domanda,” si affrettò a dire il re.","zh":"——统治一切！","t":[100,3087]}]},{"id":"ch10p21","audio":true,"sents":[{"it":"“Maestà...","zh":"——国王天真地答道。","t":[100,1000]},{"it":"lei su che cosa regna?”","zh":"——一切？","t":[1000,2276]}]},{"id":"ch10p22","audio":true,"sents":[{"it":"“Su tutto,” rispose il re, con assoluto candore.","zh":"国王谦逊地指了指自己的小星球，又指了指别的有星星的行星。","t":[100,3162]}]},{"id":"ch10p23","audio":true,"sents":[{"it":"Con un gesto discreto il re indicò il proprio pianeta, gli altri pianeti e le stelle.","zh":"——小王子追问。","t":[100,5150]}]},{"id":"ch10p24","audio":true,"sents":[{"it":"“Su tutto questo?” disse il piccolo principe.","zh":"——正是这一切，——国王骄傲地答道。","t":[100,2963]}]},{"id":"ch10p25","audio":true,"sents":[{"it":"“Su tutto questo...” rispose il re.","zh":"他可不单是专制君主，还是普天之下的君主呢。","t":[100,2300]}]},{"id":"ch10p26","audio":true,"sents":[{"it":"Infatti non era soltanto un monarca assoluto, era anche un monarca universale.","zh":"——那么星星都听您的吗？","t":[100,4924]}]},{"id":"ch10p27","audio":true,"sents":[{"it":"“E le stelle le obbediscono?”","zh":"——那还用说，——国王说。","t":[100,1612]}]},{"id":"ch10p28","audio":true,"sents":[{"it":"“Certamente,” disse il re.","zh":"——令出即行。","t":[100,1925]},{"it":"“Io non tollero la disobbedienza.”","zh":"我可不容人违抗！","t":[1925,3788]}]},{"id":"ch10p29","audio":true,"sents":[{"it":"Il piccolo principe rimase incantato da tanto potere.","zh":"这般权势，叫小王子心驰神往。","t":[100,3638]},{"it":"Se l’avesse avuto, avrebbe potuto assistere non a quarantaquattro ma a settantadue, o anche a cento, o anche a duecento tramonti nello stesso giorno, senza dover mai spostare la sedia!","zh":"他要是有这样的权力，一天里就不止看四十四场日落，而是能看七十二场，甚至一百场、两百场，连椅子都不用挪！","t":[3638,15188]},{"it":"E, poiché si sentiva un po’ triste al ricordo del piccolo pianeta abbandonato, si azzardò a chiedere un favore al re:","zh":"小王子自离开自己的星球后一直郁郁寡欢，这会儿竟壮起胆子，向国王讨个恩典。","t":[15188,22176]}]},{"id":"ch10p30","audio":true,"sents":[{"it":"“Vorrei tanto vedere un tramonto...","zh":"——我想看一场日落……","t":[100,2088]},{"it":"Per piacere...","zh":"——劳您驾——命令太阳下山吧……","t":[2088,3188]},{"it":"Ordini al sole di tramontare...”","zh":"——要是我命令某位将军像蝴蝶似的从一朵花飞到另一朵花，或者写一出伟大的悲剧，或者变成海鸟，而这位将军没执行这道命令，你说，错的是他还是我？","t":[3188,4926]}]},{"id":"ch10p31","audio":true,"sents":[{"it":"“Se ordinassi a un generale di volare di fiore in fiore come una farfalla, o di scrivere una tragedia o di trasformarsi in un uccello marino, e se il generale non eseguisse l’ordine ricevuto, chi avrebbe torto fra lui e me?”","zh":"——说得对。","t":[100,12962]}]},{"id":"ch10p32","audio":true,"sents":[{"it":"“Lei,” disse convinto il piccolo principe.","zh":"对人只该要求他力所能及的事，——国王接着说。","t":[100,2712]}]},{"id":"ch10p33","audio":true,"sents":[{"it":"“Esatto.","zh":"——权威，首要是建立在理性之上。","t":[100,1150]},{"it":"Bisogna pretendere da ciascuno quel che ciascuno può dare,” proseguì il re.","zh":"你要是命令百姓去跳悬崖，他们就要闹革命了。","t":[1150,5500]},{"it":"“L’autorità si fonda in primo luogo sulla ragione.","zh":"而我要求服从，是因为我的命令都合情合理。","t":[5500,8525]},{"it":"Se ordini al tuo popolo di andare a gettarsi in mare, quello farà la rivoluzione.","zh":"——那日落的事呢？","t":[8525,13475]},{"it":"Ho il diritto di pretendere l’obbedienza perché i miei ordini sono ragionevoli.”","zh":"——小王子提醒道。他一旦问出口，从不半途而废。","t":[13475,17562]}]},{"id":"ch10p34","audio":true,"sents":[{"it":"“Allora, il mio tramonto?” tornò alla carica il piccolo principe, che non rinunciava mai a una domanda dopo che l’aveva fatta.","zh":"——你要的日落，会给你的。","t":[100,7400]}]},{"id":"ch10p35","audio":true,"sents":[{"it":"“Lo avrai, il tuo tramonto.","zh":"我自会要求！","t":[100,2162]},{"it":"Lo esigerò.","zh":"不过得等一等。","t":[2162,3325]},{"it":"Ma, forte della mia esperienza di governo, aspetterò che si presentino le condizioni favorevoli.”","zh":"治国之道，贵在择时。","t":[3325,9150]}]},{"id":"ch10p36","audio":true,"sents":[{"it":"“E quando sarà?” volle sapere il piccolo principe.","zh":"——那要等到什么时候呢？","t":[100,3224]}]},{"id":"ch10p37","audio":true,"sents":[{"it":"“Ehm!","zh":"——嗯，嗯，——国王先瞅了瞅大日历，答道。","t":[100,838]},{"it":"Ehm!” rispose il re, che subito consultò un grosso calendario.","zh":"——嗯，嗯……","t":[838,5325]},{"it":"“Ehm, ehm, sarà verso...","zh":"这事会……","t":[5325,7688]},{"it":"verso...","zh":"会发生的……","t":[7688,8575]},{"it":"sarà stasera, verso le sette e quaranta!","zh":"就在今天傍晚，七点二十分左右！","t":[8575,11600]},{"it":"E vedrai come mi obbedirà!”","zh":"到时你就瞧瞧，万物是怎样听我号令的！","t":[11600,13037]}]},{"id":"ch10p38","audio":true,"sents":[{"it":"Il piccolo principe sbadigliò.","zh":"小王子打了个哈欠。","t":[100,2188]},{"it":"Si rammaricava per il mancato tramonto.","zh":"他已经在后悔，自己在星球上错过了那么多日落。","t":[2188,4650]},{"it":"E cominciava ad annoiarsi un po’:","zh":"再说，他也觉得乏味了。","t":[4650,6450]}]},{"id":"ch10p39","audio":true,"sents":[{"it":"“Non ho più niente da fare qui,” disse al re.","zh":"——看来我在这儿没什么事可做了，——他对国王说。","t":[100,2700]},{"it":"“Me ne vado!”","zh":"——我还是走吧。","t":[2700,3488]}]},{"id":"ch10p40","audio":true,"sents":[{"it":"“Non te ne andare,” rispose il re, talmente fiero di avere un suddito.","zh":"——留下来吧，——国王答道。有个臣民，叫他好不得意。","t":[100,4188]},{"it":"“Non te ne andare, ti faccio ministro!”","zh":"——别走！","t":[4188,6362]}]},{"id":"ch10p41","audio":true,"sents":[{"it":"“Ministro di cosa?”","zh":"——什么大臣？","t":[100,1187]}]},{"id":"ch10p42","audio":true,"sents":[{"it":"“Di...","zh":"——嗯……司法大臣。","t":[100,850]},{"it":"della Giustizia!”","zh":"——可这儿没人好审呀！","t":[850,1850]}]},{"id":"ch10p43","audio":true,"sents":[{"it":"“Ma non c’è nessuno da giudicare!”","zh":"——那可难说，——国王答道。","t":[100,1850]}]},{"id":"ch10p44","audio":true,"sents":[{"it":"“Non lo sappiamo,” gli disse il re.","zh":"——我还没巡遍整个王国呢。","t":[100,2175]},{"it":"“Non ho ancora visitato tutto il mio regno.","zh":"我年事已高，既没有马车的位置，走路又累得慌。","t":[2175,4538]},{"it":"Sono molto vecchio, non ho spazio per una carrozza e camminare mi stanca.”","zh":"——是吗？","t":[4538,8650]}]},{"id":"ch10p45","audio":true,"sents":[{"it":"“Oh!","zh":"可我已经都看过了，——小王子说着，弯下腰又朝星球的另一面望了一眼。","t":[100,812]},{"it":"Ma io ho già visto,” disse il piccolo principe che si sporse a gettare ancora un’occhiata verso l’altro lato del pianeta.","zh":"——这儿一个人也没有。","t":[812,7450]},{"it":"“Non c’è nessuno neanche di là...”","zh":"——那你审你自己吧，——国王说。","t":[7450,9113]}]},{"id":"ch10p46","audio":true,"sents":[{"it":"“Allora giudicherai te stesso,” gli rispose il re.","zh":"——这可最难了。","t":[100,3000]},{"it":"“È la cosa più difficile.","zh":"这比审别人难得多。","t":[3000,4600]},{"it":"È molto più difficile giudicare se stessi che giudicare gli altri.","zh":"你能正确评判自己，才算真正有智慧。","t":[4600,8300]},{"it":"Se riesci a giudicarti bene, significa che sei un vero saggio.”","zh":"用不着非住在这儿。","t":[8300,12050]}]},{"id":"ch10p47","audio":true,"sents":[{"it":"“Io,” disse il piccolo principe, “posso giudicare me stesso ovunque.","zh":"——嗯，嗯……","t":[100,4338]},{"it":"Non occorre che viva qui.”","zh":"——国王说。","t":[4338,5913]}]},{"id":"ch10p48","audio":true,"sents":[{"it":"“Ehm, ehm,” fece il re, “credo proprio che da qualche parte qui sul mio pianeta ci sia un vecchio topo.","zh":"——不过我确知，我星球上的某个角落，住着一只老耗子。","t":[100,6138]},{"it":"Lo sento la notte.","zh":"夜里我听得见它。","t":[6138,7612]},{"it":"Potrai giudicare quel vecchio topo.","zh":"你可以审它，时不时判它死刑。","t":[7612,9762]},{"it":"Ogni tanto lo condannerai a morte.","zh":"这样，它的性命就攥在你的判决里了。","t":[9762,12088]},{"it":"Così la sua vita dipenderà dalla tua giustizia.","zh":"不过每次出于仁慈和省事，你都赦免它。","t":[12088,14925]},{"it":"E poi lo grazierai, così potremo tenercelo.","zh":"毕竟它在这儿就这一个……","t":[14925,18000]},{"it":"Visto che ce n’è uno solo.”","zh":"——可我，——小王子反驳道，——我不喜欢判人死刑，所以，我还是走吧。","t":[18000,19450]}]},{"id":"ch10p49","audio":true,"sents":[{"it":"“A me non piace condannare a morte,” rispose il piccolo principe, “e credo proprio che me ne andrò.”","zh":"——不行，不许走！","t":[100,5276]}]},{"id":"ch10p50","audio":true,"sents":[{"it":"“No,” disse il re.","zh":"——国王说。","t":[100,1250]}]},{"id":"ch10p51","audio":true,"sents":[{"it":"Ma, finiti i preparativi, il piccolo principe non volle dare un dispiacere al vecchio monarca:","zh":"可已经整装待发的小王子，不忍心让老君主伤心。","t":[100,5862]}]},{"id":"ch10p52","audio":true,"sents":[{"it":"“Se Sua Maestà volesse essere prontamente obbedita, potrebbe darmi un ordine ragionevole.","zh":"比如，您大可命令我即刻上路。","t":[100,5262]},{"it":"Per esempio, potrebbe ordinarmi di partire fra un minuto.","zh":"这会儿，正是下这道命令的好时机。","t":[5262,8775]},{"it":"Mi sembra che ci siano le condizioni favorevoli...”","zh":"国王对此一言不发，小王子略一犹疑，叹了口气，上路了。","t":[8775,11525]}]},{"id":"ch10p53","audio":true,"sents":[{"it":"Poiché il re non rispose nulla, il piccolo principe dapprima esitò, poi con un sospiro se ne andò.","zh":"——我封你为我的使节！","t":[100,6162]}]},{"id":"ch10p54","audio":true,"sents":[{"it":"“Ti nomino mio ambasciatore,” si affrettò allora a gridare il re.","zh":"——国王冲着他的背影喊了出来。","t":[100,3375]}]},{"id":"ch10p55","audio":true,"sents":[{"it":"Aveva un atteggiamento di grande autorità.","zh":"那一瞬间，他神情威严十足。","t":[100,2362]}]},{"id":"ch10p56","audio":true,"sents":[{"it":"“Gli adulti sono proprio curiosi,” disse tra sé il piccolo principe durante il viaggio.","zh":"“大人真是古怪，”小王子一边继续飞行，一边想。","t":[100,4738]}]}]},{"id":"ch11","title_it":"XI","title_zh":"第 11 章","paras":[{"id":"ch11p00","audio":true,"sents":[{"it":"Il secondo pianeta era abitato da un vanitoso: “Ah!","zh":"第二颗行星上，住着一个虚荣的人。","t":[100,3862]},{"it":"Ecco la visita di un ammiratore!” esclamò da lontano il vanitoso appena scorse il piccolo principe.","zh":"——啊哈！","t":[3862,9862]}]},{"id":"ch11p01","audio":true,"sents":[{"it":"Per i vanitosi, infatti, gli altri uomini sono degli ammiratori.","zh":"——他老远望见小王子，就喊了起来。","t":[100,4450]}]},{"id":"ch11p02","audio":true,"sents":[{"it":"“Buongiorno,” disse il piccolo principe, “ha proprio uno strano cappello!”","zh":"要知道，在虚荣的人看来，别人统统只是他的崇拜者和仰慕者。","t":[100,4375]}]},{"id":"ch11p03","audio":true,"sents":[{"it":"“È per salutare,” gli rispose il vanitoso.","zh":"——您好，——小王子说。","t":[100,2662]},{"it":"“È per salutare quando mi acclamano.","zh":"——您的帽子真有意思。","t":[2662,4738]},{"it":"Disgraziatamente, da qui non passa mai nessuno.”","zh":"——这帽子是用来致意的，——虚荣的人答道。","t":[4738,7750]}]},{"id":"ch11p04","audio":true,"sents":[{"it":"“Ah sì?” disse il piccolo principe, che non capiva.","zh":"——别人给我鼓掌时，我就脱帽还礼；可惜这儿从来没人来。","t":[100,3563]}]},{"id":"ch11p05","audio":true,"sents":[{"it":"“Batti le mani una contro l’altra,” consigliò quindi il vanitoso.","zh":"——小王子没怎么听懂，随口应道。","t":[100,3500]}]},{"id":"ch11p06","audio":true,"sents":[{"it":"Il piccolo principe batté le mani una contro l’altra.","zh":"——你把两只手掌对拍，——虚荣的人教他。","t":[100,3488]},{"it":"Il vanitoso fece un gran saluto sollevando il cappello.","zh":"小王子拍起手来，虚荣的人便优雅地举起帽子，向他致意。","t":[3488,6800]}]},{"id":"ch11p07","audio":true,"sents":[{"it":"“È più divertente della visita al re,” si disse il piccolo principe.","zh":"“这儿比国王的星球热闹些，”小王子一边想。","t":[100,3825]},{"it":"E ricominciò a battere le mani.","zh":"他便又拍起手，虚荣的人也继续举着帽子致意。","t":[3825,5850]},{"it":"Il vanitoso ricominciò a salutare sollevando il cappello.","zh":"——要怎么着，帽子才会落下来呀？","t":[5850,9137]}]},{"id":"ch11p08","audio":true,"sents":[{"it":"Dopo cinque minuti il piccolo principe si stancò di quel giochetto sempre uguale:","zh":"——他问虚荣的人。","t":[100,4637]}]},{"id":"ch11p09","audio":true,"sents":[{"it":"“E per fare cadere il cappello cosa bisogna fare?” domandò.","zh":"可那人压根没听见。","t":[100,3413]}]},{"id":"ch11p10","audio":true,"sents":[{"it":"Ma il vanitoso non lo sentì.","zh":"虚荣的人，除了赞扬，什么也听不进去。","t":[100,2012]},{"it":"I vanitosi sentono solo le lodi.","zh":"——你当真对我崇拜得不得了吧？","t":[2012,4113]}]},{"id":"ch11p11","audio":true,"sents":[{"it":"“Tu mi ammiri davvero molto?” domandò al piccolo principe.","zh":"——虚荣的人问小王子。","t":[100,3350]}]},{"id":"ch11p12","audio":true,"sents":[{"it":"“Che cosa significa ‘ammirare’?”","zh":"——崇拜？","t":[100,1700]}]},{"id":"ch11p13","audio":true,"sents":[{"it":"“‘Ammirare’ significa riconoscere che sono l’uomo più bello, meglio vestito, più ricco e più intelligente del pianeta.”","zh":"意思就是承认，我是这颗星球上最优秀、最体面、最富有、最聪明的人。","t":[100,6974]}]},{"id":"ch11p14","audio":true,"sents":[{"it":"“Ma sei solo, sul tuo pianeta!”","zh":"——可你在这儿就一个人哪！","t":[100,2124]}]},{"id":"ch11p15","audio":true,"sents":[{"it":"“Fammi questo favore.","zh":"——哎呀，行行好，再对我崇拜一会儿吧！","t":[100,1538]},{"it":"Ammirami lo stesso!”","zh":"——好吧，——小王子耸耸肩说。","t":[1538,2775]}]},{"id":"ch11p16","audio":true,"sents":[{"it":"“Ti ammiro,” disse il piccolo principe alzando un po’ le spalle, “ma che cosa te ne viene?”","zh":"可这对你有什么好处呢？","t":[100,4888]}]},{"id":"ch11p17","audio":true,"sents":[{"it":"E il piccolo principe se ne andò.","zh":"说完，小王子便跑开了。","t":[100,1900]}]},{"id":"ch11p18","audio":true,"sents":[{"it":"“Gli adulti sono proprio strani,” disse semplicemente tra sé durante il viaggio.","zh":"“不，大人确实都是些古怪的家伙，”飞行途中他暗自想道。","t":[100,4400]}]}]},{"id":"ch12","title_it":"XII","title_zh":"第 12 章","paras":[{"id":"ch12p00","audio":true,"sents":[{"it":"Il pianeta seguente era abitato da un bevitore.","zh":"下一颗行星上，住着一个酒鬼。","t":[100,2887]}]},{"id":"ch12p01","audio":true,"sents":[{"it":"La visita fu molto breve, ma destò nel piccolo principe una gran malinconia:","zh":"对他的造访很短，却叫小王子十分难过。","t":[100,4788]}]},{"id":"ch12p02","audio":true,"sents":[{"it":"“Che fai qui?” disse al bevitore, che trovò seduto davanti a una sfilza di bottiglie, metà delle quali vuote e metà piene.","zh":"——他问酒鬼。酒鬼正坐在一堆空瓶子和满瓶子面前。","t":[100,7438]}]},{"id":"ch12p03","audio":true,"sents":[{"it":"“Bevo,” rispose il bevitore con aria cupa.","zh":"——我喝酒，——酒鬼闷闷不乐地答道。","t":[100,2375]}]},{"id":"ch12p04","audio":true,"sents":[{"it":"“Perché bevi?” gli domandò il piccolo principe.","zh":"——那你为什么喝酒？","t":[100,3050]}]},{"id":"ch12p05","audio":true,"sents":[{"it":"“Per dimenticare,” rispose il bevitore.","zh":"——为了忘掉，——酒鬼说。","t":[100,2237]}]},{"id":"ch12p06","audio":true,"sents":[{"it":"“Per dimenticare cosa?” volle sapere il piccolo principe, che già lo compativa.","zh":"——忘掉什么？","t":[100,4975]}]},{"id":"ch12p07","audio":true,"sents":[{"it":"“Per dimenticare che mi vergogno,” ammise il bevitore abbassando la testa.","zh":"——忘掉我的羞耻，——酒鬼低下头，承认道。","t":[100,4100]}]},{"id":"ch12p08","audio":true,"sents":[{"it":"“Ti vergogni di cosa?” lo interrogò il piccolo principe che desiderava aiutarlo.","zh":"——羞耻什么？","t":[100,4938]}]},{"id":"ch12p09","audio":true,"sents":[{"it":"“Mi vergogno di bere!” concluse il bevitore che si chiuse definitivamente nel silenzio.","zh":"——小王子很想帮帮他，追着问。","t":[100,5112]}]},{"id":"ch12p10","audio":true,"sents":[{"it":"E il piccolo principe se ne andò, perplesso.","zh":"小王子满心困惑，离开了这颗星球。","t":[100,2750]}]},{"id":"ch12p11","audio":true,"sents":[{"it":"“Gli adulti sono proprio molto strani,” diceva tra sé durante il viaggio.","zh":"“大人确确实实非常、非常古怪，”飞行途中，他又一次暗自想道。","t":[100,3913]}]}]},{"id":"ch13","title_it":"XIII","title_zh":"第 13 章","paras":[{"id":"ch13p00","audio":true,"sents":[{"it":"Il quarto pianeta era quello dell’uomo d’affari.","zh":"第四颗行星上，住着一个生意人。","t":[100,2912]},{"it":"Era un uomo talmente occupato che non alzò neppure la testa all’arrivo del piccolo principe.","zh":"这人忙得不可开交，小王子到来时，他连头都没抬一下。","t":[2912,8074]}]},{"id":"ch13p01","audio":true,"sents":[{"it":"“Buongiorno,” disse quest’ultimo.","zh":"——您好，——小王子打了声招呼。","t":[100,2200]},{"it":"“Ha la sigaretta spenta.”","zh":"——您瞧，您的烟灭了。","t":[2200,3537]}]},{"id":"ch13p02","audio":true,"sents":[{"it":"“Tre più due cinque.","zh":"——三加二等于五。","t":[100,1488]},{"it":"Cinque più sette dodici.","zh":"七加五等于十二。","t":[1488,3750]},{"it":"Dodici più tre quindici.","zh":"十二加三等于十五。","t":[3750,5975]},{"it":"Buongiorno.","zh":"你好。","t":[5975,7025]},{"it":"Quindici più sette ventidue.","zh":"十五加七等于二十二。","t":[7025,8988]},{"it":"Ventidue più sei ventotto.","zh":"我没空再把它点着了。","t":[8988,10888]},{"it":"Non ho tempo di riaccenderla.","zh":"二十六加五等于三十一。","t":[10888,12838]},{"it":"Ventisei più cinque trentuno.","zh":"哎哟！","t":[12838,14950]},{"it":"Uff!","zh":"总共是五亿零一百六十二万两千七百三十一。","t":[14950,15712]},{"it":"Quindi fanno cinquecentouno milioni seicento ventiduemila settecentotrentuno.”","zh":"——五亿什么呀？","t":[15712,20626]}]},{"id":"ch13p03","audio":true,"sents":[{"it":"“Cinquecento milioni di cosa?”","zh":"——什么？","t":[100,1737]}]},{"id":"ch13p04","audio":true,"sents":[{"it":"“Eh?","zh":"你还在这儿？","t":[100,712]},{"it":"Sei ancora qui?","zh":"五亿零一百六十二万……","t":[712,1988]},{"it":"Cinquecentouno milioni di...","zh":"什么来着……","t":[1988,3950]},{"it":"non mi ricordo più...","zh":"我记不得了。","t":[3950,5350]},{"it":"ho tanto di quel lavoro!","zh":"我有这么多事要忙！","t":[5350,6925]},{"it":"Sono una persona seria, io, mica perdo tempo con le stupidaggini!","zh":"我是个正经人。","t":[6925,11300]},{"it":"Due più cinque sette...”","zh":"那些无聊的闲事，我才不理会。","t":[11300,12825]}]},{"id":"ch13p05","audio":true,"sents":[{"it":"“Cinquecentouno milioni di cosa?” ripeté il piccolo principe che in vita sua non aveva mai rinunciato a una domanda dopo che l’aveva fatta.","zh":"二加五等于七。","t":[100,7813]}]},{"id":"ch13p06","audio":true,"sents":[{"it":"L’uomo d’affari alzò la testa:","zh":"——五亿什么呀？","t":[100,1987]}]},{"id":"ch13p07","audio":true,"sents":[{"it":"“Abito in questo pianeta da cinquantaquattro anni e sono stato disturbato solo tre volte.","zh":"——小王子一旦问出口，从不半途而废，这会儿又问。","t":[100,5500]},{"it":"La prima volta è stata ventidue anni fa, da un maggiolino caduto chissà da dove.","zh":"生意人抬起头：“在我住这颗星球的五十四年里，一共只被打扰过三次。","t":[5500,10412]},{"it":"Faceva un rumore spaventoso e mi sono scappati quattro errori in un’addizione.","zh":"不知从哪儿飞来一只金龟子。","t":[10412,15225]},{"it":"La seconda volta è stata undici anni fa, da un attacco di reumatismi.","zh":"它嗡嗡直叫，害我加法算错了四次。","t":[15225,19650]},{"it":"Non faccio abbastanza moto.","zh":"第二回，是十一年前。","t":[19650,21438]},{"it":"Non ho tempo di andare a spasso.","zh":"我犯了风湿。","t":[21438,23388]},{"it":"Sono una persona seria, io.","zh":"我缺少运动，可我没空去散步。","t":[23388,25550]},{"it":"La terza volta, eccola!","zh":"因为我是个正经人。","t":[25550,27688]},{"it":"Dicevo quindi cinquecentouno milioni...”","zh":"第三回，就是你闯来的！","t":[27688,30176]}]},{"id":"ch13p08","audio":true,"sents":[{"it":"“Milioni di cosa?”","zh":"所以，我刚才说到——五亿零一百六十二万……","t":[100,1125]}]},{"id":"ch13p09","audio":true,"sents":[{"it":"L’uomo d’affari capì che non aveva speranza di essere lasciato in pace:","zh":"——几亿个什么呢？","t":[100,3724]}]},{"id":"ch13p10","audio":true,"sents":[{"it":"“Milioni di quelle cosettine che ogni tanto si vedono in cielo.”","zh":"生意人明白，这下是甩不掉他了。","t":[100,3400]}]},{"id":"ch13p11","audio":true,"sents":[{"it":"“Mosche?”","zh":"——就是天上偶尔能瞧见的那许许多多小玩意儿。","t":[100,738]}]},{"id":"ch13p12","audio":true,"sents":[{"it":"“Ma no, quelle cosettine gialle.”","zh":"——小虫子？","t":[100,2237]}]},{"id":"ch13p13","audio":true,"sents":[{"it":"“Api?”","zh":"——不是啦！","t":[100,600]}]},{"id":"ch13p14","audio":true,"sents":[{"it":"“Ma no, quelle cosettine dorate che fanno sognare i perdigiorno.","zh":"是那种亮晶晶的小东西。","t":[100,4138]},{"it":"Io però sono una persona seria!","zh":"——蜜蜂？","t":[4138,6338]},{"it":"Mica ho tempo di perdermi nei sogni.”","zh":"——不是啦！","t":[6338,8513]}]},{"id":"ch13p15","audio":true,"sents":[{"it":"“Ah, le stelle?”","zh":"是那些金灿灿、让人忍不住做白日梦的小东西。","t":[100,1174]}]},{"id":"ch13p16","audio":true,"sents":[{"it":"“Esatto.","zh":"没空去胡思乱想。","t":[100,1150]},{"it":"Le stelle.”","zh":"——啊！","t":[1150,1976]}]},{"id":"ch13p17","audio":true,"sents":[{"it":"“E cosa te ne fai di cinquecento milioni di stelle?”","zh":"星星！","t":[100,2825]}]},{"id":"ch13p18","audio":true,"sents":[{"it":"“Cinquecentouno milioni seicentoventiduemila settecentotrentuno.","zh":"——正是，星星。","t":[100,4662]},{"it":"Sono una persona seria, io, una persona precisa!”","zh":"——那你拿这好几亿颗星星做什么呢？","t":[4662,8300]}]},{"id":"ch13p19","audio":true,"sents":[{"it":"“E cosa te ne fai di tutte quelle stelle?”","zh":"——精确地说，是五亿零一百六十二万两千七百三十一颗星星。","t":[100,2200]}]},{"id":"ch13p20","audio":true,"sents":[{"it":"“Cosa me ne faccio?”","zh":"——那么你拿这些星星做什么呢？","t":[100,1037]}]},{"id":"ch13p21","audio":true,"sents":[{"it":"“Sì.”","zh":"——我拿它们做什么？","t":[100,562]}]},{"id":"ch13p22","audio":true,"sents":[{"it":"“Niente.","zh":"——嗯，这个……","t":[100,1025]},{"it":"Le possiedo.”","zh":"——什么都不做。","t":[1025,1912]}]},{"id":"ch13p23","audio":true,"sents":[{"it":"“Possiedi le stelle?”","zh":"我拥有它们。","t":[100,1224]}]},{"id":"ch13p24","audio":true,"sents":[{"it":"“Sì.”","zh":"——你拥有这些星星？","t":[100,562]}]},{"id":"ch13p25","audio":true,"sents":[{"it":"“Ma io ho già visto un re che...”","zh":"——对。","t":[100,1676]}]},{"id":"ch13p26","audio":true,"sents":[{"it":"“I re non possiedono niente.","zh":"——可我见过一位国王，他……","t":[100,2012]},{"it":"Loro ‘regnano’.","zh":"——国王不“拥有”。","t":[2012,3138]},{"it":"È ben diverso.”","zh":"他们“统治”。","t":[3138,4062]}]},{"id":"ch13p27","audio":true,"sents":[{"it":"“E a cosa ti serve possedere le stelle?”","zh":"这完全是两码事。","t":[100,2200]}]},{"id":"ch13p28","audio":true,"sents":[{"it":"“Mi serve a essere ricco.”","zh":"——为什么要拥有？","t":[100,1387]}]},{"id":"ch13p29","audio":true,"sents":[{"it":"“E a cosa ti serve essere ricco?”","zh":"为了当富翁。","t":[100,1763]}]},{"id":"ch13p30","audio":true,"sents":[{"it":"“A comprare altre stelle, se qualcuno le trova.”","zh":"——那你又要富翁做什么？","t":[100,2763]}]},{"id":"ch13p31","audio":true,"sents":[{"it":"“Questo qui,” disse tra sé il piccolo principe, “ragiona un po’ come il mio ubriacone.”","zh":"——好等别人发现新星星时，把它们买下来呀。","t":[100,4787]}]},{"id":"ch13p32","audio":true,"sents":[{"it":"Tuttavia fece ancora qualche domanda:","zh":"“这个大人，”小王子暗想，“算起账来，跟那个酒鬼差不多。”","t":[100,2138]}]},{"id":"ch13p33","audio":true,"sents":[{"it":"“Come si fa a possedere le stelle?”","zh":"尽管如此，他又追问了几句：——星星怎么个“拥有”法？","t":[100,1875]}]},{"id":"ch13p34","audio":true,"sents":[{"it":"“Di chi sono?” ribatté, stizzito, l’uomo d’affari.","zh":"——那它们是谁的？","t":[100,4000]}]},{"id":"ch13p35","audio":true,"sents":[{"it":"“Non lo so.","zh":"——生意人嘟囔着反问道。","t":[100,1012]},{"it":"Di nessuno.”","zh":"——我不知道。","t":[1012,1925]}]},{"id":"ch13p36","audio":true,"sents":[{"it":"“Allora sono mie, perché ho avuto per primo l’idea.”","zh":"大概谁也不是。","t":[100,2950]}]},{"id":"ch13p37","audio":true,"sents":[{"it":"“È sufficiente?”","zh":"——既然是我第一个想到要拥有它们，那它们就是我的。","t":[100,1125]}]},{"id":"ch13p38","audio":true,"sents":[{"it":"“Certo.","zh":"——这就够了吗？","t":[100,1025]},{"it":"Quando trovi un diamante che non è di nessuno, allora è tuo.","zh":"——完全够！","t":[1025,4962]},{"it":"Quando sei il primo ad avere un’idea, la fai brevettare ed è tua.","zh":"因为你要是找到一颗没主儿的钻石，它就成了你的。","t":[4962,9075]},{"it":"E io possiedo le stelle, perché a nessuno prima di me è venuto in mente di possederle.”","zh":"你要是发现一座无主荒岛，它也是你的。","t":[9075,13774]}]},{"id":"ch13p39","audio":true,"sents":[{"it":"“È vero,” disse il piccolo principe.","zh":"你要是头一个想出某个点子，你给它申请专利，那点子就是你的。","t":[100,2275]},{"it":"“E che cosa te ne fai?”","zh":"我拥有星星，只因为从前没人想到要去占有它们。","t":[2275,3476]}]},{"id":"ch13p40","audio":true,"sents":[{"it":"“Le gestisco.","zh":"——那你拿它们做什么呢？","t":[100,1350]},{"it":"Le conto e le riconto,” disse l’uomo d’affari.","zh":"——我经营管理它们。","t":[1350,4188]},{"it":"“È difficile.","zh":"数一数，再数一数，——生意人说。","t":[4188,5275]},{"it":"Ma io sono un uomo serio!”","zh":"——这活儿不容易，可我是个正经人。","t":[5275,6862]}]},{"id":"ch13p41","audio":true,"sents":[{"it":"Il piccolo principe non era ancora soddisfatto.","zh":"不过，小王子到底还有件事没弄明白。","t":[100,2887]}]},{"id":"ch13p42","audio":true,"sents":[{"it":"“Se possiedo un fazzoletto posso mettermelo al collo e portarlo con me.","zh":"——我要是有一条围巾，我可以支配它——围在脖子上，带着它走。","t":[100,4250]},{"it":"Se possiedo un fiore posso coglier­lo e portarlo con me.","zh":"我要是有一朵花，我可以把它摘下带走。","t":[4250,7612]},{"it":"Ma tu non puoi cogliere le stelle!”","zh":"可你总不能把星星摘下来吧！","t":[7612,9526]}]},{"id":"ch13p43","audio":true,"sents":[{"it":"“No, ma posso metterle in banca.”","zh":"——摘不下来。","t":[100,2237]}]},{"id":"ch13p44","audio":true,"sents":[{"it":"“Che cosa vuol dire?”","zh":"不过我可以把它们存进银行。","t":[100,1162]}]},{"id":"ch13p45","audio":true,"sents":[{"it":"“Vuol dire che scrivo su un foglio il numero delle mie stelle.","zh":"——怎么个存法？","t":[100,3562]},{"it":"E poi chiudo a chiave il foglio in un cassetto.”","zh":"这算什么意思？","t":[3562,6050]}]},{"id":"ch13p46","audio":true,"sents":[{"it":"“Ed è sufficiente?”","zh":"——意思就是，我把星星的数目写在一张纸上，再把纸放进抽屉，用钥匙锁上。","t":[100,1163]}]},{"id":"ch13p47","audio":true,"sents":[{"it":"“Certo!”","zh":"——就这些？","t":[100,762]}]},{"id":"ch13p48","audio":true,"sents":[{"it":"“È divertente,” pensò il piccolo principe.","zh":"——这就足够了。","t":[100,2650]},{"it":"“È molto poetico.","zh":"“这真有意思，”小王子想。","t":[2650,4038]},{"it":"Ma non è granché serio.”","zh":"“听着挺美，可不太正经。”","t":[4038,5425]}]},{"id":"ch13p49","audio":true,"sents":[{"it":"Il piccolo principe aveva idee molto diverse dagli adulti riguardo alle cose serie.","zh":"——就拿我来说，——他又说，——我有一朵花，我天天给它浇水。","t":[100,4713]}]},{"id":"ch13p50","audio":true,"sents":[{"it":"“Io,” disse ancora, “possiedo una rosa che innaffio tutti i giorni.","zh":"我有三座火山，我每星期都疏通。","t":[100,4338]},{"it":"Possiedo tre vulcani che pulisco tutte le settimane.","zh":"那座死火山，我也照样清理。","t":[4338,7762]},{"it":"Perché pulisco anche quello spento.","zh":"就这么着——以防万一呗。","t":[7762,10012]},{"it":"Non si sa mai.","zh":"我拥有我的火山和我的花，对它们是有好处的。","t":[10012,11175]},{"it":"Il fatto che io li possieda è utile ai miei vulcani ed è utile alla mia rosa.","zh":"可你拥有星星，对星星有什么好处呢？","t":[11175,15950]},{"it":"Invece tu non sei utile alle stelle...”","zh":"生意人张了张嘴，到底什么也没答上来。","t":[15950,18037]}]},{"id":"ch13p51","audio":true,"sents":[{"it":"L’uomo d’affari aprì la bocca ma non trovò nulla da rispondere, e il piccolo principe se ne andò.","zh":"于是小王子又上路了。","t":[100,5387]}]},{"id":"ch13p52","audio":true,"sents":[{"it":"“Gli adulti sono veramente stravaganti,” diceva semplicemente tra sé durante il viaggio.","zh":"“大人确确实实是些不可思议的家伙，”一路上他不住地想。","t":[100,4750]}]}]},{"id":"ch14","title_it":"XIV","title_zh":"第 14 章","paras":[{"id":"ch14p00","audio":true,"sents":[{"it":"Il quinto pianeta era davvero curioso.","zh":"第五颗行星，可算是最奇特的了。","t":[100,2525]},{"it":"Era il più piccolo di tutti.","zh":"在小王子见过的星球里，它最小。","t":[2525,4412]},{"it":"C’era spazio solo per un lampione e un lampionaio.","zh":"上面只容得下一盏路灯和一个点灯人。","t":[4412,7625]},{"it":"Il piccolo principe non riusciva a spiegarsi a cosa potessero servire, in un punto del cielo, su un pia­neta senza case né popolazione, un lampione e un lampionaio.","zh":"小王子怎么也想不通，在天上那么一颗没有房屋、没有居民的星球上，要路灯和点灯人做什么。","t":[7625,17800]},{"it":"Tuttavia disse tra sé:","zh":"不过他转念一想——这人虽说古怪，可比起国王、生意人和酒鬼，倒也并不更古怪。","t":[17800,19088]}]},{"id":"ch14p01","audio":true,"sents":[{"it":"“Forse quest’uomo è assurdo.","zh":"至少，他的活计还有点意义。","t":[100,2188]},{"it":"Però è meno assurdo del re, del vanitoso, dell’uomo d’affari e del bevitore.","zh":"他点亮路灯时，仿佛天上又多了一颗星，或是又开了一朵花。","t":[2188,7412]},{"it":"Almeno il suo lavoro ha un senso.","zh":"他熄灭路灯时，仿佛星星或花儿就睡着了。","t":[7412,9538]},{"it":"Quando accende il lampione, è come se facesse nascere una stella in più, o un fiore.","zh":"这活儿挺叫人喜欢。","t":[9538,14925]},{"it":"Quando spegne il lampione, addormenta il fiore o la stella.","zh":"它有益，因为它创造美。","t":[14925,18675]},{"it":"È una bellissima occupazione.","zh":"飞近这颗星球，小王子彬彬有礼地向点灯人问好。","t":[18675,20712]},{"it":"Ed è davvero utile perché è bella!”","zh":"——您好，——他说。","t":[20712,22513]}]},{"id":"ch14p02","audio":true,"sents":[{"it":"Quando giunse sul pianeta, salutò rispettosamente il lampionaio:","zh":"——你刚才怎么把灯灭了？","t":[100,4137]}]},{"id":"ch14p03","audio":true,"sents":[{"it":"“Buongiorno.","zh":"——这是规矩，——点灯人答道。","t":[100,1150]},{"it":"Perché hai spento il tuo lampione?”","zh":"——早安。","t":[1150,2850]}]},{"id":"ch14p04","audio":true,"sents":[{"it":"“Sono le direttive,” rispose il lampionaio.","zh":"——什么规矩？","t":[100,2738]},{"it":"“Buongiorno.”","zh":"——该灭灯了。","t":[2738,3526]}]},{"id":"ch14p05","audio":true,"sents":[{"it":"“Quali direttive?”","zh":"晚上好！","t":[100,1200]}]},{"id":"ch14p06","audio":true,"sents":[{"it":"“Di spegnere il lampione.","zh":"说着，他把自己的灯点亮了。","t":[100,1800]},{"it":"Buonasera.”","zh":"——小王子问。","t":[1800,2588]}]},{"id":"ch14p07","audio":true,"sents":[{"it":"E lo riaccese.","zh":"——这是规矩，——点灯人答道。","t":[100,1038]}]},{"id":"ch14p08","audio":true,"sents":[{"it":"“Ma perché l’hai riacceso?”","zh":"——我不明白……","t":[100,1474]}]},{"id":"ch14p09","audio":true,"sents":[{"it":"“Sono le direttive,” rispose il lampionaio.","zh":"——小王子说。","t":[100,2476]}]},{"id":"ch14p10","audio":true,"sents":[{"it":"“Non capisco,” disse il piccolo principe.","zh":"——没什么好明白的，——点灯人说。","t":[100,2375]}]},{"id":"ch14p11","audio":true,"sents":[{"it":"“Non c’è niente da capire,” disse il lampionaio.","zh":"——规矩就是规矩。","t":[100,2912]},{"it":"“Le direttive sono queste.","zh":"早安！","t":[2912,4738]},{"it":"Buongiorno.”","zh":"说着，他又把灯灭了。","t":[4738,5526]}]},{"id":"ch14p12","audio":true,"sents":[{"it":"E spense il lampione.","zh":"接着，他用红格手帕擦了擦额头。","t":[100,1450]}]},{"id":"ch14p13","audio":true,"sents":[{"it":"Poi si asciugò la fronte con un fazzoletto a quadretti bianco e rosso.","zh":"这该死的活儿，累死人。","t":[100,4074]}]},{"id":"ch14p14","audio":true,"sents":[{"it":"“Il mio è proprio un mestiere orribile.","zh":"从前可轻松多了。","t":[100,2412]},{"it":"Una volta era ancora fattibile.","zh":"我早晨灭灯，傍晚点灯。","t":[2412,4500]},{"it":"Spegnevo al mattino e accendevo alla sera.","zh":"白天能歇着，夜里能睡个够。","t":[4500,7100]},{"it":"Avevo il resto della giornata per riposarmi, e il resto della notte per dormire...”","zh":"——从那以后，规矩改了吗？","t":[7100,11750]}]},{"id":"ch14p15","audio":true,"sents":[{"it":"“E da allora sono cambiate le direttive?”","zh":"——小王子问。","t":[100,2237]}]},{"id":"ch14p16","audio":true,"sents":[{"it":"“Le direttive non sono cambiate,” disse il lampionaio.","zh":"——规矩没改，——点灯人叹了口气。","t":[100,3562]},{"it":"“È proprio questo il dramma!","zh":"——毛病就出在这儿。","t":[3562,5275]},{"it":"Con il passare degli anni il pianeta ha cominciato a ruotare sempre più in fretta, ma le direttive non sono cambiate!”","zh":"这颗星球一年转得比一年快，规矩却还是老样子。","t":[5275,11812]}]},{"id":"ch14p17","audio":true,"sents":[{"it":"“E allora?” disse il piccolo principe.","zh":"——那现在呢？","t":[100,2550]}]},{"id":"ch14p18","audio":true,"sents":[{"it":"“Allora adesso che fa un giro al minuto non ho più un istante di riposo.","zh":"——小王子问。","t":[100,4612]},{"it":"Accendo e spengo una volta al minuto!”","zh":"——如今它一分钟就转一圈，我连一秒钟的休息都没有。","t":[4612,6725]}]},{"id":"ch14p19","audio":true,"sents":[{"it":"“Questo sì che è buffo!","zh":"我每分钟就得点一次、灭一次这盏灯。","t":[100,1612]},{"it":"Da te i giorni durano un minuto!”","zh":"——真逗！","t":[1612,3513]}]},{"id":"ch14p20","audio":true,"sents":[{"it":"“Non è affatto buffo,” disse il lampionaio.","zh":"——这么说，你的一天只有一分钟长？","t":[100,2712]},{"it":"“Noi due stiamo parlando già da un mese.”","zh":"——这一点都不逗！","t":[2712,4912]}]},{"id":"ch14p21","audio":true,"sents":[{"it":"“Da un mese?”","zh":"——点灯人答道。","t":[100,850]}]},{"id":"ch14p22","audio":true,"sents":[{"it":"“Sì.","zh":"——咱俩这一聊，都已经整整一个月了！","t":[100,825]},{"it":"Trenta minuti.","zh":"——一个月？","t":[825,1962]},{"it":"Trenta giorni!","zh":"——嗯，对。","t":[1962,3175]},{"it":"Buonasera.”","zh":"三十天。","t":[3175,3963]}]},{"id":"ch14p23","audio":true,"sents":[{"it":"E riaccese il lampione.","zh":"晚上好！","t":[100,1600]}]},{"id":"ch14p24","audio":true,"sents":[{"it":"Il piccolo principe lo guardò e provò simpatia per quel lampionaio così ligio alle direttive che aveva ricevuto.","zh":"点灯人说着，又把灯点亮了。","t":[100,6137]}]},{"id":"ch14p25","audio":true,"sents":[{"it":"“Sai...","zh":"小王子若有所思地望着点灯人。","t":[100,812]},{"it":"posso insegnarti un trucco per riposarti quando vuoi...”","zh":"他喜欢这个不肯违背自己规矩的人。","t":[812,3663]}]},{"id":"ch14p26","audio":true,"sents":[{"it":"“Io lo voglio sempre,” disse il lampionaio.","zh":"他想起自己从前也常挪动椅子，在星球上看日落。","t":[100,2313]}]},{"id":"ch14p27","audio":true,"sents":[{"it":"Un uomo, infatti, può essere contemporaneamente coscienzioso e pigro.","zh":"小王子便想帮帮这位新朋友。","t":[100,5000]}]},{"id":"ch14p28","audio":true,"sents":[{"it":"Il piccolo principe proseguì:","zh":"——我无时无刻不想歇着。","t":[100,1913]}]},{"id":"ch14p29","audio":true,"sents":[{"it":"“Il tuo pianeta è talmente piccolo che in tre falcate ne fai il giro.","zh":"守着规矩和偷点懒，本可以两不耽误嘛。","t":[100,4212]},{"it":"Per rimanere sempre al sole basta che cammini molto piano.","zh":"——你瞧，——小王子接着说。","t":[4212,7762]},{"it":"Quando vorrai riposarti, dovrai solo camminare...","zh":"——你的星球那么小，三步就能绕一圈。","t":[7762,10962]},{"it":"e il giorno durerà tutto il tempo che vorrai.”","zh":"你要是走得够慢，就能一直待在太阳底下。","t":[10962,13350]}]},{"id":"ch14p30","audio":true,"sents":[{"it":"“Sai che m’importa!” disse il lampionaio.","zh":"想歇工了，只管往前走，你要白天多长，它就多长。","t":[100,3375]},{"it":"“A me nella vita piace dormire.”","zh":"——这法子顶不了什么用，——点灯人叹道。","t":[3375,4900]}]},{"id":"ch14p31","audio":true,"sents":[{"it":"“Proprio una bella scalogna,” disse il piccolo principe.","zh":"——我只求能安安稳稳睡上一觉。","t":[100,3075]}]},{"id":"ch14p32","audio":true,"sents":[{"it":"“Sì, una bella scalogna davvero,” disse il lampionaio.","zh":"这才是我想要的！","t":[100,3875]},{"it":"“Buongiorno.”","zh":"——唉，你这情况是不妙，——小王子替他难过。","t":[3875,4663]}]},{"id":"ch14p33","audio":true,"sents":[{"it":"E spense il lampione.","zh":"——是啊，运气不好，——点灯人答道。","t":[100,1450]}]},{"id":"ch14p34","audio":true,"sents":[{"it":"“Quell’uomo sarebbe disprezzato da tutti gli altri,” disse tra sé il piccolo principe, proseguendo il suo viaggio, “dal re, dal vanitoso, dal bevitore, dall’uomo d’affari.","zh":"——早安！","t":[100,10700]},{"it":"Tuttavia è l’unico che non mi sembra ridicolo.","zh":"说着，他又把灯灭了。","t":[10700,13325]},{"it":"Forse perché si occupa di qualcos’altro che non sia se stesso.”","zh":"“这个大人，”小王子继续赶路，心里想，“国王、虚荣的人、酒鬼、生意人，准都看他不顺眼。","t":[13325,16238]}]},{"id":"ch14p35","audio":true,"sents":[{"it":"Ebbe un sospiro di rammarico e si disse ancora:","zh":"可我倒不觉得他荒唐。","t":[100,2825]}]},{"id":"ch14p36","audio":true,"sents":[{"it":"“Quell’uomo è l’unico che avrei potuto farmi amico.","zh":"兴许是因为，他忙的是自己的本分，而不是自己本身。”","t":[100,3000]},{"it":"Ma il suo pianeta è davvero troppo piccolo.","zh":"小王子叹了口气，又暗自补了一句：“这是唯一一个，可能成为我朋友的大人。","t":[3000,5512]},{"it":"Non c’è posto per due...”","zh":"可他的星球那么小，两个人实在挤不下……”","t":[5512,6912]}]},{"id":"ch14p37","audio":true,"sents":[{"it":"Il piccolo principe non osava ammettere che rimpiangeva quel pianeta benedetto soprattutto per i millequattrocento quaranta tramonti ogni ventiquattro ore!","zh":"小王子不肯对自己承认，他惋惜这颗美丽的星球，其实只是因为——在它上面，二十四小时里他能看上一千四百四十场日落！","t":[100,8725]}]}]},{"id":"ch15","title_it":"XV","title_zh":"第 15 章","paras":[{"id":"ch15p00","audio":true,"sents":[{"it":"Il sesto pianeta era un pianeta dieci volte più grande.","zh":"第六颗行星，比前面的足足大十倍。","t":[100,3800]},{"it":"Era abitato da un anziano signore che scriveva certi enormi libri.","zh":"上面住着一位老先生，写的全是厚厚的书。","t":[3800,7575]}]},{"id":"ch15p01","audio":true,"sents":[{"it":"“Toh!","zh":"——啊哈！","t":[100,625]},{"it":"Ecco un esploratore!” esclamò quando vide il piccolo principe.","zh":"——他一眼看见小王子，叫出声来。","t":[625,4426]}]},{"id":"ch15p02","audio":true,"sents":[{"it":"Il piccolo principe si sedette sul tavolo e tirò il fiato.","zh":"小王子在一张桌子旁坐下，好喘口气。","t":[100,4000]},{"it":"Aveva già viaggiato così tanto!","zh":"他毕竟走了那么长的路。","t":[4000,5737]}]},{"id":"ch15p03","audio":true,"sents":[{"it":"“Da dove vieni?” domandò l’anziano signore.","zh":"——你从哪儿来？","t":[100,2788]}]},{"id":"ch15p04","audio":true,"sents":[{"it":"“Cos’è quel librone?” disse il piccolo principe.","zh":"——老先生问他。","t":[100,3338]},{"it":"“Che cosa fa qui?”","zh":"——这本厚厚的书是什么呀？","t":[3338,4187]}]},{"id":"ch15p05","audio":true,"sents":[{"it":"“Sono un geografo,” disse l’anziano signore.","zh":"——小王子反问他。","t":[100,2600]}]},{"id":"ch15p06","audio":true,"sents":[{"it":"“Che cos’è un geografo?”","zh":"——您在这儿做什么呢？","t":[100,1388]}]},{"id":"ch15p07","audio":true,"sents":[{"it":"“È uno scienziato che sa dove si trovano i mari, i fiumi, le città, le montagne e i deserti.”","zh":"——地理学家是什么人？","t":[100,6225]}]},{"id":"ch15p08","audio":true,"sents":[{"it":"“Questo sì che è interessante,” disse il piccolo principe.","zh":"——是这么一种学者：他清楚海洋在哪儿，河流、城市、山脉、沙漠又在哪儿。","t":[100,3412]},{"it":"“Finalmente un vero mestiere!” E diede un’occhiata intorno a sé al pianeta del geografo.","zh":"——了不起！","t":[3412,8938]},{"it":"Non aveva mai visto un pianeta così maestoso.","zh":"——小王子赞叹道。","t":[8938,11475]}]},{"id":"ch15p09","audio":true,"sents":[{"it":"“È proprio bello il suo pianeta.","zh":"——这真是个顶呱呱的行当。","t":[100,1975]},{"it":"Ci sono degli oceani?”","zh":"说罢，他满心敬慕地环顾起地理学家的星球。","t":[1975,3187]}]},{"id":"ch15p10","audio":true,"sents":[{"it":"“Non posso saperlo,” disse il geografo.","zh":"——您的星球真美呀！","t":[100,2350]}]},{"id":"ch15p11","audio":true,"sents":[{"it":"“Ah!” (Il piccolo principe era deluso.) “E montagne?”","zh":"有海洋吗？","t":[100,3763]}]},{"id":"ch15p12","audio":true,"sents":[{"it":"“Non posso saperlo,” disse il geografo.","zh":"——这我可不知道，——地理学家答道。","t":[100,2350]}]},{"id":"ch15p13","audio":true,"sents":[{"it":"“E città e fiumi e deserti?”","zh":"——原来如此……","t":[100,1775]}]},{"id":"ch15p14","audio":true,"sents":[{"it":"“Non posso sapere neanche questo,” disse il geografo.","zh":"——小王子略微有点失望。","t":[100,3074]}]},{"id":"ch15p15","audio":true,"sents":[{"it":"“Ma lei è un geografo!”","zh":"——那山脉呢？","t":[100,1513]}]},{"id":"ch15p16","audio":true,"sents":[{"it":"“Certo,” disse il geografo, “ma non sono un esploratore.","zh":"——这我也不知道，——地理学家答道。","t":[100,3825]},{"it":"Mi mancano gli esploratori.","zh":"——这些我统统不知道，——地理学家答道。","t":[3825,5638]},{"it":"Non è il geografo che fa il conto delle città, dei fiumi, delle montagne, dei mari, degli oceani e dei deserti.","zh":"——可您是地理学家呀！","t":[5638,13288]},{"it":"Il geografo è troppo importante e non può andare a zonzo.","zh":"——这没错，可我不是旅行家。","t":[13288,16900]},{"it":"Non esce mai dal suo studio.","zh":"我最缺的，就是旅行家。","t":[16900,18788]},{"it":"Ma lì riceve gli esploratori.","zh":"因为城市、河流、山脉、海洋、大洋、沙漠，都不是地理学家亲自去考察的。","t":[18788,20725]},{"it":"Li ascolta e trascrive i loro ricordi.","zh":"地理学家身份太重要，不能到处闲逛。","t":[20725,23350]},{"it":"E se i ricordi di uno di loro gli sembrano interessanti, il geografo fa fare un’indagine sulla moralità dell’esploratore.”","zh":"他从不离开书房的四壁。","t":[23350,30276]}]},{"id":"ch15p17","audio":true,"sents":[{"it":"“Per quale motivo?”","zh":"向他们打听，把他们的见闻记下来。","t":[100,1125]}]},{"id":"ch15p18","audio":true,"sents":[{"it":"“Perché se un esploratore dovesse mentire, provocherebbe dei pasticci nei libri di geografia.","zh":"哪段见闻他觉得有意思，地理学家还要派人去核实，看这讲述者靠不靠得住。","t":[100,5638]},{"it":"E lo stesso vale per un esploratore che bevesse troppo.”","zh":"——这是为什么？","t":[5638,8600]}]},{"id":"ch15p19","audio":true,"sents":[{"it":"“Per quale motivo?”","zh":"——因为旅行家要是胡编乱造，地理课本里就要乱成一团了。","t":[100,1125]}]},{"id":"ch15p20","audio":true,"sents":[{"it":"“Perché gli ubriaconi vedono doppio.","zh":"再说，万一是个酒鬼呢？","t":[100,2388]},{"it":"Perciò l’esploratore segnerebbe due montagne dove invece ce n’è una sola.”","zh":"——那又怎样？","t":[2388,6663]}]},{"id":"ch15p21","audio":true,"sents":[{"it":"“Conosco un tale,” disse il piccolo principe, “che sarebbe un pessimo esploratore.”","zh":"——酒鬼眼里，什么都成双的。","t":[100,4863]}]},{"id":"ch15p22","audio":true,"sents":[{"it":"“È possibile.","zh":"结果地理学家就会把只有一座的山，写成两座。","t":[100,1238]},{"it":"Poi, dopo aver verificato la moralità dell’esploratore, si fa un’indagine sulla sua scoperta.”","zh":"——我认识一个酒鬼，——小王子说。","t":[1238,6863]}]},{"id":"ch15p23","audio":true,"sents":[{"it":"“Andate a vedere?”","zh":"——他若当旅行家，准是个蹩脚的。","t":[100,975]}]},{"id":"ch15p24","audio":true,"sents":[{"it":"“No.","zh":"——那当然。","t":[100,400]},{"it":"È troppo complicato.","zh":"不过，旅行家要是可信，就该去核实他的发现。","t":[400,1888]},{"it":"Ma si chiede all’esploratore di fornire delle prove.","zh":"——要亲自去瞧瞧他发现了什么吗？","t":[1888,4912]},{"it":"Nel caso per esempio della scoperta di una grande montagna, si chiede che porti qualche grossa pietra.”","zh":"那太麻烦了。","t":[4912,10912]}]},{"id":"ch15p25","audio":true,"sents":[{"it":"Il geografo all’improvviso trasalì.","zh":"旅行家得拿出证据来。","t":[100,2162]}]},{"id":"ch15p26","audio":true,"sents":[{"it":"“Ma tu vieni da lontano!","zh":"比如，发现一座大山，就得让他从那儿搬回大石头来。","t":[100,1825]},{"it":"Sei un esploratore!","zh":"听到这儿，地理学家忽然激动起来。","t":[1825,3475]},{"it":"Devi assolutamente descrivermi il tuo pianeta!”","zh":"——你可是从远方来的？","t":[3475,6150]}]},{"id":"ch15p27","audio":true,"sents":[{"it":"E dopo aver aperto il registro, il geografo temperò la matita.","zh":"你是个旅行家呀！","t":[100,4300]},{"it":"I resoconti degli esploratori sono inizialmente scritti a matita.","zh":"快给我讲讲你的星球！","t":[4300,8325]},{"it":"Poi, quando l’esploratore ha fornito le prove, sono ripassati a penna.","zh":"因为旅行家的讲述，先得用铅笔记。","t":[8325,12700]}]},{"id":"ch15p28","audio":true,"sents":[{"it":"“Allora?” interrogò il geografo.","zh":"等证据交上来，才能用墨水誊清。","t":[100,2300]}]},{"id":"ch15p29","audio":true,"sents":[{"it":"“Oh!","zh":"——嗯？","t":[100,812]},{"it":"Il posto dove sto io non è molto interessante,” disse il piccolo principe.","zh":"——地理学家催道。","t":[812,5288]},{"it":"“È piccolissimo.","zh":"——我的星球上，——小王子说，——有意思的东西不太多。","t":[5288,6625]},{"it":"Ho tre vulcani.","zh":"那儿样样都小得很。","t":[6625,7900]},{"it":"Due attivi e uno spento.","zh":"不过谁也说不准，将来会怎样。","t":[7900,9712]},{"it":"Ma non si sa mai.”","zh":"——这倒是，——地理学家说。","t":[9712,10750]}]},{"id":"ch15p30","audio":true,"sents":[{"it":"“Non si sa mai,” disse il geografo.","zh":"——我还有一朵花。","t":[100,2150]}]},{"id":"ch15p31","audio":true,"sents":[{"it":"“Ho anche una rosa.”","zh":"——花我们不感兴趣，——地理学家说。","t":[100,1163]}]},{"id":"ch15p32","audio":true,"sents":[{"it":"“Noi non registriamo i fiori,” disse il geografo.","zh":"——可为什么呢？","t":[100,2850]}]},{"id":"ch15p33","audio":true,"sents":[{"it":"“Perché mai!","zh":"它们多美呀！","t":[100,1112]},{"it":"Sono la cosa più bella!”","zh":"——因为花是“转瞬即逝”的。","t":[1112,2463]}]},{"id":"ch15p34","audio":true,"sents":[{"it":"“Perché i fiori sono effimeri!”","zh":"——地理学著作，——地理学家说，——是世界上最珍贵的书。","t":[100,1762]}]},{"id":"ch15p35","audio":true,"sents":[{"it":"“Che cosa vuol dire ‘effimero’?”","zh":"它们永远不过时。","t":[100,1600]}]},{"id":"ch15p36","audio":true,"sents":[{"it":"“I libri di geografia,” disse il geografo, “sono i libri più seri che ci siano.","zh":"因为山挪窝的事，少之又少。","t":[100,5050]},{"it":"Non passano mai di moda.","zh":"大洋干涸，也极为罕见。","t":[5050,6688]},{"it":"È rarissimo che una montagna cambi posto.","zh":"我们写的是永恒的事物。","t":[6688,9188]},{"it":"È rarissimo che un oceano si prosciughi.","zh":"——可死火山也会醒过来呀，——小王子插嘴道。","t":[9188,11625]},{"it":"Noi scriviamo cose eterne.”","zh":"——那“转瞬即逝”到底是怎么回事？","t":[11625,13326]}]},{"id":"ch15p37","audio":true,"sents":[{"it":"“Ma i vulcani spenti possono risvegliarsi,” interruppe il piccolo principe.","zh":"我们看重的，是山本身。","t":[100,4812]},{"it":"“Che cosa significa ‘effimero’?”","zh":"它不会变。","t":[4812,6438]}]},{"id":"ch15p38","audio":true,"sents":[{"it":"“Che i vulcani siano spenti o attivi, per noialtri è lo stesso,” disse il geografo.","zh":"——可“转瞬即逝”到底是什么意思？","t":[100,5400]},{"it":"“Ciò che conta per noi è la montagna.","zh":"——小王子又追问一遍。","t":[5400,7588]},{"it":"E quella non cambia!”","zh":"他一旦问出口，就绝不罢休。","t":[7588,8787]}]},{"id":"ch15p39","audio":true,"sents":[{"it":"“Ma che cosa vuol dire ‘effimero’?” ripeté il piccolo principe che in vita sua non aveva mai rinunciato a una domanda dopo che l’aveva fatta.","zh":"——就是说，眼看就要消失的东西。","t":[100,7513]}]},{"id":"ch15p40","audio":true,"sents":[{"it":"“Vuol dire che è destinato a scomparire presto.”","zh":"——那是自然。","t":[100,2688]}]},{"id":"ch15p41","audio":true,"sents":[{"it":"“La mia rosa è destinata a scomparire presto?”","zh":"“我的花是转瞬即逝的！","t":[100,2624]}]},{"id":"ch15p42","audio":true,"sents":[{"it":"“Certo.”","zh":"——小王子心里想。","t":[100,762]}]},{"id":"ch15p43","audio":true,"sents":[{"it":"“La mia rosa è effimera,” disse tra sé il piccolo principe, “e ha solo quattro spine per difendersi dal mondo!","zh":"——它只有四根刺，拿什么去抵挡整个世界！","t":[100,6750]},{"it":"E l’ho lasciata sola là dove sto io!”","zh":"可我却把它孤零零地撇在了家里！”","t":[6750,8650]}]},{"id":"ch15p44","audio":true,"sents":[{"it":"Fu il suo primo moto di rammarico.","zh":"这一刻，他生平第一次后悔，自己离开了星球。","t":[100,2288]},{"it":"Ma si fece coraggio:","zh":"不过他还是稳住了心神。","t":[2288,3600]}]},{"id":"ch15p45","audio":true,"sents":[{"it":"“Cosa mi consiglia di andare a visitare?” domandò.","zh":"——他问地理学家。","t":[100,2950]}]},{"id":"ch15p46","audio":true,"sents":[{"it":"“Il pianeta Terra,” gli rispose il geografo.","zh":"——地球，——对方答道。","t":[100,2838]},{"it":"“Ne parlano molto bene...”","zh":"——它的名声，还算不坏……","t":[2838,4238]}]},{"id":"ch15p47","audio":true,"sents":[{"it":"E il piccolo principe se ne andò, pensando alla sua rosa.","zh":"于是小王子又上了路，心里老惦记着那朵被他抛下的花。","t":[100,3500]}]}]},{"id":"ch16","title_it":"XVI","title_zh":"第 16 章","paras":[{"id":"ch16p00","audio":true,"sents":[{"it":"Il settimo pianeta fu quindi la Terra.","zh":"就这样，按地理学家的建议，小王子拜访的第七颗星球，是地球。","t":[100,2400]}]},{"id":"ch16p01","audio":true,"sents":[{"it":"La Terra non è un pianeta qualsiasi!","zh":"这颗星球，可非同寻常。","t":[100,2612]},{"it":"Conta centoundici re (fra cui ovviamente i re negri), settemila geografi, novecentomila uomini d’affari, sette milioni e mezzo di ubriaconi, trecentoundici milioni di vanitosi, che fanno in tutto circa due miliardi di adulti.","zh":"上面住着一百一十一位国王（还不算非洲的国王）、七千名地理学家、九十万个生意人、七百五十万个酒鬼、三亿一千一百万个虚荣的人，以及大约二十亿个大人。","t":[2612,17750]}]},{"id":"ch16p02","audio":true,"sents":[{"it":"Per darvi un’idea delle dimensioni della Terra sappiate solo che, prima dell’invenzione dell’elettricità, nell’insieme dei sei continenti si doveva disporre di un vero e proprio esercito di quattrocento sessantaduemila cinquecento undici lampionai.","zh":"为了让您知道地球有多大，我告诉您：在电灯发明之前，六大洲上有一支真正的点灯人大军——四十六万两千五百一十一人！","t":[100,14562]}]},{"id":"ch16p03","audio":true,"sents":[{"it":"Visto da una certa distanza, il tutto faceva un bellissimo effetto.","zh":"从远处看，他们的动作蔚为壮观。","t":[100,4525]},{"it":"I movimenti di quell’esercito erano sincronizzati come quelli di un balletto.","zh":"点灯人大军步调一致，宛如一场芭蕾。","t":[4525,9138]},{"it":"Prima toccava ai lampionai della Nuova Zelanda e dell’Australia.","zh":"最先上场的，是新西兰和澳大利亚的点灯人。","t":[9138,13338]},{"it":"Quando questi avevano acceso i loro lampioni, se ne andavano a dormire.","zh":"他们点亮路灯，便去睡了。","t":[13338,17588]},{"it":"Allora entravano in scena i lampionai della Cina e della Siberia.","zh":"接着，中国和西伯利亚的点灯人开始忙活。","t":[17588,21462]},{"it":"Poi anche loro sparivano dietro le quinte.","zh":"随后，他们也退到了幕后。","t":[21462,24012]},{"it":"Allora toccava ai lampionai della Russia e delle Indie.","zh":"接着轮到俄罗斯和印度，再往后，是非洲和欧洲的点灯人。","t":[24012,27200]},{"it":"Poi a quelli dell’Africa e dell’Europa.","zh":"接替他们的，是南、北美洲的点灯人。","t":[27200,29550]},{"it":"Poi a quelli del Sudamerica.","zh":"这场宏大演出的次序，从来不乱。","t":[29550,31488]},{"it":"Poi a quelli del Nordamerica.","zh":"真是一幕壮丽的奇观！","t":[31488,33488]},{"it":"E mai che sbagliassero un’entrata in scena.","zh":"只有北极的点灯人，和他在南极的兄弟，过得悠闲自在。","t":[33488,35887]}]},{"id":"ch16p04","audio":true,"sents":[{"it":"Solo il lampionaio dell’unico lampione del Polo Nord e il suo collega dell’unico lampione del Polo Sud conducevano vite pigre e sfaccendate: lavoravano due volte l’anno.","zh":"他们每年只点亮、熄灭自己那盏灯，各一次。","t":[100,9700]}]}]},{"id":"ch17","title_it":"XVII","title_zh":"第 17 章","paras":[{"id":"ch17p00","audio":true,"sents":[{"it":"Quando uno vuole fare dello spirito, è facile che racconti qualche frottola.","zh":"想说句俏皮话，有时免不了要扯点小谎。","t":[100,4600]},{"it":"Parlandovi dei lampionai, non sono stato molto corretto.","zh":"讲点灯人大军时，我没能百分之百说实话。","t":[4600,8200]},{"it":"Rischio di dare a quelli che non lo conoscono un’idea sbagliata del nostro pianeta.","zh":"没见过这颗星球的人，说不定会得出错误的印象。","t":[8200,12912]},{"it":"Sulla Terra gli uomini occupano pochissimo spazio.","zh":"其实，人在地球上占的地方极小。","t":[12912,16238]},{"it":"Se i due miliardi di abitanti che popolano la Terra stessero in piedi e un po’ pigiati, come a un comizio, potrebbero occupare una piazza pubblica di venti miglia per venti miglia.","zh":"倘若二十亿地球人像开大会那样聚在一处，他们轻轻松松就能挤进一块长宽各二十英里的广场。","t":[16238,26275]},{"it":"Si potrebbe ammassare l’umanità su un qualsiasi isolotto del Pacifico.","zh":"全世界的居民，随便哪个太平洋小岛都能装下。","t":[26275,30350]}]},{"id":"ch17p01","audio":true,"sents":[{"it":"Gli adulti ovviamente non vi crederanno.","zh":"大人们自然不肯信。","t":[100,2675]},{"it":"Pensano di occupare molto spazio.","zh":"他们觉得自己又高大又了不起，像猴面包树似的。","t":[2675,4988]},{"it":"Si immaginano imponenti come baobab.","zh":"所以，您不妨让他们算算这笔账。","t":[4988,7700]},{"it":"Consigliategli di fare il calcolo.","zh":"他们爱死数字了，准会乐此不疲。","t":[7700,9812]},{"it":"Si divertiranno, perché adorano i numeri.","zh":"可您自己，还是别把时间浪费在这无聊又没用的事上。","t":[9812,12525]},{"it":"Ma voi non perdete tempo con questo compitino.","zh":"您是信我的吧？","t":[12525,15425]},{"it":"È inutile.","zh":"小王子一到地球，就惊讶不已。","t":[15425,16425]},{"it":"Fidatevi di me.","zh":"他一个人也没瞧见，竟担心自己找错了星球。","t":[16425,17300]}]},{"id":"ch17p02","audio":true,"sents":[{"it":"Così, una volta giunto sulla Terra, il piccolo principe fu stupito di non vedere nessuno.","zh":"这时，沙地上有一圈月白般的颜色蠕动了一下。","t":[100,6200]},{"it":"Temeva già di aver sbagliato pianeta quando un anello color della luna si mosse sulla sabbia.","zh":"——晚上好，——小王子随口打了个招呼。","t":[6200,11276]}]},{"id":"ch17p03","audio":true,"sents":[{"it":"“Buona notte,” disse il piccolo principe a casaccio.","zh":"——晚上好，——蛇说。","t":[100,3088]}]},{"id":"ch17p04","audio":true,"sents":[{"it":"“Buona notte,” fece il serpente.","zh":"——我这是到了哪颗星球？","t":[100,1913]}]},{"id":"ch17p05","audio":true,"sents":[{"it":"“Su quale pianeta sono finito?” domandò il piccolo principe.","zh":"——小王子问。","t":[100,3787]}]},{"id":"ch17p06","audio":true,"sents":[{"it":"“Sulla Terra, in Africa,” rispose il serpente.","zh":"——地球。","t":[100,2974]}]},{"id":"ch17p07","audio":true,"sents":[{"it":"“Ah!...","zh":"你在非洲，——蛇答道。","t":[100,750]},{"it":"Ma non c’è nessuno sulla Terra?”","zh":"这么说，地球上没有人住？","t":[750,2412]}]},{"id":"ch17p08","audio":true,"sents":[{"it":"“Qui siamo nel deserto.","zh":"——你是在沙漠里。","t":[100,1775]},{"it":"E nei deserti non c’è nessuno.","zh":"沙漠里，没人住。","t":[1775,3812]},{"it":"La Terra è grande,” disse il serpente.","zh":"地球大着呢，——蛇答道。","t":[3812,6126]}]},{"id":"ch17p09","audio":true,"sents":[{"it":"Il piccolo principe si sedette su un sasso e levò gli occhi verso il cielo.","zh":"小王子在一块石头上坐下，抬眼望向天空。","t":[100,4512]}]},{"id":"ch17p10","audio":true,"sents":[{"it":"“Mi domando,” disse, “se le stelle brillano perché un giorno ciascuno possa ritrovare la propria.","zh":"——真有意思，——他说，——星星发光，是为了让每个人，终有一天能找到自己的那颗吧？","t":[100,5462]},{"it":"Guarda il mio pianeta.","zh":"你瞧","t":[5462,6862]},{"it":"È esattamente sopra di noi...","zh":"我的星球。","t":[6862,8675]},{"it":"Ma com’è lontano!”","zh":"这会儿，它就正对着咱们头顶。","t":[8675,9850]}]},{"id":"ch17p11","audio":true,"sents":[{"it":"“È bello,” disse il serpente.","zh":"可它那么远！","t":[100,1950]},{"it":"“Che cosa sei venuto a fare qui?”","zh":"——它真美，——蛇说。","t":[1950,3526]}]},{"id":"ch17p12","audio":true,"sents":[{"it":"“Ho dei problemi con una rosa,” disse il piccolo principe.","zh":"——你到这儿来做什么？","t":[100,3125]}]},{"id":"ch17p13","audio":true,"sents":[{"it":"“Ah!” fece il serpente.","zh":"——我和一朵花闹了别扭，——小王子答道。","t":[100,1588]}]},{"id":"ch17p14","audio":true,"sents":[{"it":"E tacquero.","zh":"——明白了，——蛇说。","t":[100,862]}]},{"id":"ch17p15","audio":true,"sents":[{"it":"“Dove sono gli uomini?” riprese poi il piccolo principe.","zh":"——沉默片刻后，小王子接着问。","t":[100,3925]},{"it":"“Si è un po’ soli nel deserto...”","zh":"——在沙漠里，怪冷清的。","t":[3925,5650]}]},{"id":"ch17p16","audio":true,"sents":[{"it":"“Si è soli anche fra gli uomini,” disse il serpente.","zh":"——在人群里，也一样会孤单，——蛇答道。","t":[100,2900]}]},{"id":"ch17p17","audio":true,"sents":[{"it":"Il piccolo principe lo guardò lungamente:","zh":"小王子仔细打量着它。","t":[100,2450]}]},{"id":"ch17p18","audio":true,"sents":[{"it":"“Sei uno strano animale,” gli disse alla fine, “sottile come un dito...”","zh":"——你真有意思，——他终于说。","t":[100,4113]}]},{"id":"ch17p19","audio":true,"sents":[{"it":"“Ma sono più potente del dito di un re,” disse il serpente.","zh":"——细得像……","t":[100,3226]}]},{"id":"ch17p20","audio":true,"sents":[{"it":"Il piccolo principe sorrise:","zh":"像一根手指。","t":[100,1874]}]},{"id":"ch17p21","audio":true,"sents":[{"it":"“Non si direbbe...","zh":"——我可比国王的手指还厉害呢，——蛇说。","t":[100,1325]},{"it":"non hai neanche le zampe...","zh":"小王子笑了：——你可算不上厉害。","t":[1325,2975]},{"it":"non puoi neanche viaggiare...”","zh":"你连爪子都没有，也没法去远行。","t":[2975,4488]}]},{"id":"ch17p22","audio":true,"sents":[{"it":"“Ti posso portare più lontano di quanto possa fare una nave,” disse il serpente.","zh":"——可是，我能比任何船都送你走得更远，——蛇说。","t":[100,4350]}]},{"id":"ch17p23","audio":true,"sents":[{"it":"Si avvolse intorno alla caviglia del piccolo principe, come una catenina d’oro:","zh":"说着，它像一只金镯子，缠上了小王子的脚踝。","t":[100,4537]}]},{"id":"ch17p24","audio":true,"sents":[{"it":"“Chiunque tocco, lo restituisco alla terra da cui proviene,” disse ancora.","zh":"——凡被我碰过的，都会回到他来的那片土地去，——它补了一句。","t":[100,4525]},{"it":"“Ma tu sei puro e vieni da una stella...”","zh":"——可你是洁净的，因为你来自星星。","t":[4525,6837]}]},{"id":"ch17p25","audio":true,"sents":[{"it":"Il piccolo principe non disse nulla.","zh":"——我怜惜你，——蛇接着说。","t":[100,2212]}]},{"id":"ch17p26","audio":true,"sents":[{"it":"“Mi fai pena, così fragile su questa Terra di granito.","zh":"在这石头般的地球上，你太柔弱了。","t":[100,3700]},{"it":"Se un giorno dovessi rimpiangere troppo il tuo pianeta, posso aiutarti.","zh":"说不定哪天，你要是后悔离开了星球，我能帮上忙。","t":[3700,8062]},{"it":"Posso...”","zh":"我本可以……","t":[8062,8624]}]},{"id":"ch17p27","audio":true,"sents":[{"it":"“Oh, ho capito benissimo,” fece il piccolo principe, “ma perché parli sempre per enigmi?”","zh":"——我明白你的意思，——小王子答道。","t":[100,5075]}]},{"id":"ch17p28","audio":true,"sents":[{"it":"“Li risolvo tutti,” disse il serpente.","zh":"——可你为什么老说些谜语？","t":[100,2324]}]},{"id":"ch17p29","audio":true,"sents":[{"it":"E tacquero.","zh":"——我的谜语，我自己来解，——蛇说。两人都不再作声。","t":[100,862]}]}]},{"id":"ch18","title_it":"XVIII","title_zh":"第 18 章","paras":[{"id":"ch18p00","audio":true,"sents":[{"it":"Il piccolo principe attraversò il deserto e incontrò soltanto un fiore.","zh":"小王子穿过沙漠，途中只遇见一朵花。","t":[100,4500]},{"it":"Un fiore con tre petali, un fiore da niente...","zh":"它只有三片花瓣，毫不起眼。","t":[4500,7337]}]},{"id":"ch18p01","audio":true,"sents":[{"it":"“Buongiorno,” disse il piccolo principe.","zh":"——你好，——小王子说。","t":[100,2226]}]},{"id":"ch18p02","audio":true,"sents":[{"it":"“Buongiorno,” disse il fiore.","zh":"——你好，——花儿答道。","t":[100,1626]}]},{"id":"ch18p03","audio":true,"sents":[{"it":"“Dove sono gli uomini?” domandò gentilmente il piccolo principe.","zh":"——那人们都在哪儿？","t":[100,4337]}]},{"id":"ch18p04","audio":true,"sents":[{"it":"Un giorno il fiore aveva visto passare una carovana:","zh":"——小王子客气地问。","t":[100,3112]}]},{"id":"ch18p05","audio":true,"sents":[{"it":"“Gli uomini?","zh":"花儿曾经见过一支商队从旁边经过。","t":[100,1238]},{"it":"Credo ce ne siano sei o sette.","zh":"我想，有六七个吧。","t":[1238,3250]},{"it":"Li ho intravisti anni fa.","zh":"那还是好多年前，我见过他们。","t":[3250,4900]},{"it":"Ma non si sa mai dove trovarli.","zh":"你永远说不准，上哪儿去找他们。","t":[4900,6912]},{"it":"Vanno in balìa del vento.","zh":"风把他们吹得到处跑。","t":[6912,8638]},{"it":"Non hanno radici, e questo per loro è un bel problema.”","zh":"他们又没有根，这就麻烦……","t":[8638,12187]}]},{"id":"ch18p06","audio":true,"sents":[{"it":"“Addio,” fece il piccolo principe.","zh":"——再见，——小王子说。","t":[100,2112]}]},{"id":"ch18p07","audio":true,"sents":[{"it":"“Addio,” disse il fiore.","zh":"——再见，——花儿答道。","t":[100,1488]}]}]},{"id":"ch19","title_it":"XIX","title_zh":"第 19 章","paras":[{"id":"ch19p00","audio":true,"sents":[{"it":"Il piccolo principe scalò un’alta montagna.","zh":"小王子登上一座高山。","t":[100,2950]},{"it":"Le uniche montagne che avesse mai conosciuto erano i tre vulcani che gli arrivavano al ginocchio.","zh":"他从前见过的山，只有自己星球上的三座火山。","t":[2950,8550]},{"it":"Adoperava il vulcano spento come uno sgabello.","zh":"它们都不高——刚到他的膝盖，那座死火山，他还当凳子坐。","t":[8550,11688]},{"it":"“Da una montagna così alta,” si disse quindi, “vedrò l’intero pianeta e tutti gli uomini...” Ma vide soltanto alcuni picchi aguzzi.","zh":"所以","t":[11688,19412]}]},{"id":"ch19p01","audio":true,"sents":[{"it":"“Buongiorno,” disse a casaccio.","zh":"所以","t":[100,1812]}]},{"id":"ch19p02","audio":true,"sents":[{"it":"“Buongiorno...","zh":"小王子想，从这么高的山上，准能一眼望见整颗星球和上面所有的人。","t":[100,1075]},{"it":"buongiorno...","zh":"可他什么也没看见，只有尖削的岩石。","t":[1075,2025]},{"it":"buongiorno...” rispose l’eco.","zh":"——你好，——他随口打了个招呼。","t":[2025,3900]}]},{"id":"ch19p03","audio":true,"sents":[{"it":"“Chi siete?” disse il piccolo principe.","zh":"——你好，你好，你好，——回声应道。","t":[100,2675]}]},{"id":"ch19p04","audio":true,"sents":[{"it":"“Chi siete...","zh":"——你们是谁？","t":[100,1062]},{"it":"chi siete...","zh":"——你们是谁？","t":[1062,2025]},{"it":"chi siete...” rispose l’eco.","zh":"——小王子问。","t":[2025,3875]}]},{"id":"ch19p05","audio":true,"sents":[{"it":"“Siate miei amici, sono solo,” disse.","zh":"——你们是谁，你们是谁，你们是谁？","t":[100,2350]}]},{"id":"ch19p06","audio":true,"sents":[{"it":"“Sono solo...","zh":"——回声问。","t":[100,1125]},{"it":"sono solo...","zh":"——做我的朋友吧，——小王子提议，——我好孤单。","t":[1125,2088]},{"it":"sono solo...” rispose l’eco.","zh":"——我孤单，我孤单，我孤单，——回声重复着。","t":[2088,3950]}]},{"id":"ch19p07","audio":true,"sents":[{"it":"“Che strano pianeta!” pensò allora.","zh":"“这是颗多古怪的星球啊，”小王子想，“又干，又尖，又咸。","t":[100,2725]},{"it":"“È tutto secco, appuntito e salato.","zh":"“这是颗多古怪的星球啊，”小王子想，“又干，又尖，又咸。","t":[2725,5450]},{"it":"E gli uomini sono privi di immaginazione.","zh":"人呢，一点想象力也没有。","t":[5450,8075]},{"it":"Ripetono tutto quello che gli dici...","zh":"只会重复别人说的话。","t":[8075,10638]},{"it":"Dove stavo io avevo una rosa: era sempre lei la prima a parlare...”","zh":"可在我的星球上，有一朵花，我的美人儿，她总是先开口跟我说话。”","t":[10638,14500]}]}]},{"id":"ch20","title_it":"XX","title_zh":"第 20 章","paras":[{"id":"ch20p00","audio":true,"sents":[{"it":"Ma un bel giorno, dopo aver camminato a lungo sulla sabbia, sulle rocce, sulla neve, il piccolo principe si imbatté finalmente in una strada.","zh":"就这样，小王子穿过沙地，越过岩石和雪原，终于撞见了一条路。","t":[100,9075]},{"it":"E le strade vanno tutte dove ci sono gli uomini.","zh":"天下的路，都通向有人烟的地方。","t":[9075,11588]}]},{"id":"ch20p01","audio":true,"sents":[{"it":"“Buongiorno,” disse.","zh":"——你们好，——小王子说。","t":[100,1225]}]},{"id":"ch20p02","audio":true,"sents":[{"it":"Era un giardino di rose.","zh":"——你们好，——玫瑰们说。","t":[100,1463]}]},{"id":"ch20p03","audio":true,"sents":[{"it":"“Buongiorno,” dissero le rose.","zh":"小王子望望她们，觉得她们和他的那朵花十分相像。","t":[100,1800]}]},{"id":"ch20p04","audio":true,"sents":[{"it":"Il piccolo principe le guardò.","zh":"——你们是谁？","t":[100,2062]},{"it":"Assomigliavano tutte al suo fiore.","zh":"——他被眼前的景象惊住了，问道。","t":[2062,3900]}]},{"id":"ch20p05","audio":true,"sents":[{"it":"“Chi siete?” domandò stupefatto.","zh":"——我们是玫瑰，——玫瑰们答道。","t":[100,2450]}]},{"id":"ch20p06","audio":true,"sents":[{"it":"“Siamo le rose,” dissero le rose.","zh":"——是吗？","t":[100,2000]}]},{"id":"ch20p07","audio":true,"sents":[{"it":"“Ah!” fece il piccolo principe...","zh":"他觉得自己好不辛酸。","t":[100,2162]}]},{"id":"ch20p08","audio":true,"sents":[{"it":"E si sentì molto infelice.","zh":"他的那朵花曾对他说，自己是普天之下独一无二的。","t":[100,1988]},{"it":"La sua rosa gli aveva detto di essere l’unica in tutto l’universo.","zh":"可这儿，单单一个园子里，就不下五千朵！","t":[1988,6112]},{"it":"E invece ce n’erano cinquemila, tutte uguali, in un solo giardino!","zh":"“我的美人儿要是见了这光景，”小王子想，“准会伤心透顶。","t":[6112,10526]}]},{"id":"ch20p09","audio":true,"sents":[{"it":"“Se le vedesse, ci rimarrebbe malissimo...” pensò, “tossirebbe a più non posso e farebbe finta di morire per levarsi dall’imbarazzo.","zh":"为了不显得滑稽，她多半会拼命咳嗽，装出快死的样子。","t":[100,7975]},{"it":"E sarei costretto a far finta di curarla perché altrimenti, per umiliare anche me, si lascerebbe davvero morire...”","zh":"而我，就得装作照料她的样子。","t":[7975,14326]}]},{"id":"ch20p10","audio":true,"sents":[{"it":"Poi si disse ancora: “Credevo di possedere un fiore unico, e invece ho solo una rosa uguale a tante altre.","zh":"接着他又暗自道：“我原以为自己是个富翁，拥有一朵举世无双的花，到头来不过是一朵寻常的玫瑰。","t":[100,6788]},{"it":"Lei e i miei tre vulcani che mi arrivano al ginocchio, di cui uno forse spento per sempre, non fanno di me un gran principe...”.","zh":"她，加上三座火山——其中一座还灭了，说不定永远灭着——这点家当，对于一个真正的王子，实在少得可怜。”","t":[6788,14050]},{"it":"E steso sull’erba pianse.","zh":"说着，他扑倒在草地上，哭了起来。","t":[14050,15700]}]}]},{"id":"ch21","title_it":"XXI","title_zh":"第 21 章","paras":[{"id":"ch21p00","audio":true,"sents":[{"it":"Fu allora che comparve la volpe:","zh":"这时，狐狸出现了。","t":[100,1900]}]},{"id":"ch21p01","audio":true,"sents":[{"it":"“Buongiorno,” disse la volpe.","zh":"——你好，——他说。","t":[100,1688]}]},{"id":"ch21p02","audio":true,"sents":[{"it":"“Buongiorno,” rispose gentilmente il piccolo principe, che si voltò ma non vide nulla.","zh":"——你好，——小王子彬彬有礼地答道。","t":[100,5074]}]},{"id":"ch21p03","audio":true,"sents":[{"it":"“Sono qui,” disse la voce, “sotto il melo...”","zh":"可他转过身，却什么人也没看见。","t":[100,2612]}]},{"id":"ch21p04","audio":true,"sents":[{"it":"“Chi sei?” disse il piccolo principe.","zh":"——我在这儿，——一个声音传来，——在苹果树底下。","t":[100,2838]},{"it":"“Sei proprio graziosa...”","zh":"——你是谁？","t":[2838,4274]}]},{"id":"ch21p05","audio":true,"sents":[{"it":"“Sono una volpe,” disse la volpe.","zh":"——小王子问。","t":[100,2000]}]},{"id":"ch21p06","audio":true,"sents":[{"it":"“Vieni a giocare con me,” le propose il piccolo principe, “sono tanto triste.”","zh":"——你真好看……","t":[100,4362]}]},{"id":"ch21p07","audio":true,"sents":[{"it":"“Non posso giocare con te,” disse la volpe.","zh":"——我是一只狐狸，——狐狸答道。","t":[100,2625]},{"it":"“Non sono addomesticata.”","zh":"——你不想跟我玩玩吗？","t":[2625,4200]}]},{"id":"ch21p08","audio":true,"sents":[{"it":"“Ah!","zh":"——小王子提议。","t":[100,750]},{"it":"Scusa,” fece il piccolo principe.","zh":"——我心里好难过……","t":[750,2750]}]},{"id":"ch21p09","audio":true,"sents":[{"it":"Ma, dopo averci pensato un po’, aggiunse:","zh":"——我没法跟你玩，——狐狸答道。","t":[100,2987]}]},{"id":"ch21p10","audio":true,"sents":[{"it":"“Che cosa significa ‘addomesticare’?”","zh":"——我还没被驯养。","t":[100,2026]}]},{"id":"ch21p11","audio":true,"sents":[{"it":"“Tu non sei di qui,” disse la volpe, “che cosa stai cercando?”","zh":"——啊……","t":[100,3537]}]},{"id":"ch21p12","audio":true,"sents":[{"it":"“Cerco gli uomini,” disse il piccolo principe.","zh":"那，真抱歉，——小王子说。","t":[100,2862]},{"it":"“Che cosa significa ‘addomesticare’?”","zh":"可他想了想，又问：——“驯养”是什么意思？","t":[2862,4788]}]},{"id":"ch21p13","audio":true,"sents":[{"it":"“Gli uomini,” disse la volpe, “hanno i fucili e cacciano.","zh":"——我看你不是本地人，——狐狸答道。","t":[100,3900]},{"it":"È una gran seccatura!","zh":"——你在这儿找什么？","t":[3900,5550]},{"it":"Allevano anche le galline.","zh":"——我找人，——小王子说。","t":[5550,7225]},{"it":"È l’unica cosa interessante.","zh":"——那“驯养”到底是什么意思？","t":[7225,9138]},{"it":"Cerchi delle galline?”","zh":"——人哪，——狐狸说，——他们有枪，还打猎。","t":[9138,10300]}]},{"id":"ch21p14","audio":true,"sents":[{"it":"“No,” disse il piccolo principe.","zh":"这真叫人受不了。","t":[100,2175]},{"it":"“Cerco degli amici.","zh":"而且他们还养鸡。","t":[2175,4088]},{"it":"Che cosa significa ‘addomesticare’?”","zh":"他们只操心这个。","t":[4088,6013]}]},{"id":"ch21p15","audio":true,"sents":[{"it":"“È una cosa troppo dimenticata,” disse la volpe.","zh":"你找鸡吗？","t":[100,2900]},{"it":"“Significa ‘creare dei legami’...”","zh":"——不，——小王子答道。","t":[2900,4787]}]},{"id":"ch21p16","audio":true,"sents":[{"it":"“Creare dei legami?”","zh":"——我找朋友。","t":[100,1263]}]},{"id":"ch21p17","audio":true,"sents":[{"it":"“Certo,” disse la volpe.","zh":"那“驯养”到底是什么意思？","t":[100,1838]},{"it":"“Per me, ora tu sei solo un bambino uguale a centomila altri bambini.","zh":"——这是一件早被忘掉的事，——狐狸答道。","t":[1838,6112]},{"it":"E non ho bisogno di te.","zh":"——意思是，建立牵系。","t":[6112,7575]},{"it":"Né tu hai bisogno di me.","zh":"——建立牵系？","t":[7575,9275]},{"it":"Per te, sono soltanto una volpe uguale a centomila altre volpi.","zh":"——正是，——狐狸说。","t":[9275,13450]},{"it":"Ma se mi addomestichi, avremo bisogno l’uno dell’altra.","zh":"——此刻的你，不过是个小男孩，跟十万个别的小男孩一模一样。","t":[13450,16838]},{"it":"Per me tu sarai unico al mondo.","zh":"我不需要你。","t":[16838,18762]},{"it":"Per te io sarò unica al mondo...”","zh":"对你来说，我也是只狐狸，跟十万只别的狐狸毫无二致。","t":[18762,20424]}]},{"id":"ch21p18","audio":true,"sents":[{"it":"“Comincio a capire,” disse il piccolo principe.","zh":"可一旦你驯养了我，我们便彼此需要了。","t":[100,2775]},{"it":"“C’è una rosa...","zh":"你于我，会是世上唯一的；我于你，也会是唯一的。","t":[2775,3850]},{"it":"credo che mi abbia addomesticato...”","zh":"——我好像有点明白了，——小王子说。","t":[3850,5613]}]},{"id":"ch21p19","audio":true,"sents":[{"it":"“È possibile,” disse la volpe.","zh":"——我有一朵花，我的美人儿……","t":[100,2100]},{"it":"“Sulla Terra capita di tutto...”","zh":"我觉得，是她驯养了我。","t":[2100,3700]}]},{"id":"ch21p20","audio":true,"sents":[{"it":"“Oh!","zh":"——那是可能的，——狐狸答道。","t":[100,812]},{"it":"Non è sulla Terra,” disse il piccolo principe.","zh":"——在地球上，什么事都可能发生……","t":[812,3312]}]},{"id":"ch21p21","audio":true,"sents":[{"it":"La volpe parve molto incuriosita:","zh":"——这可不是在地球上发生的，——小王子说。","t":[100,2326]}]},{"id":"ch21p22","audio":true,"sents":[{"it":"“Su un altro pianeta?”","zh":"狐狸大吃一惊：——在别的星球上？","t":[100,1300]}]},{"id":"ch21p23","audio":true,"sents":[{"it":"“Sì.”","zh":"——对。","t":[100,562]}]},{"id":"ch21p24","audio":true,"sents":[{"it":"“E ci sono cacciatori, su quel pianeta?”","zh":"——那儿有猎人吗？","t":[100,2626]}]},{"id":"ch21p25","audio":true,"sents":[{"it":"“No.”","zh":"——没有。","t":[100,462]}]},{"id":"ch21p26","audio":true,"sents":[{"it":"“Ah, molto interessante!","zh":"——有鸡吗？","t":[100,2162]},{"it":"E galline?”","zh":"——没有。","t":[2162,2887]}]},{"id":"ch21p27","audio":true,"sents":[{"it":"“No.”","zh":"——这世上没有十全十美的事，——狐狸叹了口气。","t":[100,462]}]},{"id":"ch21p28","audio":true,"sents":[{"it":"“Nulla è perfetto,” sospirò la volpe.","zh":"可他又回到原来的话题：“你瞧，我的日子相当单调。","t":[100,2387]}]},{"id":"ch21p29","audio":true,"sents":[{"it":"Ma la volpe tornò alla sua idea:","zh":"我追鸡，猎人追我。","t":[100,2000]}]},{"id":"ch21p30","audio":true,"sents":[{"it":"“Ho una vita monotona.","zh":"所有的鸡都一个样，所有的人也都彼此相像。","t":[100,1600]},{"it":"Io do la caccia alle galline e gli uomini danno la caccia a me.","zh":"所以我有点腻烦。","t":[1600,5175]},{"it":"Tutte le galline si assomigliano, e tutti gli uomini si assomigliano.","zh":"可你要是驯养了我，我的生活便仿佛洒满了阳光。","t":[5175,9350]},{"it":"Quindi mi annoio un po’.","zh":"我能认出你脚步的声音，那声音，和所有人的都不一样。","t":[9350,10850]},{"it":"Ma se tu mi addomestichi, la mia vita sarà come inondata di luce.","zh":"别人的脚步声，我就钻回地底；你的，却会把我从洞里唤出来。","t":[10850,14975]},{"it":"Conoscerò un rumore di passi diverso da tutti gli altri.","zh":"它在我听来，就像音乐。","t":[14975,18550]},{"it":"Gli altri passi mi fanno fuggire sotto terra.","zh":"还有，你瞧！","t":[18550,21238]},{"it":"Il tuo mi chiamerà fuori dalla tana, come una musica.","zh":"那边那片麦田，看见了吗？","t":[21238,24600]},{"it":"E poi guarda!","zh":"我不吃面包。","t":[24600,25788]},{"it":"Li vedi laggiù, i campi di grano?","zh":"麦子对我毫无用处。","t":[25788,28150]},{"it":"Io non mangio pane.","zh":"而麦田","t":[28150,29500]},{"it":"Quindi per me il grano è inutile.","zh":"对我毫无意义，想想也够叫人伤感的。","t":[29500,31812]},{"it":"I campi di grano non mi dicono niente.","zh":"可你的头发是金色的。","t":[31812,34138]},{"it":"E questo è molto triste!","zh":"你想想，等你驯养了我，该多美呀？","t":[34138,36000]},{"it":"Ma tu hai capelli color dell’oro.","zh":"金色的麦浪，会让我想起你。","t":[36000,38000]},{"it":"E allora sarà bellissimo quando mi avrai addomesticato!","zh":"我会爱上它在风里沙沙作响的声音……","t":[38000,41375]},{"it":"Il grano, che è dorato, mi farà pensare a te.","zh":"狐狸住了口，久久地望着小王子：“求求你，驯养我吧！”","t":[41375,44600]},{"it":"E mi piacerà il rumore del vento nel grano...”","zh":"——我也乐意，——小王子答道。","t":[44600,47000]}]},{"id":"ch21p31","audio":true,"sents":[{"it":"La volpe tacque e guardò a lungo il piccolo principe.","zh":"——可我的时间不多。","t":[100,3188]}]},{"id":"ch21p32","audio":true,"sents":[{"it":"“Per favore...","zh":"我得去找朋友，还有那么多东西要懂。","t":[100,1075]},{"it":"addomesticami!” disse.","zh":"——人已经没有耐性，去好好懂点什么了。","t":[1075,2925]}]},{"id":"ch21p33","audio":true,"sents":[{"it":"“Lo farei volentieri,” rispose il piccolo principe, “ma non ho molto tempo.","zh":"商人把现成的东西卖给他们。","t":[100,4525]},{"it":"Ho amici da scoprire e molte cose da conoscere.”","zh":"却没有哪个商人，出售朋友。","t":[4525,7088]}]},{"id":"ch21p34","audio":true,"sents":[{"it":"“Conosciamo soltanto le cose che addomestichiamo,” disse la volpe.","zh":"所以人也就没有朋友。","t":[100,3800]},{"it":"“Gli uomini non hanno più tempo per conoscere nulla.","zh":"你要是想找个朋友，就驯养我吧！","t":[3800,6750]},{"it":"Comprano le cose già fatte nei negozi.","zh":"——那该怎么做呢？","t":[6750,9300]},{"it":"Ma siccome non esistono negozi che vendono amici, gli uomini non hanno più amici.","zh":"——小王子问。","t":[9300,14950]},{"it":"Se vuoi un amico, addomesticami!”","zh":"——得极有耐心，——狐狸答道。","t":[14950,17387]}]},{"id":"ch21p35","audio":true,"sents":[{"it":"“Come si fa?” disse il piccolo principe.","zh":"——先像这样，在离我稍远些的草地上坐下。","t":[100,2637]}]},{"id":"ch21p36","audio":true,"sents":[{"it":"“Ci vuole molta pazienza,” rispose la volpe.","zh":"我拿眼角瞄着你，你什么也别说。","t":[100,2775]},{"it":"“Prima dovrai sederti un po’ lontano da me, così, nell’erba.","zh":"言语，是误会的根源。","t":[2775,6738]},{"it":"Io ti guarderò con la coda dell’occhio e tu non dirai niente.","zh":"不过，一天天过去，你可以坐得离我近一点……","t":[6738,10525]},{"it":"Il linguaggio è fonte di malintesi.","zh":"第二天，小王子又来和狐狸相会。","t":[10525,12825]},{"it":"Ma ogni giorno potrai sederti un po’ più vicino...”","zh":"——最好，——狐狸说，——你每天同一个时辰来。","t":[12825,15537]}]},{"id":"ch21p37","audio":true,"sents":[{"it":"L’indomani il piccolo principe tornò.","zh":"比如你下午四点来，从三点起，我就开始欢喜了。","t":[100,2312]}]},{"id":"ch21p38","audio":true,"sents":[{"it":"“Sarebbe stato meglio se fossi venuto alla stessa ora,” disse la volpe.","zh":"越是临近相会的时刻，我就越发高兴。","t":[100,3875]},{"it":"“Se per esempio verrai alle quattro del pomeriggio, già dalle tre io comincerò a essere felice.","zh":"到了四点整，我就会坐立不安、心慌起来。","t":[3875,9438]},{"it":"Più il tempo passerà e più mi sentirò felice.","zh":"这样，我便懂得了“幸福”的代价！","t":[9438,12300]},{"it":"Finché alle quattro sarò tutta agitata e in apprensione: scoprirò il valore della felicità!","zh":"可你要是每次来的时辰都不一样，我就不知道该什么时候开始盼着相会……","t":[12300,17762]},{"it":"Ma se vieni quando capita, non saprò mai a che ora vestirmi il cuore...","zh":"得有个仪式……","t":[17762,21825]},{"it":"I riti sono importanti.”","zh":"——“仪式”是什么？","t":[21825,23400]}]},{"id":"ch21p39","audio":true,"sents":[{"it":"“Che cos’è un rito?” disse il piccolo principe.","zh":"——小王子问。","t":[100,3188]}]},{"id":"ch21p40","audio":true,"sents":[{"it":"“Anche questa è una cosa troppo dimenticata,” disse la volpe.","zh":"——也是件早被忘掉的事，——狐狸答道。","t":[100,3662]},{"it":"“È ciò che rende un giorno diverso dagli altri giorni, un’ora diversa dalle altre ore.","zh":"——它让某一天不同于别的日子，让某一时刻变得特别。","t":[3662,8762]},{"it":"I miei cacciatori, per esempio, hanno un rito.","zh":"比如，我的那些猎人，有个仪式。","t":[8762,12188]},{"it":"Il giovedì ballano con le ragazze del villaggio.","zh":"每星期四，他们和村里的姑娘跳舞。","t":[12188,14888]},{"it":"Allora il giovedì è una giornata meravigliosa!","zh":"所以星期四，对他们来说就是好日子。","t":[14888,17662]},{"it":"E io vado a fare una passeggiata fino alla vigna.","zh":"那会儿我就能一路溜达到葡萄园去。","t":[17662,20362]},{"it":"Se i cacciatori ballassero quando capita, i giorni sarebbero tutti uguali, e non avrei mai vacanza.”","zh":"要是猎人爱跳就跳，所有的日子就都一个样了，我也没法给自己找点小乐趣。","t":[20362,26224]}]},{"id":"ch21p41","audio":true,"sents":[{"it":"Così il piccolo principe addomesticò la volpe.","zh":"终于，小王子驯养了狐狸。可临到分别，狐狸叹道：——没了你，我会哭的。","t":[100,3238]},{"it":"E quando si avvicinò il momento della partenza:","zh":"——这怨不得别人，——小王子说。","t":[3238,5813]}]},{"id":"ch21p42","audio":true,"sents":[{"it":"“Ah!” disse la volpe...","zh":"——我本不想让你难过。","t":[100,2012]},{"it":"“Piangerò.”","zh":"是你自己，要我驯养你的。","t":[2012,2637]}]},{"id":"ch21p43","audio":true,"sents":[{"it":"“È colpa tua,” disse il piccolo principe, “io non volevo farti soffrire, ma tu mi hai chiesto di addomesticarti...”","zh":"——这倒是，——狐狸说。","t":[100,6512]}]},{"id":"ch21p44","audio":true,"sents":[{"it":"“Certo,” disse la volpe.","zh":"——可你也会哭的！","t":[100,1575]}]},{"id":"ch21p45","audio":true,"sents":[{"it":"“Però piangerai!” disse il piccolo principe.","zh":"——那当然，——狐狸叹道。","t":[100,3213]}]},{"id":"ch21p46","audio":true,"sents":[{"it":"“Certo,” disse la volpe.","zh":"——那你到底得了什么好处呢？","t":[100,1575]}]},{"id":"ch21p47","audio":true,"sents":[{"it":"“Allora non ci guadagni niente!”","zh":"——如今，麦子的颜色会对我说起好多事……","t":[100,1787]}]},{"id":"ch21p48","audio":true,"sents":[{"it":"“Ci guadagno,” disse la volpe, “a causa del colore del grano.”","zh":"接着狐狸说：——去吧，再去看一眼那些玫瑰，这回你会明白，你的玫瑰是世上唯一的。","t":[100,3588]}]},{"id":"ch21p49","audio":true,"sents":[{"it":"Poi aggiunse:","zh":"等你回来向我道别，我再告诉你一个秘密。","t":[100,1026]}]},{"id":"ch21p50","audio":true,"sents":[{"it":"“Vai a rivedere le rose.","zh":"于是小王子走去，看那些玫瑰。","t":[100,1650]},{"it":"Capirai che la tua è unica al mondo.","zh":"——你们和我的玫瑰一点都不像，——他对她们说。","t":[1650,3850]},{"it":"Quando tornerai a salutarmi, ti regalerò un segreto.”","zh":"——你们根本不是她。","t":[3850,7062]}]},{"id":"ch21p51","audio":true,"sents":[{"it":"Il piccolo principe andò a rivedere le rose:","zh":"你们谁也没被驯养过，也没驯养过谁。","t":[100,2463]}]},{"id":"ch21p52","audio":true,"sents":[{"it":"“Non assomigliate affatto alla mia rosa, non siete ancora niente,” disse loro.","zh":"你们就像我那狐狸当初的样子。","t":[100,4712]},{"it":"“Nessuno vi ha addomesticate e voi non avete addomesticato nessuno.","zh":"他当初和十万只别的狐狸一模一样。可","t":[4712,8725]},{"it":"Siete com’era la mia volpe.","zh":"他成了我的朋友，如今于我，是这世上唯一的。","t":[8725,10462]},{"it":"Era solo una volpe uguale a centomila altre.","zh":"玫瑰们仿佛被他的话触动了。","t":[10462,13350]},{"it":"Ma ho fatto di lei la mia amica e ora è unica al mondo.”","zh":"——你们很美，——小王子补了一句，——却是空的。","t":[13350,16625]}]},{"id":"ch21p53","audio":true,"sents":[{"it":"Le rose erano molto imbarazzate.","zh":"不值得为你们去死。","t":[100,2162]}]},{"id":"ch21p54","audio":true,"sents":[{"it":"“Siete belle, ma siete vuote,” disse ancora.","zh":"当然，我的玫瑰……","t":[100,3188]},{"it":"“Non si può morire per voi.","zh":"一个过路人，准会说她跟你们一个样。","t":[3188,4938]},{"it":"Certo, un passante qualsiasi penserebbe che la mia rosa vi assomigli.","zh":"可对我来说，她比你们全都重要。","t":[4938,9438]},{"it":"Ma lei da sola è più importante di tutte voi, perché è quella che ho innaffiato.","zh":"因为我给她浇过水，用玻璃罩护过她。","t":[9438,14450]},{"it":"Perché l’ho messa sotto la campana di vetro.","zh":"正是她，我用屏风遮过，把毛毛虫从她身上赶走——只留下两三只要它们变蝴蝶。","t":[14450,16962]},{"it":"Perché l’ho protetta con il paravento.","zh":"我听过她的抱怨和吹嘘。","t":[16962,19225]},{"it":"Perché ho ucciso i bruchi (tranne due o tre per le farfalle).","zh":"连她沉默不语，我也听得出。","t":[19225,23050]},{"it":"Perché l’ho ascoltata lamentarsi, o vantarsi o a volte anche tacere.","zh":"因为，她是我的玫瑰！","t":[23050,27312]},{"it":"Perché è la mia rosa.”","zh":"接着，他回到狐狸身边。","t":[27312,28512]}]},{"id":"ch21p55","audio":true,"sents":[{"it":"E tornò dalla volpe:","zh":"——再见，——他对狐狸说。","t":[100,1325]}]},{"id":"ch21p56","audio":true,"sents":[{"it":"“Addio...” disse.","zh":"——再见，——狐狸答道。","t":[100,1550]}]},{"id":"ch21p57","audio":true,"sents":[{"it":"“Addio,” disse la volpe.","zh":"——这是我的秘密。","t":[100,1788]},{"it":"“Ecco il mio segreto.","zh":"它很简单。","t":[1788,3175]},{"it":"È molto semplice: si vede solo con il cuore.","zh":"只有用心，才能看清楚。","t":[3175,6175]},{"it":"L’essenziale è invisibile agli occhi.”","zh":"最重要的东西，用眼睛是看不见的。","t":[6175,8250]}]},{"id":"ch21p58","audio":true,"sents":[{"it":"“L’essenziale è invisibile agli occhi,” ripeté il piccolo principe, per tenerlo a mente.","zh":"——最重要的东西，用眼睛是看不见的，——小王子重复着，好把它记住。","t":[100,4912]}]},{"id":"ch21p59","audio":true,"sents":[{"it":"“Il tempo che hai perso per la tua rosa è ciò che fa la tua rosa tanto importante.”","zh":"——正是因为你为你的玫瑰，花费了时间，她才对你变得如此重要。","t":[100,4763]}]},{"id":"ch21p60","audio":true,"sents":[{"it":"“Il tempo che ho perso per la mia rosa...” ripeté il piccolo principe, per tenerlo a mente.","zh":"——我为我的玫瑰，花费的时间……——小王子重复着，好把它记住。","t":[100,5162]}]},{"id":"ch21p61","audio":true,"sents":[{"it":"“Gli uomini hanno dimenticato questa verità,” disse la volpe.","zh":"——人把这条真理忘了，——狐狸说。","t":[100,3625]},{"it":"“Ma tu non devi dimenticarla.","zh":"——可你不该把它忘了。","t":[3625,5538]},{"it":"Diventi responsabile per sempre di ciò che hai addomesticato.","zh":"你要对你驯养过的一切，永远负责。","t":[5538,9112]},{"it":"Tu sei responsabile della tua rosa...”","zh":"你也要对你的玫瑰负责。","t":[9112,11275]}]},{"id":"ch21p62","audio":true,"sents":[{"it":"“Sono responsabile della mia rosa...” ripeté il piccolo principe, per tenerlo a mente.","zh":"——我对我的玫瑰负责，——小王子重复着，好把它记住。","t":[100,5100]}]}]},{"id":"ch22","title_it":"XXII","title_zh":"第 22 章","paras":[{"id":"ch22p00","audio":true,"sents":[{"it":"“Buongiorno,” disse il piccolo principe.","zh":"“你好，”小王子说。","t":[100,2226]}]},{"id":"ch22p01","audio":true,"sents":[{"it":"“Buongiorno,” disse l’addetto agli scambi.","zh":"“你好，”扳道工回答。","t":[100,2387]}]},{"id":"ch22p02","audio":true,"sents":[{"it":"“Che cosa fai qui?” disse il piccolo principe.","zh":"“你在这里做什么？”","t":[100,2800]}]},{"id":"ch22p03","audio":true,"sents":[{"it":"“Smisto i viaggiatori, a migliaia,” disse l’addetto agli scambi.","zh":"“我把乘客分类，成千上万地，”扳道工回答。","t":[100,4288]},{"it":"“Mando via i treni che li portano lontano, ora verso destra ora verso sinistra.”","zh":"“我发出一列列火车，把他们带走——有的向右，有的向左。”","t":[4288,9087]}]},{"id":"ch22p04","audio":true,"sents":[{"it":"E un rapido tutto illuminato passò rombante come un tuono e fece tremare la cabina dell’addetto agli scambi.","zh":"就在这时，一列灯火通明的快车从扳道工颤抖的小屋旁轰隆隆驶过。","t":[100,6387]}]},{"id":"ch22p05","audio":true,"sents":[{"it":"“Vanno proprio di fretta,” disse il piccolo principe.","zh":"“他们很匆忙，”小王子说。","t":[100,3075]},{"it":"“Che cosa cercano?”","zh":"“这连火车司机自己也不知道，”扳道工回答。","t":[3075,4124]}]},{"id":"ch22p06","audio":true,"sents":[{"it":"“Neanche l’uomo della locomotiva lo sa,” disse l’ad­detto agli scambi.","zh":"这时，那列灯火通明的快车又朝相反方向轰隆驶过。","t":[100,3762]}]},{"id":"ch22p07","audio":true,"sents":[{"it":"E in senso inverso arrivò rombando un secondo rapido illuminato.","zh":"“他们已经回来了吗？”","t":[100,4025]}]},{"id":"ch22p08","audio":true,"sents":[{"it":"“Sono già di ritorno?” domandò il piccolo principe...","zh":"小王子问。","t":[100,3238]}]},{"id":"ch22p09","audio":true,"sents":[{"it":"“Non sono gli stessi,” disse l’addetto agli scambi.","zh":"“对开的火车。”","t":[100,3125]},{"it":"“Questo è uno scambio.”","zh":"“他们不喜欢自己待过的地方吗？”","t":[3125,4400]}]},{"id":"ch22p10","audio":true,"sents":[{"it":"“Non erano contenti, dove stavano?”","zh":"小王子问。","t":[100,2387]}]},{"id":"ch22p11","audio":true,"sents":[{"it":"“Nessuno è mai contento dove sta,” disse l’addetto allo scambio.","zh":"“他们对什么都永远不满意，”扳道工回答。","t":[100,3750]}]},{"id":"ch22p12","audio":true,"sents":[{"it":"E come un tuono rombò un terzo rapido illuminato.","zh":"第三列灯火通明的特快列车又轰鸣着驶过。","t":[100,3337]}]},{"id":"ch22p13","audio":true,"sents":[{"it":"“Inseguono i primi viaggiatori?” domandò il piccolo principe.","zh":"小王子问。","t":[100,3774]}]},{"id":"ch22p14","audio":true,"sents":[{"it":"“Non inseguono un bel niente,” disse l’addetto allo scambio.","zh":"“他们并没有在追赶谁，”扳道工回答。","t":[100,3762]},{"it":"“Là dentro dormono, oppure sbadigliano.","zh":"“车里的人不是在睡觉，就是在打哈欠。”","t":[3762,6475]},{"it":"Solo i bambini se ne stanno con il naso incollato al finestrino.”","zh":"只有孩子们把鼻子贴在玻璃上。","t":[6475,10200]}]},{"id":"ch22p15","audio":true,"sents":[{"it":"“Solo i bambini sanno quello che cercano,” fece il piccolo principe.","zh":"“他们把时间花在布偶娃娃上，于是娃娃对他们就变得非常重要。”","t":[100,3975]},{"it":"“Perdono tempo per una bambola di pezza, che allora diventa importantissima, e se qualcuno gliela porta via piangono...”","zh":"如果有人把娃娃拿走，他们就会哭。","t":[3975,10524]}]},{"id":"ch22p16","audio":true,"sents":[{"it":"“Sono fortunati,” disse l’addetto allo scambio.","zh":"“他们真幸福，”扳道工说。","t":[100,2725]}]}]},{"id":"ch23","title_it":"XXIII","title_zh":"第 23 章","paras":[{"id":"ch23p00","audio":true,"sents":[{"it":"“Buongiorno,” disse il piccolo principe.","zh":"“你好，”小王子说。","t":[100,2226]}]},{"id":"ch23p01","audio":true,"sents":[{"it":"“Buongiorno,” disse il negoziante.","zh":"“你好，”商贩回答。","t":[100,2063]}]},{"id":"ch23p02","audio":true,"sents":[{"it":"Vendeva pillole speciali che placano la sete.","zh":"这是个贩卖高效止渴药丸的商贩。","t":[100,2888]},{"it":"Ne prendi una alla settimana e non provi più il desiderio di bere.","zh":"吞下一粒这样的药丸，整整一周都不用喝水。","t":[2888,6725]}]},{"id":"ch23p03","audio":true,"sents":[{"it":"“Perché vendi queste pillole?” disse il piccolo principe.","zh":"“你为什么要卖这个？”","t":[100,3737]}]},{"id":"ch23p04","audio":true,"sents":[{"it":"“È un bel risparmio di tempo,” disse il negoziante.","zh":"“因为它们能大大节省时间，”商贩回答。","t":[100,3200]},{"it":"“Gli esperti hanno calcolato che si guadagnano cinquantatré minuti alla settimana.”","zh":"“专家们算过——每周能省下五十三分钟。”","t":[3200,7563]}]},{"id":"ch23p05","audio":true,"sents":[{"it":"“E cosa si fa di quei cinquantatré minuti?”","zh":"“那这省下的五十三分钟，用来做什么呢？”","t":[100,2437]}]},{"id":"ch23p06","audio":true,"sents":[{"it":"“Quello che si vuole...”","zh":"“想做什么就做什么。”","t":[100,1100]}]},{"id":"ch23p07","audio":true,"sents":[{"it":"“Se avessi cinquantatré minuti da spendere,” si disse il piccolo principe, “me ne andrei lentamente verso una fontana...”","zh":"“要是我能多出这五十三分钟，”小王子心想，“我就慢慢散步到泉水边去……”","t":[100,6576]}]}]},{"id":"ch24","title_it":"XXIV","title_zh":"第 24 章","paras":[{"id":"ch24p00","audio":true,"sents":[{"it":"Erano passati otto giorni da quando avevo avuto il guasto nel deserto, e avevo ascoltato la storia del negoziante bevendo la mia ultima goccia d’acqua:","zh":"从我飞机在沙漠失事到现在，已经过了八天。","t":[100,8326]}]},{"id":"ch24p01","audio":true,"sents":[{"it":"“Ah!” dissi al piccolo principe, “i tuoi ricordi sono proprio belli, ma non ho ancora riparato l’aereo, non ho più niente da bere, e sarei ben felice anch’io di poter camminare pian piano verso una fontana!”","zh":"听着商贩的故事，我喝光了存水里的最后一滴。","t":[100,12437]}]},{"id":"ch24p02","audio":true,"sents":[{"it":"“La mia amica volpe...” mi disse.","zh":"“你讲的故事真有意思，”我对小王子说，“可我的飞机还没修好，水也喝光了，要是我也能慢悠悠散步到泉水边去，那该多好。”","t":[100,2162]}]},{"id":"ch24p03","audio":true,"sents":[{"it":"“Caro il mio ometto, lascia stare la tua volpe!”","zh":"“我的朋友狐狸曾经对我说过……”","t":[100,2825]}]},{"id":"ch24p04","audio":true,"sents":[{"it":"“Perché?”","zh":"“我的小朋友，现在说的可不是狐狸！”","t":[100,588]}]},{"id":"ch24p05","audio":true,"sents":[{"it":"“Perché qui moriremo di sete...”","zh":"“为什么？”","t":[100,1738]}]},{"id":"ch24p06","audio":true,"sents":[{"it":"Non capì il mio ragionamento e mi rispose:","zh":"“因为我会渴死的。”","t":[100,2437]}]},{"id":"ch24p07","audio":true,"sents":[{"it":"“È bello avere avuto un amico, anche se devi morire di sete.","zh":"比方说，我很高兴曾经有过狐狸这个朋友。","t":[100,3775]},{"it":"Io sono molto contento di avere avuto la mia amica volpe...”","zh":"“他无法真正明白危险，”我想。","t":[3775,6863]}]},{"id":"ch24p08","audio":true,"sents":[{"it":"“Non si rende conto del pericolo,” pensai.","zh":"“因为他从没尝过饥饿，也没尝过干渴。”","t":[100,2700]},{"it":"“Non ha mai né fame né sete.","zh":"“对他来说，只要有阳光就够了……”","t":[2700,4462]},{"it":"Gli basta un po’ di sole...”","zh":"可是小王子望着我，似乎看穿了我的心思。","t":[4462,5924]}]},{"id":"ch24p09","audio":true,"sents":[{"it":"Ma lui mi guardò e rispose al mio pensiero:","zh":"“我也想喝水……”","t":[100,2450]}]},{"id":"ch24p10","audio":true,"sents":[{"it":"“Anch’io ho sete...","zh":"我们去找井吧。","t":[100,1450]},{"it":"cerchiamo un pozzo...”","zh":"我绝望地摆了摆手——在茫茫沙漠里瞎找水井，毫无意义。","t":[1450,2512]}]},{"id":"ch24p11","audio":true,"sents":[{"it":"Ebbi un gesto di stanchezza: è assurdo cercare a caso un pozzo nell’immensità del deserto.","zh":"尽管如此，我们还是上路了。","t":[100,5825]},{"it":"Tuttavia ci mettemmo in cammino.","zh":"我们默默地走了好几个小时。","t":[5825,7612]}]},{"id":"ch24p12","audio":true,"sents":[{"it":"Dopo che avemmo camminato per ore, in silenzio, scese la notte, e cominciarono ad accendersi le stelle.","zh":"夜幕降临，天空中开始亮起星星。","t":[100,6762]},{"it":"Le scorgevo come in sogno, poiché a causa della sete avevo un po’ di febbre.","zh":"我望着它们，如坠梦中。","t":[6762,11400]},{"it":"Nella memoria mi danzavano le parole del piccolo principe:","zh":"干渴让我有些发热。","t":[11400,14575]}]},{"id":"ch24p13","audio":true,"sents":[{"it":"“Allora anche tu hai sete?” gli domandai.","zh":"小王子的话在我脑海里翻腾。","t":[100,2612]}]},{"id":"ch24p14","audio":true,"sents":[{"it":"Ma non rispose.","zh":"“你是说，你也感到口渴了？”","t":[100,1412]},{"it":"Mi disse soltanto:","zh":"他没有正面回答，只是说：“水对心灵也是好的。”","t":[1412,2724]}]},{"id":"ch24p15","audio":true,"sents":[{"it":"“L’acqua può essere buona anche per il cuore...”","zh":"我没明白他的意思，但没再追问。","t":[100,2188]}]},{"id":"ch24p16","audio":true,"sents":[{"it":"Non capii quella risposta, ma tacqui...","zh":"我很清楚，不该去盘问他。","t":[100,2862]},{"it":"Sapevo che non bisognava fargli domande.","zh":"他看起来累了。","t":[2862,5000]}]},{"id":"ch24p17","audio":true,"sents":[{"it":"Era stanco.","zh":"小王子坐到沙地上，我也挨着他坐下。","t":[100,1200]},{"it":"Si sedette.","zh":"沉默片刻，他说：“星星真美；因为某处有一朵花，虽然从这里看不见它。”","t":[1200,2350]},{"it":"Mi sedetti accanto a lui.","zh":"“当然，”我回答，然后望着月光下沙丘的脊线，不再出声。","t":[2350,4000]},{"it":"Poi, dopo un momento di silenzio, disse ancora:","zh":"“沙漠真美，”他又说。","t":[4000,7224]}]},{"id":"ch24p18","audio":true,"sents":[{"it":"“Le stelle sono belle grazie a un fiore che non vediamo...”","zh":"这话说得对。","t":[100,3225]}]},{"id":"ch24p19","audio":true,"sents":[{"it":"Risposi “certo” e guardai, senza parlare, le pieghe della sabbia sotto la luna.","zh":"我一直喜欢沙漠。","t":[100,5212]}]},{"id":"ch24p20","audio":true,"sents":[{"it":"“Il deserto è bello...” aggiunse.","zh":"坐在沙丘上。","t":[100,2324]}]},{"id":"ch24p21","audio":true,"sents":[{"it":"Ed era vero.","zh":"一片寂静。","t":[100,1062]},{"it":"Ho sempre amato il deserto.","zh":"没有任何动静。","t":[1062,2875]},{"it":"Ti siedi su una duna di sabbia.","zh":"“沙漠之所以美，”小王子说，“还因为它在某处藏着一口井。”","t":[2875,4975]},{"it":"Non vedi niente.","zh":"我吃了一惊，忽然明白了沙地那神秘的闪烁意味着什么。","t":[4975,6238]},{"it":"Non senti niente.","zh":"我小的时候，住在一栋老房子里。","t":[6238,7650]},{"it":"E tuttavia qualcosa brilla in silenzio...","zh":"传说房子里某处埋着宝藏。","t":[7650,9912]}]},{"id":"ch24p22","audio":true,"sents":[{"it":"“Ciò che fa bello il deserto,” disse il piccolo principe, “è che da qualche parte nasconde un pozzo...”","zh":"当然，谁也没找到它。","t":[100,5500]}]},{"id":"ch24p23","audio":true,"sents":[{"it":"E con grande stupore capii d’un tratto il misterioso brillio della sabbia.","zh":"也许，根本没人去找过。","t":[100,4612]},{"it":"Da bambino abitavo in una vecchia casa che la leggenda diceva celasse un tesoro.","zh":"但它给房子平添了一种魔幻的魅力。","t":[4612,9388]},{"it":"Ovviamente nessuno è mai riuscito a trovarlo, né forse l’ha mai cercato.","zh":"房子仿佛把秘密藏在心底……","t":[9388,13938]},{"it":"Ma esso rendeva quella casa come incantata.","zh":"“没错，”我对小王子说，“无论是房子、星星，还是沙漠。’","t":[13938,16712]},{"it":"Il cuore della mia casa nascondeva un segreto...","zh":"让它们变得美丽的东西，是肉眼看不见的。”","t":[16712,19313]}]},{"id":"ch24p24","audio":true,"sents":[{"it":"“Sì,” dissi al piccolo principe, “che si tratti della casa, delle stelle o del deserto, quel che fa la loro bellezza è invisibile!”","zh":"“我很高兴，”他回答，“你赞同我的狐狸朋友。”","t":[100,8200]}]},{"id":"ch24p25","audio":true,"sents":[{"it":"“Mi fa piacere,” disse, “che tu sia d’accordo con la mia volpe.”","zh":"小王子打起了瞌睡。","t":[100,3574]}]},{"id":"ch24p26","audio":true,"sents":[{"it":"Il piccolo principe si stava addormentando, allora lo presi in braccio e mi rimisi in cammino.","zh":"我把他抱在怀里，重新上路。","t":[100,5775]},{"it":"Provavo una grande emozione.","zh":"我心里激动不已。","t":[5775,7712]},{"it":"Mi sembrava di reggere un fragile tesoro.","zh":"我觉得手里抱着一件脆弱的珍宝。","t":[7712,10150]},{"it":"Mi sembrava addirittura che non ci fosse nulla di più fragile sulla Terra.","zh":"借著月光，我望着他苍白的额头、闭着的眼睛、被风吹动的发丝，对自己说：我看到的只是外表。","t":[10150,14475]},{"it":"Alla luce della luna, guardavo quella fronte pallida, quegli occhi chiusi, quelle ciocche di capelli che tremavano al vento, e mi dicevo: “Io vedo soltanto la scorza.","zh":"因为最重要的东西，是肉眼看不见的……","t":[14475,24375]},{"it":"Ciò che è davvero importante è invisibile...”.","zh":"他半张的嘴唇泛起一丝几乎察觉不到的微笑，我想：“这位睡着的王子让我如此感动，是因为他对自己的花忠贞不渝。”","t":[24375,26600]}]},{"id":"ch24p27","audio":true,"sents":[{"it":"Mentre le sue labbra socchiuse accennavano un mezzo sorriso, mi dissi ancora: “La cosa che più mi commuove di questo piccolo principe addormentato è la sua fedeltà a un fiore, è l’immagine di una rosa che brilla dentro di lui come la fiamma di una lampada, anche quando dorme...”.","zh":"玫瑰的形象在他心中闪烁，如同烛火，即便在他睡着时也是如此。","t":[100,16138]},{"it":"E capii che era ancora più fragile.","zh":"我再次感到他是多么脆弱。","t":[16138,18450]},{"it":"Bisogna proteggere le lampade: un soffio di vento basta a spegnerle...","zh":"这样的火苗必须小心守护，因为一阵风就能把它吹灭。","t":[18450,22650]}]},{"id":"ch24p28","audio":true,"sents":[{"it":"E, camminando così, all’alba trovai il pozzo.","zh":"我走啊走，终于在黎明时看见了那口井。","t":[100,3374]}]}]},{"id":"ch25","title_it":"XXV","title_zh":"第 25 章","paras":[{"id":"ch25p00","audio":true,"sents":[{"it":"“Gli uomini,” disse il piccolo principe, “salgono sui treni ma non sanno più cosa cercano.","zh":"“人们，”小王子说，“他们钻进快车，却不知道自己要奔向何方。”","t":[100,5538]},{"it":"Allora si agitano e girano a vuoto...”","zh":"所以他们白白折腾，兜着圈子跑。","t":[5538,7776]}]},{"id":"ch25p01","audio":true,"sents":[{"it":"Quindi aggiunse:","zh":"接着他又说：“这毫无意义……”","t":[100,1138]}]},{"id":"ch25p02","audio":true,"sents":[{"it":"“E tutto questo non serve a niente...”","zh":"我们抵达的这口井，非同寻常。","t":[100,2063]}]},{"id":"ch25p03","audio":true,"sents":[{"it":"Il pozzo cui eravamo giunti era diverso dai soliti pozzi del Sahara.","zh":"因为撒哈拉的井，不过是在沙里挖出的简单坑洞。","t":[100,4188]},{"it":"I pozzi del Sahara sono semplici buche scavate nella sabbia.","zh":"而这口却像个乡村的井，尽管附近并无村落。","t":[4188,8012]},{"it":"Questo era simile al pozzo di un villaggio.","zh":"我简直以为自己在做梦。","t":[8012,10500]},{"it":"Ma non c’era alcun villaggio, e credevo di sognare.","zh":"我简直以为自己在做梦。","t":[10500,13576]}]},{"id":"ch25p04","audio":true,"sents":[{"it":"“È strano,” dissi al piccolo principe, “è tutto pronto: la carrucola, il secchio e la corda...”","zh":"“真怪，”我对小王子说，“这儿什么都是现成的：辘轳、水桶和绳子……”","t":[100,6063]}]},{"id":"ch25p05","audio":true,"sents":[{"it":"Lui rise, toccò la corda, fece ruotare la carrucola.","zh":"他笑着回答，拉了拉绳子，辘轳便转了起来。","t":[100,3513]}]},{"id":"ch25p06","audio":true,"sents":[{"it":"E la carrucola gemette come geme una vecchia banderuola dopo che il vento ha dormito a lungo.","zh":"辘轳随之发出呻吟，像那为早已沉睡的风而鸣的旧风标。","t":[100,5137]}]},{"id":"ch25p07","audio":true,"sents":[{"it":"“Lo senti?” disse il piccolo principe, “svegliamo il pozzo e lui canta...”","zh":"“你听见了吗，”小王子说，“我们把这口井唤醒了，它唱起歌来。”","t":[100,4650]}]},{"id":"ch25p08","audio":true,"sents":[{"it":"Non volevo che si stancasse:","zh":"我不想让他太费力。","t":[100,1750]}]},{"id":"ch25p09","audio":true,"sents":[{"it":"“Lascia fare a me,” gli dissi, “per te è troppo pesante.”","zh":"“让我来吧，”我对他说，“这活儿你干不动。”","t":[100,3350]}]},{"id":"ch25p10","audio":true,"sents":[{"it":"Tirai su adagio il secchio fino al bordo.","zh":"我慢慢提起水桶，重重地把它放在井沿上。","t":[100,2538]},{"it":"Lo posai bene in equilibrio.","zh":"我耳中仍回响着辘轳的歌声，而颤动的波光上，跃动着太阳的倒影。","t":[2538,4450]},{"it":"Nelle mie orecchie durava il canto della puleggia e, nell’acqua che ancora tremava, vedevo tremare il sole.","zh":"“让我喝这水吧，”小王子说，“给我喝吧。”","t":[4450,10524]}]},{"id":"ch25p11","audio":true,"sents":[{"it":"“Ho sete di quell’acqua,” disse il piccolo principe, “dammi da bere...”","zh":"于是我明白了他要找的是什么。","t":[100,3800]}]},{"id":"ch25p12","audio":true,"sents":[{"it":"E capii che cosa aveva cercato!","zh":"我把水桶举到他唇边。","t":[100,2050]}]},{"id":"ch25p13","audio":true,"sents":[{"it":"Gli sollevai il secchio fino alle labbra.","zh":"他闭着眼睛喝水。","t":[100,2488]},{"it":"Bevve, con gli occhi chiusi.","zh":"这水对他而言是一场盛宴。","t":[2488,4538]},{"it":"Era dolce come una festa.","zh":"这水对他而言是一场盛宴。","t":[4538,6250]},{"it":"Quell’acqua era ben altro che un alimento.","zh":"它全然不同，不是供日常解渴之水。","t":[6250,8588]},{"it":"Era nata dalla camminata sotto le stelle, dal canto della carrucola, dallo sforzo delle mie braccia.","zh":"这水诞生于星空之下，诞生于辘轳的歌声之中，诞生于我双手的努力。","t":[8588,14788]},{"it":"Era buona per il cuore, come un dono.","zh":"它对心灵如此甘美，宛如礼物。","t":[14788,17200]},{"it":"Quando ero piccolo, erano i lumini dell’albero di Natale, la musica della messa di mezzanotte, la dolcezza dei sorrisi a far risplendere il regalo che ricevevo.","zh":"当我还是个小男孩时，圣诞树的光芒、晚祷的教堂乐曲、四周洋溢的温柔笑容，也曾是我收到的璀璨节日礼物。","t":[17200,26425]}]},{"id":"ch25p14","audio":true,"sents":[{"it":"“Gli uomini di dove stai tu,” disse il piccolo principe, “coltivano cinquemila rose in un giardino e non trovano quello che cercano...”","zh":"“你们这里的人，”小王子说，“在一个园子里种出五千朵玫瑰，却找不到自己所求……”","t":[100,7300]}]},{"id":"ch25p15","audio":true,"sents":[{"it":"“Non lo trovano...” risposi.","zh":"“是找不到，”我确认说……","t":[100,1826]}]},{"id":"ch25p16","audio":true,"sents":[{"it":"“Eppure, quello che cercano potrebbero trovarlo in una sola rosa o in un po’ d’acqua...”","zh":"“可他们寻找的一切，都能在一朵玫瑰和几口水中找到。”","t":[100,4738]}]},{"id":"ch25p17","audio":true,"sents":[{"it":"“Certo,” risposi.","zh":"“当然，”我同意。","t":[100,1300]}]},{"id":"ch25p18","audio":true,"sents":[{"it":"E il piccolo principe aggiunse:","zh":"小王子又道：“他们的眼睛是盲的。”","t":[100,1888]}]},{"id":"ch25p19","audio":true,"sents":[{"it":"“Ma gli occhi sono ciechi.","zh":"必须用心灵去寻找。","t":[100,1812]},{"it":"Bisogna cercare con il cuore.”","zh":"我畅饮了个够。","t":[1812,3400]}]},{"id":"ch25p20","audio":true,"sents":[{"it":"Avevo bevuto.","zh":"黎明时分，呼吸格外舒畅。","t":[100,1288]},{"it":"Respiravo bene.","zh":"沙子泛着蜜糖般的色泽。","t":[1288,2575]},{"it":"Al sorgere del sole la sabbia ha il colore del miele.","zh":"沙子泛着蜜糖般的色泽。","t":[2575,6062]},{"it":"Ero felice anche di quel color miele.","zh":"那色调让我欢喜。","t":[6062,8312]},{"it":"Perché mai dovevo essere triste...","zh":"我再没有什么可担忧和悲伤的了。","t":[8312,10075]}]},{"id":"ch25p21","audio":true,"sents":[{"it":"“Devi mantenere la promessa,” mi disse dolcemente il piccolo principe, che di nuovo si era seduto accanto a me.","zh":"“你一定会信守承诺吧？”","t":[100,5913]}]},{"id":"ch25p22","audio":true,"sents":[{"it":"“Quale promessa?”","zh":"小王子挨着我坐下，问道。","t":[100,1037]}]},{"id":"ch25p23","audio":true,"sents":[{"it":"“Sai...","zh":"“什么承诺？”","t":[100,838]},{"it":"la museruola per la pecora...","zh":"“你知道的……给我小羊的嘴套。”","t":[838,2662]},{"it":"io sono responsabile di quella rosa!”","zh":"我对我的花是负有责任的。","t":[2662,4737]}]},{"id":"ch25p24","audio":true,"sents":[{"it":"Tirai fuori di tasca i miei disegni.","zh":"我从口袋里掏出草图。","t":[100,2650]},{"it":"Il piccolo principe li vide e disse ridendo:","zh":"小王子看了看，笑了起来。","t":[2650,5176]}]},{"id":"ch25p25","audio":true,"sents":[{"it":"“I tuoi baobab sembrano un po’ dei cavoli...”","zh":"“你的猴面包树，画得像棵花椰菜……”","t":[100,2612]}]},{"id":"ch25p26","audio":true,"sents":[{"it":"“Oh!”","zh":"“竟是这样？”","t":[100,562]}]},{"id":"ch25p27","audio":true,"sents":[{"it":"Io che ero così fiero dei baobab!","zh":"而我原本对自己的猴面包树是那么得意……","t":[100,2213]}]},{"id":"ch25p28","audio":true,"sents":[{"it":"“La tua volpe...","zh":"而我原本对自己的猴面包树是那么得意……","t":[100,1225]},{"it":"ha certe orecchie...","zh":"“你的狐狸……它的耳朵……有点像鹿角——太长了。”","t":[1225,2562]},{"it":"che sembrano un po’ delle corna...","zh":"他又笑了起来。","t":[2562,4362]},{"it":"e sono troppo lunghe!”","zh":"“你对我不公平，我的小朋友。”","t":[4362,5575]}]},{"id":"ch25p29","audio":true,"sents":[{"it":"E rise ancora:","zh":"除了蟒蛇——从外面和里面——我本来什么都不会画。","t":[100,1138]}]},{"id":"ch25p30","audio":true,"sents":[{"it":"“Sei ingiusto, ometto, io sapevo disegnare soltanto i boa chiusi e i boa aperti.”","zh":"“啊……”","t":[100,5524]}]},{"id":"ch25p31","audio":true,"sents":[{"it":"“Ma va benissimo, dai,” disse, “i bambini capiscono.”","zh":"“那也凑合。”","t":[100,3788]}]},{"id":"ch25p32","audio":true,"sents":[{"it":"Disegnai quindi una museruola.","zh":"“孩子们会懂的，”小王子回答。","t":[100,2362]},{"it":"E nel dargliela mi si stringeva il cuore:","zh":"我拿起铅笔，画了个嘴套。","t":[2362,4438]}]},{"id":"ch25p33","audio":true,"sents":[{"it":"“Hai progetti che io ignoro...”","zh":"可当我将画递给他时，我的心猛地一颤：“你打算做什么？”","t":[100,1724]}]},{"id":"ch25p34","audio":true,"sents":[{"it":"Ma non mi rispose.","zh":"你没跟我说过……”","t":[100,1450]},{"it":"Mi disse:","zh":"小王子对此没有作答。","t":[1450,2200]}]},{"id":"ch25p35","audio":true,"sents":[{"it":"“Sai...","zh":"他只说：“你知道的……到明天，我降临地球正好满一年……”","t":[100,850]},{"it":"domani è l’anniversario della mia caduta sulla Terra...”","zh":"他沉默了，接着又说：“这事就发生在离这儿不远的地方。”","t":[850,3750]}]},{"id":"ch25p36","audio":true,"sents":[{"it":"Poi, dopo un momento di silenzio:","zh":"他沉默了，接着又说：“这事就发生在离这儿不远的地方。”","t":[100,2224]}]},{"id":"ch25p37","audio":true,"sents":[{"it":"“Ero caduto proprio qui vicino...”","zh":"说着，他脸红了。","t":[100,1776]}]},{"id":"ch25p38","audio":true,"sents":[{"it":"E arrossì.","zh":"我的心揪了一下，虽然我不明白为什么。","t":[100,863]}]},{"id":"ch25p39","audio":true,"sents":[{"it":"E di nuovo, senza capirne il motivo, provai una strana pena.","zh":"我脑中浮起一个问题：“这么说，八天前的那个早晨，我第一次见到你时，你出现在这里并非偶然？”","t":[100,4275]},{"it":"Mi sorse però una domanda:","zh":"孤零零一个人，离人烟有千里之遥！”","t":[4275,5862]}]},{"id":"ch25p40","audio":true,"sents":[{"it":"“Allora non è un caso se la mattina in cui ti ho conosciuto, otto giorni fa, te ne andavi in giro da solo, lontano mille miglia da qualunque terra abitata!","zh":"你是回自己坠落的地方去？”","t":[100,9238]},{"it":"Tornavi verso il punto dov’eri caduto?”","zh":"小王子又脸红了。","t":[9238,11324]}]},{"id":"ch25p41","audio":true,"sents":[{"it":"Di nuovo il piccolo principe arrossì.","zh":"我迟疑地又补了一句：“跟这周年纪念有关？”","t":[100,2263]}]},{"id":"ch25p42","audio":true,"sents":[{"it":"E io aggiunsi, titubante:","zh":"小王子再次脸红。","t":[100,1937]}]},{"id":"ch25p43","audio":true,"sents":[{"it":"“Era forse a causa dell’anniversario?”","zh":"他从不直接回答问题，可脸红，不就意味著“是”吗？","t":[100,2075]}]},{"id":"ch25p44","audio":true,"sents":[{"it":"Di nuovo il piccolo principe arrossì.","zh":"“是这样？”","t":[100,2525]},{"it":"Non rispondeva mai alle domande, ma quando si arrossisce significa “sì”, vero?","zh":"我对他说。","t":[2525,7500]}]},{"id":"ch25p45","audio":true,"sents":[{"it":"“Ah!” gli dissi, “ho paura...”","zh":"“我怕……”","t":[100,2438]}]},{"id":"ch25p46","audio":true,"sents":[{"it":"Ma mi rispose:","zh":"但他打断我：“你该去干活了。”","t":[100,1137]}]},{"id":"ch25p47","audio":true,"sents":[{"it":"“Adesso devi lavorare.","zh":"但他打断我：“你该去干活了。”","t":[100,1662]},{"it":"Devi tornare al tuo aereo.","zh":"回到你的飞机那儿去。","t":[1662,3638]},{"it":"Io ti aspetto qui.","zh":"我在这儿等你。","t":[3638,4975]},{"it":"Torna domani sera...”","zh":"明天傍晚回来……”","t":[4975,6075]}]},{"id":"ch25p48","audio":true,"sents":[{"it":"Ma non ero tranquillo.","zh":"听了这话，我反而更不安了。","t":[100,1725]},{"it":"Pensavo alla volpe.","zh":"我想起了狐狸。","t":[1725,3088]},{"it":"Si corre il rischio di piangere un po’, quando ci si è lasciati addomesticare...","zh":"一旦让自己被驯养，就有落泪的风险……","t":[3088,7662]}]}]},{"id":"ch26","title_it":"XXVI","title_zh":"第 26 章","paras":[{"id":"ch26p00","audio":true,"sents":[{"it":"C’erano, accanto al pozzo, i resti di un vecchio muro di pietra.","zh":"井旁有一道旧石墙的残垣。","t":[100,4525]},{"it":"Quando l’indomani sera tornai, dopo aver lavorato, scorsi da lontano il mio piccolo principe seduto là sopra, con le gambe penzoloni.","zh":"第二天傍晚，我干完活回来，老远就看见小王子坐在墙上，双腿垂着。","t":[4525,13112]},{"it":"E lo sentii che parlava:","zh":"我听见他对谁说：“难道你把这事忘了吗？”","t":[13112,14450]}]},{"id":"ch26p01","audio":true,"sents":[{"it":"“Ma non te lo ricordi?” diceva.","zh":"我听见他对谁说：“难道你把这事忘了吗？”","t":[100,2400]},{"it":"“Non è mica qui!”","zh":"那不在这里……”","t":[2400,3463]}]},{"id":"ch26p02","audio":true,"sents":[{"it":"Probabilmente un’altra voce gli rispose, poiché lui ribatté:","zh":"毫无疑问，有人答了他，因为他反驳道：“不，才不是！”","t":[100,3675]}]},{"id":"ch26p03","audio":true,"sents":[{"it":"“Ma sì, invece!","zh":"是整整一年前，但不是在这儿。”","t":[100,1838]},{"it":"Il giorno è giusto, ma il posto non è questo...”","zh":"我走近墙边，却依旧谁也没看见，也没听见。","t":[1838,4875]}]},{"id":"ch26p04","audio":true,"sents":[{"it":"Continuai ad avvicinarmi al muro.","zh":"可小王子又答道：“哦，当然。","t":[100,2250]},{"it":"Non sentivo né vedevo ancora nessuno.","zh":"可小王子又答道：“哦，当然。","t":[2250,4650]},{"it":"Tuttavia il piccolo principe di nuovo ribatté:","zh":"你会在沙上看见我的脚印。","t":[4650,7175]}]},{"id":"ch26p05","audio":true,"sents":[{"it":"“...Certo.","zh":"你只需等我就好。","t":[100,1025]},{"it":"Guarda dove iniziano le mie impronte sulla sabbia.","zh":"今夜我会来的……”","t":[1025,4012]},{"it":"Non devi fare altro che aspettarmi lì.","zh":"当时我离墙只有二十米，却依旧什么人也看不见。","t":[4012,6312]},{"it":"Ci sarò.","zh":"小王子沉默片刻，问道：“你的毒，厉害吗？”","t":[6312,7138]},{"it":"Stanotte.”","zh":"小王子沉默片刻，问道：“你的毒，厉害吗？”","t":[7138,7900]}]},{"id":"ch26p06","audio":true,"sents":[{"it":"Ero a venti metri dal muro e continuavo a non vedere niente.","zh":"你能保证我不会受太久的苦吗？”","t":[100,3463]}]},{"id":"ch26p07","audio":true,"sents":[{"it":"Dopo una pausa, il piccolo principe disse ancora:","zh":"我停住脚步，心猛地一紧，却仍没完全明白。","t":[100,3387]}]},{"id":"ch26p08","audio":true,"sents":[{"it":"“È un buon veleno, il tuo?","zh":"“现在你走开吧，”小王子说，“我想下去了。”","t":[100,2125]},{"it":"Sei sicuro di non farmi soffrire a lungo?”","zh":"我垂眼望向墙根，随即惊得退开一步。","t":[2125,4263]}]},{"id":"ch26p09","audio":true,"sents":[{"it":"Mi fermai, con il cuore in gola, ma continuavo a non capire.","zh":"我垂眼望向墙根，随即惊得退开一步。","t":[100,4026]}]},{"id":"ch26p10","audio":true,"sents":[{"it":"“Adesso vattene...” disse.","zh":"墙根下，一条黄色的蛇正朝小王子游来。","t":[100,2675]},{"it":"“Voglio scendere!”","zh":"这种蛇半分钟就能要人命。","t":[2675,3700]}]},{"id":"ch26p11","audio":true,"sents":[{"it":"Allora abbassai gli occhi ai piedi del muro e sobbalzai!","zh":"我摸索着口袋里的左轮手枪，我向前探身，但听到声响，蛇便顺着沙地轻轻滑走，发出轻微的金属声，像一缕即将干涸的水流般消失在石块间。","t":[100,3625]},{"it":"Era lì, ritto verso il piccolo principe, uno di quei serpenti gialli che ammazzano in trenta secondi.","zh":"我刚好跑到墙边，及时把我的小王子接进怀里。","t":[3625,10000]},{"it":"Mi ficcai una mano in tasca per tirar fuori la pistola e presi a correre, ma, al rumore che feci, il serpente scivolò piano nella sabbia, come un rigagnolo d’acqua che muore e, senza affrettarsi troppo, si infilò tra le pietre con un lieve rumore metallico.","zh":"他苍白如雪。","t":[10000,25900]}]},{"id":"ch26p12","audio":true,"sents":[{"it":"Giunsi al muro appena in tempo per ricevere fra le braccia il mio ometto, il mio principe, pallido come la neve.","zh":"他苍白如雪。","t":[100,6400]}]},{"id":"ch26p13","audio":true,"sents":[{"it":"“Che storia è questa!","zh":"“你到底在打什么主意？！”","t":[100,1600]},{"it":"Adesso parli con i serpenti!”","zh":"你为什么要跟蛇说话？”","t":[1600,3437]}]},{"id":"ch26p14","audio":true,"sents":[{"it":"Avevo slacciato la sua eterna sciarpa color oro.","zh":"我解开他那条从不离身的金色围巾。","t":[100,2912]},{"it":"Gli avevo bagnato le tempie e lo avevo fatto bere.","zh":"我润湿他的太阳穴，又喂他喝水。","t":[2912,5900]},{"it":"E adesso non osavo più domandargli nulla.","zh":"我润湿他的太阳穴，又喂他喝水。","t":[5900,8425]},{"it":"Mi guardò con aria seria e mi mise le braccia intorno al collo.","zh":"我不敢问他什么。","t":[8425,12212]},{"it":"Gli sentivo battere il cuore come quello di un uccello morente dopo che gli hai sparato con la carabina.","zh":"他认真地望着我，用双臂搂住我的脖子。","t":[12212,17738]},{"it":"Mi disse:","zh":"我感觉到他的心在跳动，","t":[17738,18487]}]},{"id":"ch26p15","audio":true,"sents":[{"it":"“Sono contento che tu abbia trovato quel che mancava al tuo aereo.","zh":"像一只被枪击中的垂死鸟儿的心。","t":[100,3862]},{"it":"Adesso potrai tornare a casa...”","zh":"他对我说：“我很高兴，你把飞机修好了。”","t":[3862,5712]}]},{"id":"ch26p16","audio":true,"sents":[{"it":"“Come fai a saperlo!”","zh":"他对我说：“我很高兴，你把飞机修好了。”","t":[100,1326]}]},{"id":"ch26p17","audio":true,"sents":[{"it":"Venivo proprio ad annunciargli che contro ogni speranza ero riuscito a finire il lavoro!","zh":"现在你能回家了。”","t":[100,4750]}]},{"id":"ch26p18","audio":true,"sents":[{"it":"Non rispose alla mia domanda, ma aggiunse:","zh":"“你怎么知道？”","t":[100,2687]}]},{"id":"ch26p19","audio":true,"sents":[{"it":"“Anch’io oggi torno a casa...”","zh":"我正想告诉他，我终究还是成功完成了工作。","t":[100,1688]}]},{"id":"ch26p20","audio":true,"sents":[{"it":"Poi, malinconico:","zh":"他没回答我的问题，只说：“今天我也要回自己的家了……”","t":[100,1750]}]},{"id":"ch26p21","audio":true,"sents":[{"it":"“È molto più lontano...","zh":"接着又悲伤地补了一句：“但那要远得多，也难得多……”","t":[100,1512]},{"it":"è molto più complicato...”","zh":"接着又悲伤地补了一句：“但那要远得多，也难得多……”","t":[1512,2862]}]},{"id":"ch26p22","audio":true,"sents":[{"it":"Sentivo che stava succedendo qualcosa di straordinario.","zh":"我感到有什么不寻常的事正在发生。","t":[100,3562]},{"it":"Lo strinsi fra le braccia, come fosse un bambino piccolo, e tuttavia mi sembrava che precipitasse in un abisso senza che potessi far nulla per trattenerlo...","zh":"我像抱小孩一样把他搂在怀里，却觉得他正滑向某个深渊，而我无力留住他。","t":[3562,12338]}]},{"id":"ch26p23","audio":true,"sents":[{"it":"Aveva lo sguardo serio, perso lontano:","zh":"他的目光严肃，却又透着几分怅惘。","t":[100,2700]}]},{"id":"ch26p24","audio":true,"sents":[{"it":"“Ho la tua pecora.","zh":"我有着你的小羊。","t":[100,1350]},{"it":"E ho la cassa per la pecora.","zh":"我有着你的小羊。","t":[1350,3075]},{"it":"E ho la museruola...”","zh":"也有着给它的箱子。","t":[3075,4188]}]},{"id":"ch26p25","audio":true,"sents":[{"it":"E sorrise con malinconia.","zh":"还有嘴套……”","t":[100,1712]}]},{"id":"ch26p26","audio":true,"sents":[{"it":"Aspettai a lungo.","zh":"说到这里，他凄然一笑。","t":[100,1388]},{"it":"Sentivo che pian piano si rianimava.","zh":"我等了很久，感到他渐渐缓了过来。","t":[1388,3387]}]},{"id":"ch26p27","audio":true,"sents":[{"it":"“Ometto, hai avuto paura...”","zh":"“小王子，你害怕……”","t":[100,2063]}]},{"id":"ch26p28","audio":true,"sents":[{"it":"Certo che aveva avuto paura!","zh":"“小王子，你害怕……”","t":[100,1938]},{"it":"Ma rise dolcemente:","zh":"他当然害怕。","t":[1938,3275]}]},{"id":"ch26p29","audio":true,"sents":[{"it":"“Avrò molta più paura stasera...”","zh":"“今天夜里，我会怕得更厉害……”","t":[100,1775]}]},{"id":"ch26p30","audio":true,"sents":[{"it":"Di nuovo fui raggelato da una sensazione d’ineluttabilità.","zh":"想到那逼近的、无可挽回的灾祸，我再次感到一阵寒意。","t":[100,3850]},{"it":"E capii che non sopportavo l’idea di non udire più quella risata.","zh":"我明白了——想到再也听不见他的笑声，我无法忍受。","t":[3850,7675]},{"it":"Per me era come una sorgente nel deserto.","zh":"因为对我来说，他犹如沙漠中的清泉。","t":[7675,10050]}]},{"id":"ch26p31","audio":true,"sents":[{"it":"“Ometto, voglio ancora sentirti ridere...”","zh":"因为对我来说，他犹如沙漠中的清泉。","t":[100,2575]}]},{"id":"ch26p32","audio":true,"sents":[{"it":"Ma lui mi disse:","zh":"“小王子，我想一直听见你的笑声……”","t":[100,1175]}]},{"id":"ch26p33","audio":true,"sents":[{"it":"“Stanotte sarà trascorso un anno.","zh":"他回答我：“今夜，我的星星会正好在我一年前坠落之地的正上方……”","t":[100,2312]},{"it":"La mia stella si troverà proprio sopra il punto in cui sono caduto l’anno scorso...”","zh":"“小王子，求你告诉我，这整桩蛇的事、与星星相会的事，不过是一场噩梦吧？”","t":[2312,6975]}]},{"id":"ch26p34","audio":true,"sents":[{"it":"“Ometto, è vero che questa storia del serpente e dell’appuntamento e della stella è soltanto un brutto sogno...”","zh":"他没回答我的问题，只说：“重要的东西，是肉眼看不见的……”","t":[100,6313]}]},{"id":"ch26p35","audio":true,"sents":[{"it":"Ma non rispose alla mia domanda.","zh":"他没回答我的问题，只说：“重要的东西，是肉眼看不见的……”","t":[100,2062]},{"it":"Mi disse:","zh":"“哦，当然……”","t":[2062,2813]}]},{"id":"ch26p36","audio":true,"sents":[{"it":"“Ciò che è importante non si vede...”","zh":"“这就和那朵花一样。","t":[100,1787]}]},{"id":"ch26p37","audio":true,"sents":[{"it":"“Certo...”","zh":"如果你爱一朵生长远星上的花，夜里望天便是件美事。","t":[100,775]}]},{"id":"ch26p38","audio":true,"sents":[{"it":"“È come per la rosa.","zh":"所有的星星都会绽放……”","t":[100,1538]},{"it":"Se ami una rosa che si trova su una stella, di notte è bello guardare il cielo.","zh":"“哦，当然……”","t":[1538,6262]},{"it":"Tutte le stelle sono fiorite.”","zh":"“哦，当然……”","t":[6262,7887]}]},{"id":"ch26p39","audio":true,"sents":[{"it":"“Certo...”","zh":"“这也和水一样。","t":[100,775]}]},{"id":"ch26p40","audio":true,"sents":[{"it":"“È come per l’acqua.","zh":"你给我的那水，宛如音乐……","t":[100,1450]},{"it":"Quella che mi hai dato da bere era come una musica, per via della carrucola e della corda...","zh":"辘轳和绳子……”","t":[1450,6400]},{"it":"ti ricordi...","zh":"你还记得吗？……”","t":[6400,7350]},{"it":"com’era buona.”","zh":"你还记得吗？……”","t":[7350,8188]}]},{"id":"ch26p41","audio":true,"sents":[{"it":"“Certo...”","zh":"那水真美。","t":[100,775]}]},{"id":"ch26p42","audio":true,"sents":[{"it":"“Di notte, ricordati di guardare le stelle.","zh":"“当然……”","t":[100,2962]},{"it":"Dove sto io è troppo piccolo perché possa mostrarti dove si trova la mia.","zh":"“夜里，你会望着星星。","t":[2962,7412]},{"it":"Meglio così.","zh":"我的家太小，没法指给你看我的星星在哪儿。","t":[7412,8525]},{"it":"La mia stella sarà per te una stella qualsiasi, e allora ti farà piacere guardarle tutte...","zh":"但这样反而更好。","t":[8525,13862]},{"it":"Saranno tutte tue amiche.","zh":"但这样反而更好。","t":[13862,15550]},{"it":"E poi ti farò un regalo...”","zh":"我的那颗，对你而言只是其中一颗，而你会欣赏所有的星星。","t":[15550,16963]}]},{"id":"ch26p43","audio":true,"sents":[{"it":"Rise ancora.","zh":"它们全都会成为你的朋友。","t":[100,1037]}]},{"id":"ch26p44","audio":true,"sents":[{"it":"“Ah!, ometto, ometto, come mi piace udire questa risata!”","zh":"而且，我会送你一件礼物……”","t":[100,4038]}]},{"id":"ch26p45","audio":true,"sents":[{"it":"“E infatti sarà il mio regalo...","zh":"小王子又笑了起来。","t":[100,2188]},{"it":"sarà come per l’acqua...”","zh":"“啊，小王子，小王子！”","t":[2188,3450]}]},{"id":"ch26p46","audio":true,"sents":[{"it":"“Che cosa vuoi dire?”","zh":"“啊，小王子，小王子！”","t":[100,1188]}]},{"id":"ch26p47","audio":true,"sents":[{"it":"“Le stelle sono diverse da persona a persona.","zh":"我喜欢听你的笑声。”","t":[100,2862]},{"it":"Per chi viaggia le stelle sono una guida.","zh":"“这就是我的礼物……和水一样……”","t":[2862,5200]},{"it":"Per altri sono soltanto lucine.","zh":"“你这话是什么意思？”","t":[5200,7362]},{"it":"Per altri ancora, come gli scienziati, sono problemi.","zh":"“每个人都有属于自己的星星。","t":[7362,11088]},{"it":"Per il mio uomo d’affari erano oro.","zh":"“每个人都有属于自己的星星。","t":[11088,13175]},{"it":"Ma tutte queste stelle tacciono.","zh":"对旅人来说，它们是引路的明灯。","t":[13175,15112]},{"it":"Tu invece avrai stelle che saranno qualcosa di completamente diverso...”","zh":"对旁人来说，它们只是小小的光点。","t":[15112,18800]}]},{"id":"ch26p48","audio":true,"sents":[{"it":"“Cosa vuoi dire?”","zh":"对学者来说，它们是谜题。","t":[100,1000]}]},{"id":"ch26p49","audio":true,"sents":[{"it":"“Quando la notte guarderai il cielo, poiché io abiterò in una di esse, e riderò in una di esse, per te sarà come se ridessero tutte le stelle.","zh":"对我的那位商人来说，它们是金子做的。","t":[100,8388]},{"it":"Avrai stelle che sapranno ridere!”","zh":"但所有的星星都沉默不语。","t":[8388,10113]}]},{"id":"ch26p50","audio":true,"sents":[{"it":"E rise ancora.","zh":"但所有的星星都沉默不语。","t":[100,1113]}]},{"id":"ch26p51","audio":true,"sents":[{"it":"“E quando ti sarai consolato (poiché ci si consola sempre), sarai contento di avermi conosciuto.","zh":"而你，会拥有别人都不曾拥有的星星。","t":[100,5962]},{"it":"Sarai sempre mio amico.","zh":"“你这话是什么意思？”","t":[5962,7562]},{"it":"Avrai voglia di ridere con me.","zh":"“夜里你会望天，而我将住在其中一颗星上，在其中一颗上欢笑，于是你会觉得，所有的星星都在为你而笑。”","t":[7562,9300]},{"it":"E ogni tanto aprirai la finestra, così, per puro piacere...","zh":"你会拥有会笑的星星！”","t":[9300,13450]},{"it":"E i tuoi amici saranno stupiti di vederti ridere guardando il cielo.","zh":"他又放声大笑起来。","t":[13450,17288]},{"it":"Allora tu gli dirai: ‘Sì, le stelle mi fanno sempre ridere!’.","zh":"他又放声大笑起来。","t":[17288,21625]},{"it":"E penseranno che sei pazzo.","zh":"“等你安慰好自己——人总会安慰好自己的——你会庆幸认识了我。","t":[21625,23488]},{"it":"Ti avrò fatto un bello scherzetto...”","zh":"你将永远是我的朋友。","t":[23488,25237]}]},{"id":"ch26p52","audio":true,"sents":[{"it":"E rise ancora.","zh":"你会和我一起欢笑。","t":[100,1113]}]},{"id":"ch26p53","audio":true,"sents":[{"it":"“Sarà come se, invece delle stelle, ti avessi dato tanti sonagli che sanno ridere...”","zh":"你的朋友们会奇怪，你为什么望着天空笑。","t":[100,4887]}]},{"id":"ch26p54","audio":true,"sents":[{"it":"E rise ancora.","zh":"你的朋友们会奇怪，你为什么望着天空笑。","t":[100,1375]},{"it":"Poi tornò serio:","zh":"而你会回答他们，星星总是让你发笑。”","t":[1375,2576]}]},{"id":"ch26p55","audio":true,"sents":[{"it":"“Stanotte...","zh":"他们会以为你有点失常。","t":[100,1125]},{"it":"sai...","zh":"是的，我会跟你开个有趣的玩笑……”","t":[1125,1788]},{"it":"non venire.”","zh":"小王子又笑了。","t":[1788,2537]}]},{"id":"ch26p56","audio":true,"sents":[{"it":"“Non ti lascerò.”","zh":"“这就好像，我没给你星星，而是给了你一大堆会笑的铃铛。”","t":[100,975]}]},{"id":"ch26p57","audio":true,"sents":[{"it":"“Sembrerà che stia male...","zh":"“这就好像，我没给你星星，而是给了你一大堆会笑的铃铛。”","t":[100,1662]},{"it":"che muoia.","zh":"他哈哈大笑，随后又严肃起来。","t":[1662,2588]},{"it":"È così.","zh":"“今夜……你知道……你最好别来。","t":[2588,3488]},{"it":"Non venire a vedere.","zh":"“我不会丢下你。”","t":[3488,4862]},{"it":"Non è il caso...”","zh":"“你会觉得我很难受。","t":[4862,5925]}]},{"id":"ch26p58","audio":true,"sents":[{"it":"“Non ti lascerò.”","zh":"“你会觉得我很难受。","t":[100,975]}]},{"id":"ch26p59","audio":true,"sents":[{"it":"Ma era pensieroso.","zh":"我会像在死去一样。","t":[100,1338]}]},{"id":"ch26p60","audio":true,"sents":[{"it":"“Te lo dico...","zh":"事情总是这样……你不必看见，也不该看见……”","t":[100,1150]},{"it":"per via del serpente.","zh":"“我不会丢下你。”","t":[1150,2675]},{"it":"Non deve morderti...","zh":"小王子显得真的担心起来。","t":[2675,4100]},{"it":"I serpenti sono cattivi.","zh":"“我跟你这么说……是因为蛇……","t":[4100,5950]},{"it":"Possono mordere per il semplice gusto di farlo...”","zh":"“我跟你这么说……是因为蛇……","t":[5950,8513]}]},{"id":"ch26p61","audio":true,"sents":[{"it":"“Non ti lascerò.”","zh":"怕它咬了你。","t":[100,975]}]},{"id":"ch26p62","audio":true,"sents":[{"it":"Ma qualcosa lo tranquillizzò:","zh":"蛇……它们是恶的。","t":[100,1763]}]},{"id":"ch26p63","audio":true,"sents":[{"it":"“È vero che non hanno veleno per un secondo morso...”","zh":"它们甚至会无缘无故地咬人……”","t":[100,2612]}]},{"id":"ch26p64","audio":true,"sents":[{"it":"Quella notte non lo vidi mettersi in cammino.","zh":"“我不会丢下你！”","t":[100,2700]},{"it":"Se n’era andato senza far rumore.","zh":"不过，有什么让他安心了。","t":[2700,4900]},{"it":"Quando riuscii a raggiungerlo, camminava deciso, di buon passo.","zh":"不过，有什么让他安心了。","t":[4900,9200]},{"it":"Mi disse soltanto:","zh":"“嗯，也对！","t":[9200,10512]}]},{"id":"ch26p65","audio":true,"sents":[{"it":"“Ah!","zh":"它的毒，不够咬第二口……","t":[100,750]},{"it":"Sei qui...”","zh":"这一夜，我没看见他是怎么离开的。","t":[750,1463]}]},{"id":"ch26p66","audio":true,"sents":[{"it":"E mi prese per mano.","zh":"他就这样悄然消失了。","t":[100,1488]},{"it":"Ma si tormentava ancora:","zh":"他就这样悄然消失了。","t":[1488,2987]}]},{"id":"ch26p67","audio":true,"sents":[{"it":"“Hai fatto male.","zh":"等我追上他时，他正快速而坚定地向前走。","t":[100,1262]},{"it":"Sarai triste.","zh":"看见我，他只说：“啊……你在这儿……”","t":[1262,2462]},{"it":"Sembrerà che sia morto e non sarà vero...”","zh":"他依旧满心忧虑，握住我的手。","t":[2462,4612]}]},{"id":"ch26p68","audio":true,"sents":[{"it":"Io tacevo.","zh":"“你不该来……看着这情景，你会难受的。","t":[100,962]}]},{"id":"ch26p69","audio":true,"sents":[{"it":"“Capisci, è troppo lontano.","zh":"我会像死了一样，但其实并非如此……”","t":[100,2212]},{"it":"Non posso portarmi dietro questo corpo.","zh":"我会像死了一样，但其实并非如此……”","t":[2212,4738]},{"it":"È troppo pesante.”","zh":"我沉默着。","t":[4738,5837]}]},{"id":"ch26p70","audio":true,"sents":[{"it":"Io tacevo.","zh":"“你明白吗——我的家，对这副躯壳来说太远了。","t":[100,962]}]},{"id":"ch26p71","audio":true,"sents":[{"it":"“Ma sarà come una vecchia scorza abbandonata.","zh":"它太重，我带不走它……","t":[100,2812]},{"it":"Non sono tristi, le vecchie scorze...”","zh":"我沉默着。","t":[2812,5074]}]},{"id":"ch26p72","audio":true,"sents":[{"it":"Io tacevo.","zh":"“这就像抛弃一件旧外壳。","t":[100,962]}]},{"id":"ch26p73","audio":true,"sents":[{"it":"Era un po’ scoraggiato.","zh":"“这就像抛弃一件旧外壳。","t":[100,1625]},{"it":"Ma fece ancora uno sforzo:","zh":"丢弃旧外壳，并不悲伤……","t":[1625,3288]}]},{"id":"ch26p74","audio":true,"sents":[{"it":"“Sarà carino, sai.","zh":"我沉默着。","t":[100,2112]},{"it":"Anch’io guarderò le stelle.","zh":"他有些泄气，却仍再做一次努力。","t":[2112,3975]},{"it":"Tutte le stelle saranno pozzi con una carrucola arrugginita.","zh":"“你知道，这会很妙！","t":[3975,7612]},{"it":"Tutte le stelle mi verseranno da bere...”","zh":"“你知道，这会很妙！","t":[7612,9587]}]},{"id":"ch26p75","audio":true,"sents":[{"it":"Io tacevo.","zh":"我也会望着星星。","t":[100,962]}]},{"id":"ch26p76","audio":true,"sents":[{"it":"“Sarà divertentissimo!","zh":"它们全都会像生了锈辘轳的井。","t":[100,1750]},{"it":"Tu avrai cinquecento milioni di sonagli, io avrò cinquecento milioni di sorgenti...”","zh":"所有的星星都会让我喝个够。","t":[1750,6638]}]},{"id":"ch26p77","audio":true,"sents":[{"it":"E anche lui tacque, perché piangeva...","zh":"我沉默着。","t":[100,2425]}]},{"id":"ch26p78","audio":true,"sents":[{"it":"“Ecco, siamo arrivati.","zh":"“这该多有趣！","t":[100,2050]},{"it":"Lasciami fare un passo da solo.”","zh":"“这该多有趣！","t":[2050,3738]}]},{"id":"ch26p79","audio":true,"sents":[{"it":"E si sedette perché aveva paura.","zh":"你会有五亿只铃铛，而我会有五亿眼清泉。”","t":[100,1963]}]},{"id":"ch26p80","audio":true,"sents":[{"it":"Disse ancora:","zh":"他也沉默了，因为他哭了起来。","t":[100,1124]}]},{"id":"ch26p81","audio":true,"sents":[{"it":"“Sai...","zh":"“就在这儿。","t":[100,750]},{"it":"io sono responsabile della mia rosa!","zh":"让我独自走完最后一步吧。”","t":[750,3038]},{"it":"E lei è così delicata!","zh":"让我独自走完最后一步吧。”","t":[3038,4788]},{"it":"È così ingenua.","zh":"他在沙地上坐下。","t":[4788,6162]},{"it":"Per proteggersi dal mondo ha solo quattro spine da niente...”","zh":"他害怕了。","t":[6162,9537]}]},{"id":"ch26p82","audio":true,"sents":[{"it":"Mi sedetti perché non riuscivo più a stare in piedi.","zh":"接着他说：“你知道……我的花……我的美人儿……","t":[100,3338]},{"it":"Disse:","zh":"她是那么柔弱，那么天真！","t":[3338,4026]}]},{"id":"ch26p83","audio":true,"sents":[{"it":"“Ecco...","zh":"她只有四根刺，用来抵御整个世界……","t":[100,950]},{"it":"È tutto...”","zh":"她只有四根刺，用来抵御整个世界……","t":[950,1588]}]},{"id":"ch26p84","audio":true,"sents":[{"it":"Esitò ancora un istante, poi si rialzò.","zh":"我在沙地上坐下。","t":[100,3238]},{"it":"Fece un passo.","zh":"我的双腿支撑不住身子。","t":[3238,4438]},{"it":"Io non potevo muovermi.","zh":"“嗯，就这么结束了……”","t":[4438,5813]}]},{"id":"ch26p85","audio":true,"sents":[{"it":"Ci fu solo un lampo giallo vicino alla sua caviglia.","zh":"他略一迟疑，然后起身，向前迈了一步。","t":[100,3138]},{"it":"Rimase un secondo immobile.","zh":"我无力动弹。","t":[3138,5088]},{"it":"Non gridò.","zh":"我无力动弹。","t":[5088,6062]},{"it":"Cadde piano come cade un albero.","zh":"我看见一道小小的黄色闪电，在他脚边一闪而过。","t":[6062,8188]},{"it":"Non fece neppure rumore, a causa della sabbia.","zh":"他静止地站了一瞬，随后像被砍倒的树一般，无声而缓慢地倒在沙地上，沙掩住了他落地的声响。","t":[8188,11024]}]}]},{"id":"ch27","title_it":"XXVII","title_zh":"第 27 章","paras":[{"id":"ch27p00","audio":true,"sents":[{"it":"E adesso, certo, sono già passati sei anni...","zh":"从那以后，已经过去了六年。","t":[100,3675]},{"it":"Non avevo mai raccontato questa storia.","zh":"我至今没对任何人讲过这个故事。","t":[3675,6062]},{"it":"Gli amici che ho ritrovato sono stati felici di rivedermi vivo.","zh":"我的熟人们再见我时，都高兴我还好好活着。","t":[6062,9600]},{"it":"Ero triste, ma dicevo: “È la stanchezza...”.","zh":"而我满心忧伤，却只对他们说，我只是累了。","t":[9600,12600]}]},{"id":"ch27p01","audio":true,"sents":[{"it":"Adesso mi sono un po’ consolato.","zh":"如今我已平静下来。","t":[100,2238]},{"it":"Insomma...","zh":"我确信，他已经回到了自己的星球。","t":[2238,3088]},{"it":"non del tutto.","zh":"因为在那天清晨，黎明时分，我没找到他的躯体。","t":[3088,4200]},{"it":"Ma so che è tornato sul suo pianeta, perché al sorgere del sole non ho ritrovato il corpo.","zh":"也许，它本来就没那么重……","t":[4200,9450]},{"it":"Non era un corpo tanto pesante...","zh":"现在，我喜欢在夜里聆听星星。","t":[9450,11538]},{"it":"E di notte mi piace ascoltare le stelle.","zh":"它们为我叮当作响，像五亿只铃铛。","t":[11538,14050]},{"it":"Sono come cinquecento milioni di sonagli...","zh":"可是有件事真奇怪。","t":[14050,16400]}]},{"id":"ch27p02","audio":true,"sents":[{"it":"C’è però un fatto importante.","zh":"我画了嘴套，把那张画交给了小王子。","t":[100,2000]},{"it":"Ho dimenticato di aggiungere la cinghia di cuoio alla museruola che ho disegnato per il piccolo principe!","zh":"然而我忘了给嘴套画上那条皮带。","t":[2000,7638]},{"it":"Non avrà potuto metterla alla pecora.","zh":"那他还怎么把嘴套套到小羊头上呢？","t":[7638,9938]},{"it":"Allora mi chiedo: “Che cosa è successo sul suo pianeta?","zh":"或许，小羊终究还是吃了那朵花？","t":[9938,13562]},{"it":"Forse la pecora ha mangiato la rosa...?”.","zh":"可我随即安慰自己——当然不会！","t":[13562,15663]}]},{"id":"ch27p03","audio":true,"sents":[{"it":"A volte mi dico: “Sicuramente no!","zh":"因为每天夜里，小王子都会用玻璃罩罩住他的花，又细心照看他的小羊。","t":[100,2612]},{"it":"Ogni sera il piccolo principe copre la rosa con la campana di vetro e tiene d’occhio la pecora...”.","zh":"于是我安心了，所有的星星都轻轻欢笑。","t":[2612,8225]},{"it":"Allora sono felice.","zh":"可有时我又想——只要有一次疏忽，就全完了！","t":[8225,9688]},{"it":"E tutte le stelle ridono dolcemente.","zh":"万一有天傍晚他忘了罩子，或是小羊夜里悄悄走开呢？","t":[9688,11800]}]},{"id":"ch27p04","audio":true,"sents":[{"it":"Altre volte mi dico: “Prima o poi capita a tutti di distrarsi!","zh":"那样的夜里，所有的铃铛都会哭泣……","t":[100,4312]},{"it":"Una sera ha dimenticato la campana di vetro, oppure la pecora è uscita senza far rumore durante la notte...”.","zh":"这里面藏着巨大的奥秘。","t":[4312,10738]},{"it":"Allora i sonagli si trasformano in lacrime!...","zh":"在宇宙中是和从前一样了，如果某处那头你们甚至从未见过的羊，已经吃掉了他的玫瑰。","t":[10738,13276]}]},{"id":"ch27p05","audio":true,"sents":[{"it":"È un mistero enorme.","zh":"仰望天空，问问自己——这事已经发生，还是尚未发生？","t":[100,1625]},{"it":"Per voi che come me amate il piccolo principe, tutto nell’universo cambia se da qualche parte, non si sa dove, una pecora che non conosciamo ha mangiato una rosa oppure no...","zh":"你会看见，周遭的一切都因这个问题的答案而改变。","t":[1625,11513]}]},{"id":"ch27p06","audio":true,"sents":[{"it":"Guardate il cielo.","zh":"没有哪个大人能明白，这有多重要！","t":[100,1300]},{"it":"Domandatevi: “La pecora ha mangiato o non ha mangiato il fiore?”.","zh":"这幅画里，有对我来说世界上最美丽、也最忧伤的风景。","t":[1300,5162]},{"it":"E vedrete come tutto è diverso...","zh":"这风景与上一页所画的是同一处。","t":[5162,6926]}]},{"id":"ch27p07","audio":true,"sents":[{"it":"E nessun adulto capirà mai quanto è importante!","zh":"我重画了一遍，好让你们看得更清楚。","t":[100,2900]}]},{"id":"ch27p08","audio":true,"sents":[{"it":"Questo è per me il paesaggio più bello e più triste del mondo.","zh":"小王子正是在这里降临地球，随后又消失。","t":[100,3662]},{"it":"È lo stesso paesaggio della pagina precedente, ma l’ho disegnato un’altra volta per mostrarvelo bene.","zh":"请仔细看看这景致。","t":[3662,9475]},{"it":"Qui il piccolo principe è apparso sulla Terra e qui è scomparso.","zh":"非洲沙漠时，能够认出他。","t":[9475,13387]}]},{"id":"ch27p09","audio":true,"sents":[{"it":"Guardate attentamente questo paesaggio per essere sicuri di riconoscerlo, se un giorno doveste viaggiare in Africa, nel deserto.","zh":"若你们真到了这里，我恳请你们，不要匆忙。","t":[100,7712]},{"it":"E se vi capitasse di passare di lì, vi scongiuro, non tirate dritto, fermatevi un poco sotto la stella!","zh":"就在此地、那颗星下，稍作停留！","t":[7712,14275]},{"it":"Se allora vi viene incontro un bambino, se ride, se ha i capelli d’oro, se non risponde alle domande, voi sapete chi è.","zh":"若有个小男孩走来对你笑，若他有一头金色头发，且对你的问话不予回答，你便知他是谁。","t":[14275,21488]},{"it":"Allora siate gentili, non lasciatemi alla mia tristezza: scrivetemi che è tornato...","zh":"那时，请行行好——别再让我悲伤，快写信告诉我：他回来了……","t":[21488,26500]}]}]}]};